//! Plugins, from tiny's side: what they are shown, and doing what they ask.
//!
//! The plugins themselves (loading them, calling into Lua, keeping a broken
//! one from hanging the window) are [`crate::plugins`]. This is the seam: a
//! [`Snapshot`] goes out before each call, and the [`Effect`]s that come back
//! are carried out here, once the plugin has returned. See that module's docs
//! for why a plugin never reaches into `App` directly.

use std::path::{Path, PathBuf};

use anyhow::anyhow;

use crate::files::media;
use crate::plugins::{Effect, Plugins, Snapshot};

use super::App;
use super::mode::Focus;
use super::preview::Preview;

impl App {
    /// Load every plugin in the plugins folder, replacing any loaded before.
    /// Called once at startup, and again by `*reload`.
    ///
    /// The first plugin that failed to load is named on the status line;
    /// tiny carries on without it either way.
    pub fn load_plugins(&mut self) {
        let Some(dir) = self.plugins_dir.clone() else {
            return;
        };
        self.plugins = Plugins::load(&dir, self.root());
        let asked = std::mem::take(&mut self.plugins.startup);
        self.apply_plugin_effects(asked, None);
        if let Some(first) = self.plugins.errors.first() {
            self.status = format!("plugin {first}");
        }
    }

    /// At startup, once the plugins are loaded: a file named on the command
    /// line was opened before there was anyone to tell.
    pub fn tell_plugins_what_is_open(&mut self) {
        if let (Focus::Editor, Preview::Buffer { path, .. }) = (self.focus, &self.preview) {
            let path = path.clone();
            self.plugin_event("open", &path);
        }
    }

    /// What a plugin can read: the project, and a file.
    ///
    /// For a command, the file is what the cursor is on and the one open in
    /// the right pane, whether or not it has the keyboard, so a command run
    /// from the browser can work on the note under the cursor. For an event,
    /// it is the file the event is about, which is not always that one:
    /// saving a folder saves every file in it.
    fn plugin_snapshot(&self, about: Option<&Path>) -> Snapshot {
        let (path, editing) = match about {
            Some(path) => (Some(path), self.buffers.get(path)),
            None => (self.selected_path(), self.active_buffer()),
        };
        Snapshot {
            root: self.root().to_string_lossy().into_owned(),
            path: path.map(|p| p.to_string_lossy().into_owned()),
            text: editing.map(|ed| ed.to_text()),
            cursor: editing.map(|ed| (ed.cursor_line + 1, ed.cursor_col + 1)),
        }
    }

    /// `*name`, for a command a plugin added. `None` when no plugin did, so
    /// the caller can say it is not a command at all.
    pub(super) fn run_plugin_command(
        &mut self,
        name: &str,
        args: &[String],
    ) -> Option<anyhow::Result<String>> {
        let snapshot = self.plugin_snapshot(None);
        let outcome = self.plugins.run(name, args, snapshot)?;
        Some(match outcome {
            Ok(effects) => {
                let said = effects.iter().any(|e| matches!(e, Effect::Status(_)));
                self.apply_plugin_effects(effects, None);
                // A plugin that said nothing still did something.
                Ok(if said {
                    String::new()
                } else {
                    format!("ran *{name}")
                })
            }
            Err(e) => Err(anyhow!("plugin {e}")),
        })
    }

    /// Tell the plugins that `path` was opened or saved, and do what they ask
    /// to that file.
    ///
    /// Not while doing what an earlier event asked: a hook on `open` that
    /// opens a file would otherwise hear about its own open, and open it
    /// again, until the stack ran out.
    pub(super) fn plugin_event(&mut self, event: &str, path: &Path) {
        if self.in_plugin_event || !self.plugins.listens(event) {
            return;
        }
        let snapshot = self.plugin_snapshot(Some(path));
        let (effects, errors) = self.plugins.fire(event, path, snapshot);
        self.in_plugin_event = true;
        self.apply_plugin_effects(effects, Some(path));
        self.in_plugin_event = false;
        if let Some(first) = errors.first() {
            self.status = format!("plugin {first}");
        }
    }

    /// Carry out what a plugin asked for, in the order it asked, to the file
    /// it was shown: `about`, or the one in the right pane.
    ///
    /// The edits go through the editor's own methods, so each is one step of
    /// undo and marks the file unsaved like any other change: a plugin can
    /// change a file, but never write one behind your back.
    fn apply_plugin_effects(&mut self, effects: Vec<Effect>, about: Option<&Path>) {
        for effect in effects {
            let buffer = match about {
                Some(path) => self.buffers.get_mut(path),
                None => self.active_buffer_mut(),
            };
            match effect {
                Effect::Status(message) => self.status = message,
                Effect::SetText(text) => {
                    // A formatter with nothing to change hands the text back
                    // as it was, and that is not an edit to save.
                    if let Some(ed) = buffer.filter(|ed| ed.to_text() != text) {
                        ed.replace_all(&text);
                    }
                }
                Effect::Insert(text) => {
                    if let Some(ed) = buffer {
                        ed.insert_text(&text);
                    }
                }
                Effect::Go(line, col) => {
                    if let Some(ed) = buffer {
                        ed.goto(line - 1, col - 1);
                    }
                }
                Effect::Open(path) => {
                    let path = PathBuf::from(path);
                    let path = if path.is_absolute() {
                        path
                    } else {
                        self.root().join(path)
                    };
                    self.open_path(&path);
                }
                // Already checked against a spare config when the plugin
                // asked, so this does not fail in practice; if it ever did,
                // the reason goes on the status line rather than nowhere.
                Effect::Set(name, value) => match self.config.set(&name, &value) {
                    Ok(()) => {
                        if let Some(warning) = self.apply_config() {
                            self.status = format!("plugin: {warning}");
                        }
                    }
                    Err(e) => self.status = format!("plugin: {e}"),
                },
            }
        }
    }

    /// The settings area's `Plugins` button: the folder, in the desktop's own
    /// file manager, made first if this is the first time, so there is
    /// somewhere to drop a plugin.
    pub(super) fn open_plugins_folder(&mut self) {
        let Some(dir) = self.plugins_dir.clone() else {
            self.status = "there is no config folder to keep plugins in".into();
            return;
        };
        if let Err(e) = std::fs::create_dir_all(&dir) {
            self.status = format!("cannot make {}: {e}", dir.display());
            return;
        }
        self.status = match media::open_with_desktop(&dir) {
            Ok(()) => format!(
                "{}: drop a .lua file in, then *reload ({} loaded)",
                dir.display(),
                self.plugins.loaded.len()
            ),
            Err(e) => format!("{e:#}; the folder is {}", dir.display()),
        };
    }
}

files.src/app/preview.rs:
//! What the cursor is on, and what the right pane becomes because of it.
//!
//! The single seam between the two panes. The tree does not know the preview
//! exists and the preview does not know about the tree; they are coupled only
//! by [`App::sync_preview`], which runs after every cursor move and decides
//! which [`Preview`] the right pane is showing.
//!
//! # The order of the questions
//!
//! [`App::load_file_preview`] asks them in an order that matters. An already
//! open buffer wins over anything on disk, so a file with unsaved edits is
//! never re-read out from under them. Then media, which is described rather
//! than opened. Then the size ceiling. Only then is the file read, and only
//! then is it decided to be text or binary: a file that is not valid UTF-8,
//! or that holds a zero byte, is reported as binary rather than opened as
//! mojibake.
//!
//! # Prose and code are different files
//!
//! [`TextKind`] is what separates "this reads better wrapped and rendered"
//! from "this is source". It decides line numbers, wrapping, and whether an
//! unfocused preview shows a rendered page or the text itself. It never
//! decides whether something can be edited: every text file opens into the
//! editor the same way.

use std::fs;
use std::path::{Path, PathBuf};

use crate::files::media;
use crate::files::size;
use crate::text::editor::Editor;

use super::App;
use super::parts::display_name;

/// How a text file wants to be shown.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TextKind {
    /// Rendered markdown.
    Markdown,
    /// Wrapped prose: notes, licenses, logs.
    Prose,
    /// Source. Straight into the editor, with line numbers.
    Code,
}

impl TextKind {
    /// Whether an *unfocused* preview of this shows it rendered rather than as
    /// source. Prose and markdown read better formatted when there is no
    /// cursor in them; code is already at its most readable as itself.
    ///
    /// Says nothing about editing. Every text file opens into the editor the
    /// same way, see [`App::focus_editor`].
    pub fn reads_first(self) -> bool {
        self != TextKind::Code
    }
}

/// Extensionless files that are prose by convention rather than by suffix.
///
/// Without this, `LICENSE` and `README` would be classified as code and open
/// straight into the editor with line numbers, which is not what anyone wants
/// from a license file.
pub(super) const PROSE_NAMES: &[&str] = &[
    // Not a spelling of ours: files really are named this, and matching one
    // is recognizing a name rather than writing a word.
    "LICENCE",
    "LICENSE",
    "COPYING",
    "NOTICE",
    "AUTHORS",
    "CONTRIBUTORS",
    "CHANGELOG",
    "CHANGES",
    "README",
    "TODO",
];

/// Decide how a text file should open.
///
/// Checked in order: markdown first (it is usually also in the prose list but
/// has a renderer of its own), then the configured prose extensions, then
/// anything else with an extension is code. Extensionless files fall back to
/// [`PROSE_NAMES`], and are code otherwise, which is the right default for a
/// `Makefile` or a shell script.
pub(super) fn text_kind(path: &Path, prose_exts: &[String]) -> TextKind {
    // Markdown is checked first: it is also in the prose list by default, but
    // it has a renderer of its own.
    if crate::text::markdown::is_markdown(path) {
        return TextKind::Markdown;
    }
    match path.extension().and_then(|e| e.to_str()) {
        Some(e) if prose_exts.iter().any(|p| p.eq_ignore_ascii_case(e)) => TextKind::Prose,
        Some(_) => TextKind::Code,
        None => {
            let name = path
                .file_name()
                .map(|n| n.to_string_lossy().to_uppercase())
                .unwrap_or_default();
            if PROSE_NAMES.contains(&name.as_str()) {
                TextKind::Prose
            } else {
                TextKind::Code
            }
        }
    }
}

/// What the preview pane is showing for the current selection.
#[derive(Debug, Clone, PartialEq, Default)]
pub enum Preview {
    /// A text file with an open buffer. Notes and prose render when the tree
    /// has focus and show raw source while being edited.
    Buffer {
        path: PathBuf,
        kind: TextKind,
    },
    /// A picture, a video, a PDF or a sound. Described in words, not drawn;
    /// Enter hands it to the desktop's own viewer. See [`crate::files::media`].
    Media {
        path: PathBuf,
        kind: media::Kind,
        size: u64,
        info: media::Info,
    },
    Directory {
        path: PathBuf,
        entries: usize,
    },
    Binary {
        path: PathBuf,
        size: u64,
        kind: String,
    },
    Unreadable(String),
    #[default]
    Empty,
}

/// Files larger than this are not loaded into the editor. Shown as a
/// "large file" preview instead: the undo model snapshots whole buffers, so
/// there is a real ceiling on what can be edited comfortably.
pub(super) const MAX_EDIT_BYTES: u64 = 8 * 1024 * 1024;

/// A file's text, if the editor would open it: small enough to edit, and
/// text rather than bytes that happen to decode. What a command that works
/// on a file reads it with when it is not open, so it agrees with opening it.
pub(super) fn read_editable(path: &Path) -> Option<String> {
    if fs::metadata(path).ok()?.len() > MAX_EDIT_BYTES {
        return None;
    }
    String::from_utf8(fs::read(path).ok()?)
        .ok()
        .filter(|text| !text.contains('\0'))
}

/// A human word for a non-text file, so the preview can say "archive" instead
/// of just "binary". PDFs and sound are not here: they are media, described
/// and opened by [`media`].
pub(super) fn binary_kind(path: &Path) -> &'static str {
    match path
        .extension()
        .and_then(|e| e.to_str())
        .map(str::to_lowercase)
        .as_deref()
    {
        Some("zip" | "gz" | "tar" | "xz" | "zst" | "7z") => "archive",
        Some("so" | "dll" | "dylib" | "o" | "a") => "object file",
        _ => "binary",
    }
}

impl Preview {
    /// The file or folder this shows, if it shows one.
    pub fn path(&self) -> Option<&Path> {
        match self {
            Preview::Buffer { path, .. }
            | Preview::Media { path, .. }
            | Preview::Directory { path, .. }
            | Preview::Binary { path, .. } => Some(path),
            Preview::Unreadable(_) | Preview::Empty => None,
        }
    }

    /// Follow a rename: what this shows, if it was `from` or inside it, is
    /// now in the same place under `to`.
    pub fn moved(&mut self, from: &Path, to: &Path) {
        if let Preview::Buffer { path, .. }
        | Preview::Media { path, .. }
        | Preview::Directory { path, .. }
        | Preview::Binary { path, .. } = self
            && path.starts_with(from)
        {
            *path = super::fileops::moved(path, from, to);
        }
    }
}

impl App {
    // ---- selection & preview ---------------------------------------------

    /// Re-flatten the tree and keep the cursor on the same *file*, not the same
    /// index.
    ///
    /// This is the difference between a refresh feeling stable and feeling like
    /// the list jumped: rows shift whenever anything above them is added,
    /// removed, expanded or collapsed, so the path is remembered and looked up
    /// again afterwards. Only when the file is genuinely gone does the index
    /// get clamped instead.
    pub(super) fn rebuild_rows(&mut self) {
        // Anything that rebuilds the rows can have changed what a folder
        // holds, and a remembered size is only worth having while it is true.
        self.size_cache.clear();
        let want = self.selected_path().map(Path::to_path_buf);
        self.rows = self.tree.flatten();
        if let Some(want) = want {
            if let Some(i) = self.rows.iter().position(|r| r.path == want) {
                self.selected = i;
            } else {
                self.selected = self.selected.min(self.rows.len().saturating_sub(1));
            }
        }
        // Whatever just changed about the tree, these rows are what is drawn
        // now, so this is what the disk should be compared against next.
        self.note_dirs();
        self.sync_preview();
    }

    /// Open every folder on the way to `path` and put the cursor on it.
    ///
    /// Necessary because the tree loads lazily: a file three directories deep
    /// does not exist as a row until its parents have been expanded. Returns
    /// false when the path is outside the project or could not be found, and
    /// still syncs the preview either way so the pane never shows something
    /// stale.
    ///
    /// A hidden path (`.env`, `.github/workflows/ci.yml`) is asked for by
    /// name, so hidden files are shown, the way `.` would show them: there
    /// is no row to put the cursor on otherwise, and opening the file is
    /// what was asked.
    pub(super) fn reveal(&mut self, path: &Path) -> bool {
        let root = self.tree.root_path().to_path_buf();
        // Two spellings of the same place. The tree's root has been through
        // `canonical`, and a path from somewhere else (git's idea of where a
        // file is, say) may not have been; or the other way round. A temp
        // directory under a symlink on macOS and an 8.3 short name such as
        // `RUNNER~1` on Windows both do this. Resolving *both* sides is the only
        // comparison that holds everywhere, and the part after the root is then
        // spelled the root's way, because that is how the rows are spelled.
        let rel: std::path::PathBuf = match path.strip_prefix(&root) {
            Ok(rel) => rel.to_path_buf(),
            Err(_) => {
                let resolved = crate::files::project::canonical(path);
                let root_resolved = crate::files::project::canonical(&root);
                let (Ok(p), Ok(r)) = (resolved, root_resolved) else {
                    return false;
                };
                match p.strip_prefix(&r) {
                    Ok(rel) => rel.to_path_buf(),
                    Err(_) => return false,
                }
            }
        };
        let path = root.join(&rel);
        let hidden = rel
            .components()
            .any(|c| c.as_os_str().to_string_lossy().starts_with('.'));
        if hidden && !self.tree.show_hidden() {
            self.tree.set_show_hidden(true);
            self.config.show_hidden = true;
        }
        let mut cur = root;
        let parts: Vec<_> = rel.components().collect();
        for part in parts.iter().take(parts.len().saturating_sub(1)) {
            cur.push(part);
            self.tree.expand(&cur);
        }
        self.rows = self.tree.flatten();
        // Opening folders on the way here read them; that reading is what the
        // disk watcher compares against from now on.
        self.note_dirs();
        match self.rows.iter().position(|r| r.path == path) {
            Some(i) => {
                self.selected = i;
                self.sync_preview();
                true
            }
            None => {
                self.sync_preview();
                false
            }
        }
    }

    /// Point the preview at whatever the cursor is now on, and reset its
    /// scroll.
    ///
    /// Measure what the cursor is on, for the end of the status line.
    ///
    /// A file is one `stat` and is measured every time, so saving one shows
    /// the new size immediately. A folder is a walk of everything under it,
    /// so it is measured once and remembered, see [`size`] for the budget
    /// that keeps the walk from being felt, and `size_cache` for how long the
    /// answer is kept.
    pub(super) fn note_size(&mut self) {
        let Some(row) = self.selected_row() else {
            self.cursor_size = None;
            return;
        };
        if !row.is_dir {
            self.cursor_size = size::of(&row.path);
            return;
        }
        let path = row.path.clone();
        if let Some(known) = self.size_cache.get(&path) {
            self.cursor_size = Some(*known);
            return;
        }
        let measured = size::of(&path);
        if let Some(size) = measured {
            self.size_cache.insert(path, size);
        }
        self.cursor_size = measured;
    }

    /// Called after every cursor move. This is the single seam between the two
    /// panes: the tree does not know about the preview and vice versa; they
    /// are coupled only here.
    ///
    /// A file only looked at in passing is let go of on the way past, so that
    /// arrowing down a folder of large files does not keep every one of them
    /// in memory, and on the watcher's list, for the rest of the session.
    pub(super) fn sync_preview(&mut self) {
        let leaving = match &self.preview {
            Preview::Buffer { path, .. } => Some(path.clone()),
            _ => None,
        };
        self.preview_selection();
        if let Some(path) = leaving {
            self.let_go_if_untouched(&path);
        }
    }

    /// Let go of the buffer for `path` when it holds nothing that reading the
    /// file again would not give back (see [`Editor::untouched`]) and no pane
    /// is showing it.
    fn let_go_if_untouched(&mut self, path: &Path) {
        let shown = self.preview.path() == Some(path)
            || self.split.as_ref().is_some_and(|s| {
                s.pinned
                    .iter()
                    .any(|(_, pane)| pane.preview.path() == Some(path))
            });
        if !shown && self.buffers.get(path).is_some_and(Editor::untouched) {
            self.buffers.remove(path);
        }
    }

    /// Make the preview whatever the browser's cursor is on.
    fn preview_selection(&mut self) {
        self.preview_scroll = 0;
        self.note_size();
        self.sync_pinned();
        let Some(row) = self.selected_row().cloned() else {
            self.preview = Preview::Empty;
            return;
        };
        if row.is_dir {
            if row.unreadable {
                self.preview = Preview::Unreadable(format!("cannot read {}", row.name));
                return;
            }
            let entries = fs::read_dir(&row.path).map(|d| d.count()).unwrap_or(0);
            self.preview = Preview::Directory {
                path: row.path,
                entries,
            };
            return;
        }
        self.preview = self.load_file_preview(&row.path);
    }

    /// Classify a file and, if it is text, open a buffer for it.
    ///
    /// Order matters. An already-open buffer wins over anything on disk, so a
    /// file with unsaved edits is never re-read out from under them. Then
    /// media, then the size ceiling, then a decode attempt: a file that is not
    /// valid UTF-8, or that contains a zero byte, is reported as binary rather
    /// than opened as mojibake.
    ///
    /// The `\0` check catches UTF-16 and similar, which decode as valid UTF-8
    /// often enough to slip past `from_utf8` alone.
    pub(super) fn load_file_preview(&mut self, path: &Path) -> Preview {
        // A buffer already open, possibly with unsaved edits, wins over disk.
        if self.buffers.contains_key(path) {
            return Preview::Buffer {
                path: path.to_path_buf(),
                kind: text_kind(path, &self.config.prose_extensions),
            };
        }
        let meta = match fs::metadata(path) {
            Ok(m) => m,
            Err(e) => return Preview::Unreadable(format!("{}: {e}", display_name(path))),
        };
        let size = meta.len();

        let kind = media::classify(path);
        if kind != media::Kind::Other {
            return Preview::Media {
                path: path.to_path_buf(),
                kind,
                size,
                info: media::probe(path, kind),
            };
        }
        if size > MAX_EDIT_BYTES {
            return Preview::Binary {
                path: path.to_path_buf(),
                size,
                kind: "large file".into(),
            };
        }
        match fs::read(path) {
            Ok(bytes) => match String::from_utf8(bytes) {
                Ok(text) if !text.contains('\0') => {
                    // A fresh buffer reports no edits, so the highlight cache
                    // would go on believing whatever it last knew about this
                    // path, which, after a rename or a delete, is a different
                    // file's contents.
                    self.highlight_cache.clear();
                    self.buffers.insert(
                        path.to_path_buf(),
                        Editor::from_str(path.to_path_buf(), &text),
                    );
                    // Stamped as it is read, so a write landing a moment later
                    // is a change and not the new normal, see `watch`.
                    self.note_file(path);
                    Preview::Buffer {
                        path: path.to_path_buf(),
                        kind: text_kind(path, &self.config.prose_extensions),
                    }
                }
                _ => Preview::Binary {
                    path: path.to_path_buf(),
                    size,
                    kind: binary_kind(path).into(),
                },
            },
            Err(e) => Preview::Unreadable(format!("{}: {e}", display_name(path))),
        }
    }

    /// Move the tree cursor by `delta` rows, clamped to the list. Only syncs
    /// the preview when the cursor actually moved, so holding a key at the end
    /// of the list does not re-read the same file repeatedly.
    pub(super) fn move_selection(&mut self, delta: isize) {
        if self.rows.is_empty() {
            return;
        }
        let last = self.rows.len() - 1;
        let next = (self.selected as isize + delta).clamp(0, last as isize) as usize;
        if next != self.selected {
            self.selected = next;
            self.sync_preview();
        }
    }

    pub(super) fn select_index(&mut self, i: usize) {
        let i = i.min(self.rows.len().saturating_sub(1));
        if i != self.selected {
            self.selected = i;
            self.sync_preview();
        }
    }
}

