    assert!(!bar.contains('\u{b7}'), "{bar}");
    assert!(
        !bar.contains("| ? help"),
        "the status already opens with `? for help`:\n{bar}"
    );
    assert!(
        !bar.contains(": commands"),
        "there is no colon key any more:\n{bar}"
    );
}

