    assert!(
        drawn_in(&mut app, Color::Green).trim().is_empty(),
        "and the shipped green is gone"
    );

    cursor_on(&mut app, "main.py");
    let hex = drawn_in(&mut app, Color::Rgb(0xff, 0x00, 0xaa));
