    assert_eq!(app.selected_row().unwrap().name, "notes");
    app.on_key(k(KeyCode::Right));
    assert!(app.selected_row().unwrap().expanded);
    assert_eq!(app.rows[2].name, "design.md");
    app.on_key(k(KeyCode::Left));
