    // Left goes up to the folder, and left again folds it.
    app.on_key(k(KeyCode::Left));
    assert_eq!(selected_name(&app), "many");
    app.on_key(k(KeyCode::Left));
    assert!(!app.rows[app.selected].expanded, "folded");
