    assert_eq!(app.status, "cut 1 line");
    assert!(text(&app, &path).starts_with("\n\ndef main():"));
    app.on_key(k(KeyCode::Down));
    app.on_key(k(KeyCode::Down));
    app.on_key(ctrl('v'));
    assert!(
        text(&app, &path).starts_with("\n\nimport utils\ndef main():"),
        "{}",
