//! The update question.
//!
//! Nothing here asks GitHub: the check's answer is put straight into
//! `update_found`, the way [`App::poll_update`] would on finding one. What is
//! tested is the part a person meets: when the question appears, what it
//! says, and what each answer does.

use super::*;

/// A newer tiny than any that will ever really exist, already found.
fn found(app: &mut App) {
    app.update_found = Some("9.9.9".into());
}

fn is_asking(app: &App) -> bool {
    matches!(&app.mode, Mode::Confirm(c) if matches!(c.kind, ConfirmKind::Update(_)))
}

#[test]
fn the_question_waits_until_you_are_in_the_browser() {
    let (_td, mut app) = fixture();
    select(&mut app, "main.py");
    app.on_key(k(KeyCode::Enter));
    found(&mut app);

    // Put while you were typing, the next letter (a `y`) would answer it.
    app.poll_update();
    assert!(!is_asking(&app), "not while a file has the keyboard");

    app.on_key(k(KeyCode::Esc));
    assert!(app.poll_update(), "the screen has something new on it");
    assert!(is_asking(&app), "and now it asks");
}

#[test]
fn the_question_is_a_window_in_the_words_it_was_asked_for() {
    let (_td, mut app) = fixture();
    found(&mut app);
    app.poll_update();
    let out = joined(&mut app);
    assert!(
        out.contains("tiny has been updated to version 9.9.9,"),
        "{out}"
    );
    assert!(out.contains("would you like to update now?"), "{out}");
    assert!(out.contains("y yes"), "{out}");
}

#[test]
fn yes_quits_and_leaves_the_version_to_be_installed() {
    let (_td, mut app) = fixture();
    found(&mut app);
    app.poll_update();
    app.on_key(ch('y'));
    assert!(app.should_quit, "tiny leaves, so the installer can run");
    assert_eq!(app.update_on_exit.as_deref(), Some("9.9.9"));
}

#[test]
fn yes_with_unsaved_work_asks_about_it_first() {
    let (_td, mut app) = fixture();
    select(&mut app, "main.py");
    app.on_key(k(KeyCode::Enter));
    type_str(&mut app, "x");
    app.on_key(k(KeyCode::Esc));
    found(&mut app);
    app.poll_update();
    app.on_key(ch('y'));

    assert!(!app.should_quit, "not with an unsaved file");
    let Mode::Confirm(c) = &app.mode else {
        panic!("expected the save question, got {:?}", app.mode)
    };
    assert!(c.message.contains("before updating"), "{}", c.message);

    // Taking that back takes the update back with it: a later Ctrl+Q is a
    // quit, not an install.
    app.on_key(k(KeyCode::Esc));
    assert!(!app.should_quit);
    assert_eq!(app.update_on_exit, None);
}

#[test]
fn saving_on_the_way_out_still_updates() {
    let (td, mut app) = fixture();
    select(&mut app, "main.py");
    app.on_key(k(KeyCode::Enter));
    type_str(&mut app, "x");
    app.on_key(k(KeyCode::Esc));
    found(&mut app);
    app.poll_update();
    app.on_key(ch('y'));
    app.on_key(ch('y'));

    assert!(app.should_quit);
    assert_eq!(app.update_on_exit.as_deref(), Some("9.9.9"));
    let saved = fs::read_to_string(td.path().join("src/main.py")).unwrap();
    assert!(saved.starts_with('x'), "the work was written first");
}

#[test]
fn no_keeps_this_version_and_does_not_ask_again() {
    let (_td, mut app) = fixture();
    found(&mut app);
    app.poll_update();
    app.on_key(ch('n'));
    assert!(matches!(app.mode, Mode::Normal));
    assert!(!app.should_quit);
    assert_eq!(app.update_on_exit, None);
    assert!(app.status.contains("*update"), "{}", app.status);

    app.poll_update();
    assert!(!is_asking(&app), "once a run is enough");
}

#[test]
fn any_other_key_leaves_the_question_standing() {
    let (_td, mut app) = fixture();
    found(&mut app);
    app.poll_update();
    let before = app.selected;
    app.on_key(ch('k'));
    assert!(is_asking(&app), "a stray key does not answer it");
    assert_eq!(app.selected, before, "or move anything behind it");
}

#[test]
fn the_update_command_puts_the_question_from_anywhere() {
    let (_td, mut app) = fixture();
    select(&mut app, "main.py");
    app.on_key(k(KeyCode::Enter));
    found(&mut app);
    command(&mut app, "update");
    assert!(is_asking(&app), "asked for, so asked, even from a file");
}

files.src/app/tests/watch.rs:
//! Files and folders changed by something other than tiny.
//!
//! Every test here plays the other program: it writes to the temp project
//! directly, then calls [`App::rescan_disk`] the way the event loop does when
//! nothing has been typed for half a second.
//!
//! Note what is *not* mocked: the clock, or the filesystem. The scan compares
//! real modification times and sizes, so a test that passed by accident would
//! have to have written the same bytes.

use super::*;

#[test]
fn a_file_changed_by_another_program_is_picked_up() {
    let (td, mut app) = fixture();
    select(&mut app, "README.md");
    assert!(joined(&mut app).contains("hello widget"), "the old text");
    assert!(
        !app.rescan_disk(),
        "nothing has changed, so there is nothing to redraw"
    );

    fs::write(td.path().join("README.md"), "# Fixture\n\ngoodbye widget\n").unwrap();

    assert!(app.rescan_disk(), "the file moved under us");
    let after = joined(&mut app);
    assert!(after.contains("goodbye widget"), "the new text is drawn");
    assert!(!after.contains("hello widget"), "the old text is gone");
    assert!(after.contains("changed on disk"), "and it says why");
}

#[test]
fn an_unsaved_buffer_is_never_overwritten_by_the_disk() {
    let (td, mut app) = fixture();
    select(&mut app, "README.md");
    app.focus_editor();
    type_str(&mut app, "MINE");
    assert!(app.is_dirty(&td.path().join("README.md")), "unsaved");

    fs::write(
        td.path().join("README.md"),
        "theirs, all of it, at length\n",
    )
    .unwrap();
    assert!(app.rescan_disk(), "the warning is worth a frame");

    let after = joined(&mut app);
    assert!(after.contains("MINE"), "what was typed is still here");
    assert!(!after.contains("theirs"), "the disk did not win");
    assert!(
        after.contains("unsaved copy"),
        "and the reader is told, in {after}"
    );
    assert!(
        !app.rescan_disk(),
        "told once: the stamp moved on even though the buffer did not"
    );
}

#[test]
fn saving_from_tiny_is_not_an_external_change() {
    let (_td, mut app) = fixture();
    select(&mut app, "README.md");
    app.focus_editor();
    type_str(&mut app, "x");
    app.save_active();

    // The file's modification time has just moved, and the scan will notice
    // that. What it must not do is call it a change: it reads the file, finds
    // the bytes it already has, and says nothing.
    assert!(!app.rescan_disk(), "our own write is not news");
    assert!(!joined(&mut app).contains("changed on disk"));
}

#[test]
fn a_file_another_program_creates_appears_in_the_tree() {
    let (td, mut app) = fixture();
    assert!(!joined(&mut app).contains("arrived.md"));

    fs::write(td.path().join("arrived.md"), "# New\n").unwrap();

    assert!(app.rescan_disk(), "the folder changed");
    assert!(joined(&mut app).contains("arrived.md"), "and it is listed");
}

#[test]
fn a_file_another_program_deletes_leaves_the_tree() {
    let (td, mut app) = fixture();
    select(&mut app, "design.md");
    assert!(joined(&mut app).contains("design.md"));

    fs::remove_file(td.path().join("notes/design.md")).unwrap();

    assert!(app.rescan_disk(), "the folder changed");
    assert!(
        !app.rows.iter().any(|r| r.name == "design.md"),
        "the row is gone from {:?}",
        app.rows.iter().map(|r| &r.name).collect::<Vec<_>>()
    );
    assert!(
        !app.buffers.contains_key(&td.path().join("notes/design.md")),
        "and so is the buffer, so the name is free if the file comes back"
    );
    assert!(
        joined(&mut app).contains("gone from disk"),
        "and the reader is told rather than left wondering"
    );
}

#[test]
fn a_change_hidden_by_a_coarse_clock_is_still_found() {
    // The Windows failure, reproduced anywhere. NTFS stamps a folder from the
    // system clock tick, about sixteen milliseconds, so a file deleted and made
    // again inside one tick leaves the folder's stamp exactly as the last scan
    // recorded it. `note_dirs` plays the coarse clock here: it records the
    // stamp as it is *after* the file came back, so the stamps agree and only
    // their age can say that something may be hiding behind them.
    let (td, mut app) = fixture();
    let path = td.path().join("README.md");
    select(&mut app, "README.md");

    fs::remove_file(&path).unwrap();
    assert!(app.rescan_disk(), "the delete is seen");
    fs::write(&path, "# back\n").unwrap();
    app.note_dirs();

    assert!(app.rescan_disk(), "a stamp this young is a reason to look");
    assert!(
        app.rows.iter().any(|r| r.name == "README.md"),
        "and looking finds it: {:?}",
        app.rows.iter().map(|r| &r.name).collect::<Vec<_>>()
    );
}

#[test]
fn a_young_stamp_with_nothing_behind_it_draws_nothing() {
    // Looking has a cost, and it must not be a frame: a folder re-read because
    // its stamp is young, and found the same, is not news.
    let (_td, mut app) = fixture();
    app.note_dirs();
    assert!(
        !app.rescan_disk(),
        "looked, found the same listing, said nothing"
    );
}

#[test]
fn losing_the_file_you_are_editing_takes_the_keyboard_out_of_it() {
    let (td, mut app) = fixture();
    select(&mut app, "design.md");
    app.focus_editor();
    assert_eq!(app.focus, Focus::Editor);

    fs::remove_file(td.path().join("notes/design.md")).unwrap();
    assert!(app.rescan_disk());

    assert_eq!(
        app.focus,
        Focus::Tree,
        "the cursor fell onto another file; typing must not land in it"
    );
}

#[test]
fn a_deleted_file_that_comes_back_is_read_again_rather_than_remembered() {
    let (td, mut app) = fixture();
    let path = td.path().join("README.md");
    select(&mut app, "README.md");
    assert!(joined(&mut app).contains("hello widget"));

    fs::remove_file(&path).unwrap();
    app.rescan_disk();
    fs::write(&path, "# Fixture\n\nsecond life\n").unwrap();
    app.rescan_disk();

    select(&mut app, "README.md");
    let after = joined(&mut app);
    assert!(after.contains("second life"), "read afresh, in {after}");
    assert!(!after.contains("hello widget"), "not the old buffer");
}

#[test]
fn a_reload_leaves_the_cursor_where_the_reader_left_it() {
    let (td, mut app) = fixture();
    let path = td.path().join("src/main.py");
    select(&mut app, "main.py");
    app.focus_editor();
    for _ in 0..3 {
        app.on_key(k(KeyCode::Down));
    }
    let (line, col) = {
        let ed = app.buffers.get(&path).unwrap();
        (ed.cursor_line, ed.cursor_col)
    };
    assert_eq!(line, 3, "three lines down");

    fs::write(
        &path,
        "import utils\n\n\ndef main():\n    return utils.load()\n\n\ndef other():\n    pass\n",
    )
    .unwrap();
    assert!(app.rescan_disk());

    let ed = app.buffers.get(&path).unwrap();
    assert_eq!((ed.cursor_line, ed.cursor_col), (line, col), "still there");
    assert_eq!(ed.line_count(), 9, "and the new lines arrived");
}

#[test]
fn a_reload_clamps_a_cursor_the_file_no_longer_reaches() {
    let (td, mut app) = fixture();
    let path = td.path().join("src/main.py");
    select(&mut app, "main.py");
    app.focus_editor();
    for _ in 0..4 {
        app.on_key(k(KeyCode::Down));
    }
    app.on_key(k(KeyCode::End));

    fs::write(&path, "one\n").unwrap();
    assert!(app.rescan_disk());

    let ed = app.buffers.get(&path).unwrap();
    assert_eq!(ed.cursor_line, 0, "the file has one line now");
    assert!(ed.cursor_col <= 3, "and the cursor is inside it");
}

#[test]
fn an_edit_elsewhere_does_not_move_the_file_being_read() {
    let (td, mut app) = fixture();
    select(&mut app, "design.md");
    app.preview_scroll = 2;

    // Something lands in the project, but not in the file on screen.
    fs::write(td.path().join("unrelated.md"), "# Elsewhere\n").unwrap();
    assert!(app.rescan_disk(), "the tree changed");

    assert_eq!(app.preview_scroll, 2, "the reader kept their place");
    assert_eq!(
        app.selected_path(),
        Some(td.path().join("notes/design.md").as_path()),
        "and the cursor did not move"
    );
}

#[test]
fn turning_auto_reload_off_leaves_the_disk_alone() {
    let (td, mut app) = fixture();
    app.config.auto_reload = false;
    select(&mut app, "README.md");

    fs::write(td.path().join("README.md"), "# Fixture\n\nchanged\n").unwrap();
    assert!(!app.rescan_disk(), "not asked to look");
    assert!(joined(&mut app).contains("hello widget"), "so it did not");

    // Asking still works, which is the whole point of being able to turn the
    // automatic half off.
    command(&mut app, "reload");
    assert!(joined(&mut app).contains("changed"), "asked, and it looked");
}

#[test]
fn a_file_that_stops_being_text_is_let_go_of() {
    let (td, mut app) = fixture();
    let path = td.path().join("README.md");
    select(&mut app, "README.md");

    fs::write(&path, [0x89u8, b'P', b'N', b'G', 0, 1, 2, 3, 4, 5]).unwrap();
    assert!(app.rescan_disk());

    assert!(
        !app.buffers.contains_key(&path),
        "a buffer holding text that is not the file's is worse than none"
    );
}

#[test]
fn typing_straight_after_a_save_is_not_taken_for_someone_elses_write() {
    // The save moves the file's stamp. Before tiny stamped its own writes,
    // the next scan saw a moved stamp on a buffer dirty again from new
    // typing, and warned about a change that was tiny's own.
    let (_td, mut app) = fixture();
    select(&mut app, "README.md");
    app.focus_editor();
    type_str(&mut app, "one ");
    app.on_key(ctrl('s'));
    type_str(&mut app, "two ");
    app.rescan_disk();
    assert!(
        !app.status.contains("changed on disk"),
        "our own save: {}",
        app.status
    );
}

#[test]
fn a_file_that_grows_past_what_the_editor_opens_is_let_go() {
    let (td, mut app) = fixture();
    let log = td.path().join("grows.txt");
    fs::write(&log, "small\n").unwrap();
    command(&mut app, "reload");
    select(&mut app, "grows.txt");
    assert!(app.buffers.contains_key(&log));

    let big = "x".repeat(1024) + "\n";
    fs::write(&log, big.repeat(9 * 1024)).unwrap();
    assert!(app.rescan_disk());
    assert!(
        !app.buffers.contains_key(&log),
        "not read whole on every scan from here on"
    );
    assert!(app.status.contains("too large"), "{}", app.status);
}

#[test]
fn a_file_only_looked_at_is_let_go_of_on_the_way_past() {
    let (td, mut app) = fixture();
    let readme = td.path().join("README.md");
    select(&mut app, "README.md");
    assert!(app.buffers.contains_key(&readme), "open while it is shown");
    select(&mut app, "main.py");
    assert!(
        !app.buffers.contains_key(&readme),
        "nothing of yours in it, so nothing is kept, or watched"
    );
    // Coming back reads it again, as it is now.
    fs::write(&readme, "# Fixture\n\nnewer\n").unwrap();
    select(&mut app, "README.md");
    assert!(joined(&mut app).contains("newer"));
}

#[test]
fn a_file_with_anything_of_yours_in_it_is_kept() {
    let (td, mut app) = fixture();
    let main = td.path().join("src/main.py");
    select(&mut app, "main.py");
    app.on_key(k(KeyCode::Enter));
    app.on_key(k(KeyCode::Down));
    app.on_key(k(KeyCode::Esc));
    select(&mut app, "README.md");
    assert_eq!(
        app.buffers.get(&main).map(|ed| ed.cursor_line),
        Some(1),
        "the place you left it is yours"
    );
}

#[test]
fn a_file_in_the_other_pane_is_kept_while_the_cursor_moves_on() {
    let (td, mut app) = fixture();
    select(&mut app, "README.md");
    app.on_key(k(KeyCode::Enter));
    app.on_key(ctrl('w'));
    app.on_key(k(KeyCode::Esc));
    select(&mut app, "main.py");
    assert!(app.buffers.contains_key(&td.path().join("README.md")));
}

#[test]
fn a_hidden_file_arriving_redraws_nothing() {
    // The folder's stamp moves, and it is read again, but the tree does not
    // show dotfiles, so the rows come out the same and no frame is spent.
    let (td, mut app) = fixture();
    select(&mut app, "README.md");
    fs::write(td.path().join(".swap"), "x").unwrap();
    assert!(!app.rescan_disk());
}

#[test]
fn a_hidden_file_arriving_in_the_folder_under_the_cursor_is_counted() {
    // Its count of entries takes in hidden ones, and it is on screen.
    let (td, mut app) = fixture();
    select(&mut app, "notes");
    let before = joined(&mut app);
    assert!(before.contains("1 entry"), "{before}");
    fs::write(td.path().join("notes/.swap"), "x").unwrap();
    assert!(app.rescan_disk());
    assert!(joined(&mut app).contains("2 entries"));
}

#[test]
fn a_picture_saved_over_itself_is_described_again() {
    // Written to a temporary name and renamed over the old one, the way many
    // programs save: the folder's listing comes out the same, the file not.
    let (td, mut app) = fixture();
    select(&mut app, "logo.png");
    let mut png = vec![0x89u8, b'P', b'N', b'G'];
    png.resize(5000, 0);
    fs::write(td.path().join("logo.tmp"), &png).unwrap();
    fs::rename(td.path().join("logo.tmp"), td.path().join("logo.png")).unwrap();
    assert!(app.rescan_disk(), "worth a frame");
    assert!(
        matches!(app.preview, Preview::Media { size: 5000, .. }),
        "{:?}",
        app.preview
    );
    assert_eq!(app.cursor_size.map(|s| s.bytes), Some(5000));
}

