//! Asking whether to install a newer tiny.
//!
//! The asking of GitHub is [`crate::update`]'s; this is the asking of the
//! person. The answer comes back on a thread whenever it comes back, and the
//! question is put only once they are somewhere it cannot be answered by
//! accident: in the browser, with nothing else open. Put while they were
//! typing, the very next letter of a sentence (a `y`) would answer it.
//!
//! `y` does not install anything here. It asks to quit, the way `Ctrl+Q`
//! does (saving first, or not, if anything is unsaved) and leaves the
//! version in [`App::update_on_exit`] for `main` to install once the terminal
//! is an ordinary terminal again.

use crate::update;

use super::App;
use super::mode::{Confirm, ConfirmKind, Focus, Mode, Window};

impl App {
    /// Ask GitHub, on a thread, whether a newer tiny is out.
    ///
    /// `by_hand` is `*update`: the answer is then reported whatever it is, and
    /// the question is put wherever you are, since you just asked for it.
    pub fn start_update_check(&mut self, by_hand: bool) {
        self.update_by_hand = by_hand;
        if self.update_check.is_none() {
            self.update_check = Some(update::Check::start());
        }
    }

    /// Collect the check's answer, and put the question if it is time to.
    /// Returns whether anything on screen changed. Called on the event loop's
    /// idle tick.
    pub fn poll_update(&mut self) -> bool {
        let mut changed = false;
        if let Some(answer) = self.update_check.as_ref().and_then(|c| c.finished()) {
            self.update_check = None;
            match answer {
                update::Answer::Newer(version) => self.update_found = Some(version),
                update::Answer::Newest if self.update_by_hand => {
                    self.status = format!("tiny {} is the newest", update::running());
                    changed = true;
                }
                // Not "the newest": nobody could be asked.
                update::Answer::Unknown if self.update_by_hand => {
                    self.status = format!(
                        "could not ask GitHub (offline, or no curl?); this is tiny {}",
                        update::running()
                    );
                    changed = true;
                }
                _ => {}
            }
        }
        if self.update_found.is_some() && self.can_ask_about_update() {
            let version = self.update_found.take().unwrap_or_default();
            self.offer_update(version);
            changed = true;
        }
        changed
    }

    /// Whether the question can go up now without catching a keystroke meant
    /// for something else.
    fn can_ask_about_update(&self) -> bool {
        matches!(self.mode, Mode::Normal)
            && (self.update_by_hand || (self.window == Window::Main && self.focus == Focus::Tree))
    }

    /// Put the question: the window the user asked for, in the words they
    /// asked for it.
    pub(super) fn offer_update(&mut self, version: String) {
        self.update_by_hand = false;
        self.mode = Mode::Confirm(Confirm {
            message: format!(
                "tiny has been updated to version {version}, would you like to update now?  (y/n)"
            ),
            kind: ConfirmKind::Update(version),
        });
    }

    /// `y`: leave, and install on the way out. Unsaved work gets the same
    /// question a quit gets, and taking that question back takes the update
    /// back with it.
    pub(super) fn begin_update(&mut self, version: String) {
        self.update_on_exit = Some(version);
        self.request_quit_to("updating");
    }

    /// `n`: not now. Not asked again this run; `*update` asks again on purpose.
    pub(super) fn decline_update(&mut self) {
        self.status = format!(
            "staying on {}, *update installs it later",
            update::running()
        );
    }

    /// `*update`: offer what is already known to be newer, or go and ask.
    pub(super) fn cmd_update(&mut self) -> anyhow::Result<String> {
        if let Some(version) = self.update_found.take() {
            self.offer_update(version);
            return Ok(String::new());
        }
        self.start_update_check(true);
        Ok("asking GitHub for a newer tiny".into())
    }
}

files.src/app/watch.rs:
//! Noticing that the disk has changed underneath us.
//!
//! Another program writes to a file tiny has open (a formatter, a build step,
//! a `git checkout`, the same project open in another window) and what is on
//! screen is now a picture of a file that no longer exists. This is the part
//! that fixes that: [`App::rescan_disk`] is called by the event loop whenever
//! it has been idle for a moment, and takes on whatever it finds.
//!
//! # Polling, not inotify
//!
//! There is no watcher and no background thread. The event loop waits on the
//! keyboard with a timeout instead of without one, and every time the timeout
//! expires it stats what is on screen: the directories the tree has read, and
//! the files there are buffers for. That is a handful of `stat` calls twice a
//! second (microseconds) against a dependency, a thread, a channel, and a
//! way to wake a blocking read, which is what a real watcher would cost.
//!
//! The trade is honest and worth naming: tiny is no longer a program that uses
//! *no* CPU while idle. It uses a rounding error of one.
//!
//! # Stamps are taken when the thing is read, not when it is scanned
//!
//! Every path is remembered as its modification time and size, and the stamp
//! is taken at the moment tiny reads the thing: [`App::note_file`] when a
//! buffer is opened, [`App::note_dirs`] whenever the tree has been rebuilt.
//!
//! Doing it at the first *scan* instead would leave a hole exactly the width
//! of the poll interval. Expand a folder, have a file land in it 200ms later,
//! and the first scan would record a modification time that already includes
//! the new file without ever having drawn it, so it would stay invisible
//! until something else changed in that folder.
//!
//! A path with no stamp at all is still recorded rather than acted on, which
//! is what keeps the scan after startup from deciding the whole project has
//! just changed.
//!
//! # Our own writes
//!
//! Saving from tiny moves the file's modification time as surely as anyone
//! else's write does, so the next scan sees a difference on a file we just
//! wrote ourselves. Rather than trying to remember which writes were ours,
//! a file whose stamp moved is read and compared: identical text is not a
//! change, and nothing on screen moves. It costs one read of a file small
//! enough to be open in an editor, and only on the scan after a write.
//!
//! # A stamp can be too young to trust
//!
//! Some filesystems keep coarse time: NTFS moves in steps of about sixteen
//! milliseconds, HFS+ in one second, FAT in two. Two changes inside one step
//! leave the same stamp, so a scan that fell between them would see nothing
//! for the second. A stamp younger than [`RACY`] is therefore a reason to look
//! rather than proof that nothing moved (a folder is re-read, a clean file
//! re-read and compared) and neither draws a frame unless something did.
//!
//! # Unsaved work is never overwritten
//!
//! A dirty buffer is never reloaded, whatever the disk says. It gets a line on
//! the status bar (once, because the stamp is updated either way) and keeps
//! the text the user typed. There is nowhere else for that text to live.

use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime};

use super::App;
use super::mode::Focus;
use super::parts::display_name;
use super::preview::{MAX_EDIT_BYTES, Preview};

/// What a path looked like when we last stat'd it: modification time and size.
///
/// `None` records that it could not be stat'd at all, which is a state like
/// any other: going from `Some` to `None` is a file being deleted, and going
/// the other way is one appearing.
type Stamp = Option<(SystemTime, u64)>;

/// Both halves of what tiny is looking at, as of the last scan.
///
/// Kept in the same shape for directories and files even though they are
/// checked for different things: a directory's modification time changes when
/// an entry is added or removed, a file's when its contents are written.
#[derive(Debug, Default)]
pub struct Watch {
    dirs: HashMap<PathBuf, Stamp>,
    files: HashMap<PathBuf, Stamp>,
}

/// Modification time and size, or `None` for anything that cannot be stat'd.
///
/// A filesystem with no usable modification time still gets its size watched,
/// which catches most edits, better than a stamp that can never differ.
fn stamp(path: &Path) -> Stamp {
    let m = fs::metadata(path).ok()?;
    Some((m.modified().unwrap_or(SystemTime::UNIX_EPOCH), m.len()))
}

/// How long after a change a stamp cannot be trusted to have caught the next.
///
/// This is git's "racily clean" problem (a timestamp is only as fine as the
/// clock that wrote it) and the answer is git's: a stamp too young to vouch
/// for itself is a reason to look. Two seconds covers the coarsest filesystem
/// anyone is likely to open a project on.
const RACY: Duration = Duration::from_secs(2);

/// Whether this stamp is too recent to prove nothing has changed since.
fn racy(stamp: &Stamp) -> bool {
    match stamp {
        Some((when, _)) => match SystemTime::now().duration_since(*when) {
            Ok(age) => age < RACY,
            // A time in the future (clock skew, a network share) cannot
            // vouch for anything either.
            Err(_) => true,
        },
        None => false,
    }
}

impl App {
    /// Remember what the directories on screen look like right now.
    ///
    /// Called from `rebuild_rows`, which runs after every structural change to
    /// the tree, so the stamps are always as fresh as the rows drawn from them.
    pub(super) fn note_dirs(&mut self) {
        self.watch.dirs = self
            .tree
            .loaded_dirs()
            .into_iter()
            .map(|d| {
                let now = stamp(&d);
                (d, now)
            })
            .collect();
    }

    /// Remember what a file looked like as it was read into a buffer.
    pub(super) fn note_file(&mut self, path: &Path) {
        let now = stamp(path);
        self.watch.files.insert(path.to_path_buf(), now);
    }

    /// Take on everything that changed on disk since the last look. Returns
    /// whether anything did, which is the event loop's cue to draw a frame.
    ///
    /// Directories first, so that a file which has just been deleted is
    /// already out of the tree by the time its buffer is dealt with.
    pub fn rescan_disk(&mut self) -> bool {
        if !self.config.auto_reload {
            return false;
        }
        let dirs = self.rescan_dirs();
        let files = self.rescan_files();
        dirs || files
    }

    /// Entries appearing in or disappearing from the directories on screen.
    ///
    /// One stat per directory the tree has read; collapsed ones are not read,
    /// so a project with a large unopened subtree costs nothing to watch. Only
    /// a directory whose stamp moved, or is too young to trust, is read again,
    /// and only a listing that came out different is redrawn: a build writing
    /// into a folder, or an editor saving through a temporary file, moves the
    /// stamp without changing a single row.
    fn rescan_dirs(&mut self) -> bool {
        let mut moved = Vec::new();
        let mut fresh: HashMap<PathBuf, Stamp> = HashMap::new();
        for dir in self.tree.loaded_dirs() {
            let now = stamp(&dir);
            if self
                .watch
                .dirs
                .get(&dir)
                .is_some_and(|was| *was != now || racy(was))
            {
                moved.push(dir.clone());
            }
            fresh.insert(dir, now);
        }
        self.watch.dirs = fresh;
        if moved.is_empty() {
            return false;
        }
        self.tree.refresh(&moved);
        if self.tree.flatten() == self.rows {
            // Nothing in the tree changed, but what is in it may have: a
            // hidden file, one in a folder opened and closed again, or the
            // very file under the cursor, written to a temporary name and
            // renamed over itself. A remembered size that takes in a moved
            // folder is forgotten, and what is under the cursor is looked at
            // again if it is in one, since its picture and size are drawn.
            self.size_cache
                .retain(|p, _| !moved.iter().any(|m| m.starts_with(p)));
            let touched = self.selected_row().is_some_and(|r| {
                if r.is_dir {
                    moved.iter().any(|m| m.starts_with(&r.path))
                } else {
                    r.path
                        .parent()
                        .is_some_and(|dir| moved.iter().any(|m| m == dir))
                }
            });
            if !touched {
                return false;
            }
            // Looking again is only news if it found something different,
            // and it is no reason to lose the place in what is being read.
            let (preview, size, scroll) =
                (self.preview.clone(), self.cursor_size, self.preview_scroll);
            self.sync_preview();
            self.preview_scroll = scroll;
            return self.preview != preview || self.cursor_size != size;
        }
        // `rebuild_rows` re-derives the preview, which resets its scroll. That
        // is right when the cursor has moved to another file and wrong when it
        // has not: a file being written elsewhere in the project should not
        // send you back to the top of the one you are reading.
        let was_on = self.selected_path().map(Path::to_path_buf);
        let scroll = self.preview_scroll;
        self.rebuild_rows();
        if was_on.as_deref() == self.selected_path() {
            self.preview_scroll = scroll;
            return true;
        }
        // The row the cursor was on has gone, and it has fallen onto a
        // neighbor. Said here, since a file only looked at has been let go of
        // on the way, and so has no buffer for `take_on_disk` to speak for;
        // one with unsaved edits does, and what that says comes after this.
        if let Some(gone) = was_on.filter(|p| !p.exists()) {
            self.status = format!("{} is gone from disk", display_name(&gone));
        }
        if self.focus == Focus::Editor {
            // Take the keyboard out of the file: otherwise the next thing
            // typed is typed into whichever file the cursor fell onto.
            self.focus_tree();
        }
        true
    }

    /// Open files whose contents have been written by someone else.
    fn rescan_files(&mut self) -> bool {
        let mut changed = false;
        for path in self.buffers.keys().cloned().collect::<Vec<_>>() {
            let now = stamp(&path);
            let dirty = self.is_dirty(&path);
            match self.watch.files.get(&path) {
                // Unchanged, unless the stamp is too young to prove it. Then a
                // clean buffer is read and compared, which costs one read and
                // says nothing when nothing changed. A dirty one is not: its
                // warning is given once per real change, not once per tick.
                Some(was) if *was == now && (dirty || !racy(was)) => continue,
                Some(_) => {
                    self.watch.files.insert(path.clone(), now);
                    changed |= self.take_on_disk(&path);
                }
                // Never seen before: this is the scan that learns it, not the
                // one that acts on it.
                None => {
                    self.watch.files.insert(path, now);
                }
            }
        }
        // A buffer can go away (a delete, or a rename moving it to another
        // key) and its stamp should not outlive it.
        let buffers = &self.buffers;
        self.watch.files.retain(|p, _| buffers.contains_key(p));
        changed
    }

    /// One file that is no longer what it was. Returns whether the screen
    /// needs redrawing.
    pub(super) fn take_on_disk(&mut self, path: &Path) -> bool {
        let name = display_name(path);
        let dirty = self.is_dirty(path);
        let fresh = match fs::metadata(path) {
            // Grown past what the editor opens (a log left open, say), and so
            // not read whole on every tick: classified afresh, like any file
            // too large to edit.
            Ok(meta) if meta.len() > MAX_EDIT_BYTES => Err("is too large to edit now"),
            _ => match fs::read(path) {
                // The same guard `load_file_preview` uses: a file that has
                // become binary is not text that happens to decode.
                Ok(bytes) => String::from_utf8(bytes)
                    .ok()
                    .filter(|text| !text.contains('\0'))
                    .ok_or("is no longer text"),
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => Err("is gone from disk"),
                // Busy rather than gone: Windows refuses a read while another
                // program is writing, for one. Not a change to act on, so the
                // stamp is forgotten and the next scan looks again.
                Err(_) => {
                    self.watch.files.insert(path.to_path_buf(), None);
                    return false;
                }
            },
        };

        let text = match fresh {
            Ok(text) => text,
            Err(what) if dirty => {
                // The buffer stays. There may be no row to put the cursor back
                // on, but the text is not lost: it is still listed on the way
                // out, and saving it there writes the file back.
                self.status = format!("{name} {what}; your unsaved copy is kept");
                return true;
            }
            Err(what) => {
                let showing = matches!(&self.preview, Preview::Buffer { path: p, .. } if p == path);
                self.buffers.remove(path);
                // Dropping the buffer is what lets the file be classified
                // afresh, since an open buffer always wins over disk.
                if showing {
                    self.sync_preview();
                } else {
                    self.sync_pinned();
                }
                self.status = format!("{name} {what}");
                return true;
            }
        };

        if dirty {
            self.status = format!("{name} changed on disk; your unsaved copy is what you see");
            return true;
        }
        let Some(editor) = self.buffers.get_mut(path) else {
            return false;
        };
        // Our own save, or someone else's write that changed nothing.
        if editor.to_text() == text {
            return false;
        }
        // Marks every line changed, so both panes' saved highlighting of this
        // file starts again, wherever it is drawn.
        editor.reload_from(&text);
        self.status = format!("{name} changed on disk, reloaded");
        true
    }

    /// Bring every clean buffer up to date with its file, in place, the way
    /// a change the watcher noticed is taken on: the cursor and the scroll
    /// stay where they were. One that is gone or no longer text is dropped,
    /// and a dirty one is left alone, its edits being worth more than the
    /// disk's copy. For `*reload`, and after a replace across the project.
    pub(super) fn reread_clean_buffers(&mut self) {
        let clean: Vec<PathBuf> = self
            .buffers
            .iter()
            .filter(|(_, ed)| !ed.dirty)
            .map(|(path, _)| path.clone())
            .collect();
        for path in clean {
            // Stamped first, so a file too busy to read keeps the mark that
            // has the next scan try it again.
            self.note_file(&path);
            self.take_on_disk(&path);
        }
    }
}

files.src/clipboard.rs:
//! The clipboard for text: the system's, wherever tiny can reach it, and a
//! copy of its own.
//!
//! Text copied in a file goes to the system's clipboard, so it pastes into
//! anything, and tiny keeps it as well, for two reasons. A machine without a
//! way in (a server over SSH, a desktop without the clipboard programs) still
//! copies and pastes inside tiny. And tiny remembers what *kind* of text it
//! was: copying with nothing selected takes whole lines, which paste back in
//! above the line rather than into the middle of it, and the system's
//! clipboard has no way to carry that.
//!
//! # Reaching the system's
//!
//! There is no one way. Each system has its own, tried in turn:
//!
//! - **Windows:** its own clipboard, through the Windows API.
//! - **macOS:** `pbcopy` and `pbpaste`, which every Mac has.
//! - **Linux and the BSDs:** `wl-copy` and `wl-paste` under Wayland, `xclip`
//!   or `xsel` under X. Whichever is installed.
//! - **Anywhere else**, including over SSH: the terminal itself, with the
//!   escape sequence (OSC 52) that asks it to set the clipboard. Most
//!   terminals do it (kitty, WezTerm, foot, Alacritty, iTerm2, Windows
//!   Terminal, tmux with `set-clipboard on`) and the rest ignore it. There is
//!   no reading the clipboard back this way, so a paste there is tiny's own
//!   copy, or the terminal's paste key.
//!
//! The tests never touch any of it: a clipboard made with `system` false is
//! tiny's own alone, so running them does not overwrite what the person
//! running them had copied.

use std::io::Write;

#[derive(Debug, Default)]
pub struct Clipboard {
    /// The last text copied in tiny, and whether it was whole lines.
    last: Option<(String, bool)>,
    /// Whether to use the system's clipboard at all.
    system: bool,
}

impl Clipboard {
    pub fn new(system: bool) -> Self {
        Self { last: None, system }
    }

    /// Copy `text`, which is whole lines when `whole_lines` is set.
    pub fn copy(&mut self, text: String, whole_lines: bool) {
        if self.system && !set_system(&text) {
            osc52(&text);
        }
        self.last = Some((text, whole_lines));
    }

    /// What a paste puts in: the system's clipboard when it can be read and
    /// holds something, otherwise tiny's own copy. The flag says whether it
    /// is whole lines, which it is only when it is exactly what tiny copied
    /// as whole lines.
    pub fn paste(&self) -> Option<(String, bool)> {
        let system = self
            .system
            .then(get_system)
            .flatten()
            .filter(|t| !t.is_empty());
        match system {
            Some(text) => {
                let whole = self.whole_lines(&text);
                Some((text, whole))
            }
            None => self.last.clone(),
        }
    }

    /// Whether `text`, pasted by the terminal or read from the system, is
    /// the whole lines tiny last copied. Line breaks are compared as `\n`,
    /// since a Windows clipboard gives them back as `\r\n`.
    pub fn whole_lines(&self, text: &str) -> bool {
        match &self.last {
            Some((last, true)) => {
                let plain = |s: &str| s.replace("\r\n", "\n");
                plain(last) == plain(text)
            }
            _ => false,
        }
    }
}

/// Set the system's clipboard to `text`. Returns whether something took it.
fn set_system(text: &str) -> bool {
    #[cfg(windows)]
    {
        win::set(text)
    }
    #[cfg(not(windows))]
    {
        programs::all()
            .iter()
            .any(|(copy, _)| programs::run_with_input(copy, text))
    }
}

/// The system's clipboard, when it can be read.
fn get_system() -> Option<String> {
    #[cfg(windows)]
    {
        win::get()
    }
    #[cfg(not(windows))]
    {
        programs::all()
            .iter()
            .find_map(|(_, paste)| programs::run_for_output(paste))
    }
}

/// Everything but Windows: a program for each way in, see the module docs.
#[cfg(not(windows))]
mod programs {
    use std::io::{Read, Write};
    use std::process::{Child, Command, Stdio};
    use std::time::{Duration, Instant};

    /// How long a clipboard program gets to answer. One that hangs (a
    /// Wayland compositor that has gone, an X server across a dead SSH link)
    /// costs this much once, rather than freezing tiny.
    const PATIENCE: Duration = Duration::from_millis(1500);

    /// The clipboard programs worth trying here, each as the command that copies
    /// and the one that pastes, most likely first.
    pub fn all() -> Vec<(&'static [&'static str], &'static [&'static str])> {
        if cfg!(target_os = "macos") {
            return vec![(&["pbcopy"], &["pbpaste"])];
        }
        let mut out: Vec<(&'static [&'static str], &'static [&'static str])> = Vec::new();
        if std::env::var_os("WAYLAND_DISPLAY").is_some() {
            out.push((
                &["wl-copy"],
                &["wl-paste", "--no-newline", "--type", "text"],
            ));
        }
        if std::env::var_os("DISPLAY").is_some() {
            out.push((
                &["xclip", "-selection", "clipboard", "-in"],
                &["xclip", "-selection", "clipboard", "-out"],
            ));
            out.push((
                &["xsel", "--clipboard", "--input"],
                &["xsel", "--clipboard", "--output"],
            ));
        }
        out
    }

    /// Run `argv` with `text` on its standard input. Whether it ran and said
    /// yes.
    ///
    /// Its output goes nowhere rather than to a pipe: `xclip` and `wl-copy`
    /// leave a process behind to hand the text to whoever pastes it, and a pipe
    /// it held open would be a pipe never closed.
    pub fn run_with_input(argv: &[&str], text: &str) -> bool {
        let Ok(mut child) = Command::new(argv[0])
            .args(&argv[1..])
            .stdin(Stdio::piped())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
        else {
            return false;
        };
        if let Some(mut stdin) = child.stdin.take() {
            let _ = stdin.write_all(text.as_bytes());
        }
        matches!(wait(&mut child), Some(true))
    }

    /// Run `argv` and read what it prints, when it says yes in time.
    pub fn run_for_output(argv: &[&str]) -> Option<String> {
        let mut child = Command::new(argv[0])
            .args(&argv[1..])
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::null())
            .spawn()
            .ok()?;
        // Read on a thread of its own: a large clipboard fills the pipe, and a
        // program waiting for its pipe to be read never exits.
        let mut stdout = child.stdout.take()?;
        let reader = std::thread::spawn(move || {
            let mut bytes = Vec::new();
            let _ = stdout.read_to_end(&mut bytes);
            bytes
        });
        if wait(&mut child) != Some(true) {
            return None;
        }
        String::from_utf8(reader.join().ok()?).ok()
    }

    /// Wait for `child`, at most [`PATIENCE`]. Whether it succeeded; `None` when
    /// it took too long and was stopped.
    fn wait(child: &mut Child) -> Option<bool> {
        let start = Instant::now();
        loop {
            match child.try_wait() {
                Ok(Some(status)) => return Some(status.success()),
                Ok(None) if start.elapsed() < PATIENCE => {
                    std::thread::sleep(Duration::from_millis(5));
                }
                _ => {
                    let _ = child.kill();
                    let _ = child.wait();
                    return None;
                }
            }
        }
    }
}

/// Ask the terminal to set the clipboard, see the module docs.
///
/// Written straight to the terminal between frames: it moves no cursor and
/// draws nothing, so the screen is none the wiser.
fn osc52(text: &str) {
    let seq = format!("\x1b]52;c;{}\x07", base64(text.as_bytes()));
    let mut out = std::io::stdout();
    let _ = out.write_all(seq.as_bytes());
    let _ = out.flush();
}

/// Standard base64, with padding: what OSC 52 carries.
fn base64(bytes: &[u8]) -> String {
    const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for chunk in bytes.chunks(3) {
        let n = chunk
            .iter()
            .enumerate()
            .fold(0u32, |n, (i, b)| n | (u32::from(*b) << (16 - 8 * i)));
        for i in 0..4 {
            if i <= chunk.len() {
                out.push(ALPHABET[((n >> (18 - 6 * i)) & 63) as usize] as char);
            } else {
                out.push('=');
            }
        }
    }
    out
}

/// The Windows clipboard, through the API: text in UTF-16, the one form
/// every Windows program reads.
#[cfg(windows)]
mod win {
    use std::ptr::null_mut;
    use windows_sys::Win32::Foundation::GlobalFree;
    use windows_sys::Win32::System::DataExchange::{
        CloseClipboard, EmptyClipboard, GetClipboardData, IsClipboardFormatAvailable,
        OpenClipboard, SetClipboardData,
    };
    use windows_sys::Win32::System::Memory::{
        GMEM_MOVEABLE, GlobalAlloc, GlobalLock, GlobalUnlock,
    };
    use windows_sys::Win32::System::Ole::CF_UNICODETEXT;

    pub fn set(text: &str) -> bool {
        // Windows' own line break, and the terminating zero it expects.
        let wide: Vec<u16> = text
            .replace("\r\n", "\n")
            .replace('\n', "\r\n")
            .encode_utf16()
            .chain(Some(0))
            .collect();
        // SAFETY: the clipboard is opened and closed on every path, and the
        // memory handed to it is ours until `SetClipboardData` takes it.
        unsafe {
            if OpenClipboard(null_mut()) == 0 {
                return false;
            }
            EmptyClipboard();
            let memory = GlobalAlloc(GMEM_MOVEABLE, wide.len() * 2);
            let mut done = false;
            if !memory.is_null() {
                let to = GlobalLock(memory).cast::<u16>();
                if !to.is_null() {
                    std::ptr::copy_nonoverlapping(wide.as_ptr(), to, wide.len());
                    GlobalUnlock(memory);
                    done = !SetClipboardData(u32::from(CF_UNICODETEXT), memory).is_null();
                }
                if !done {
                    GlobalFree(memory);
                }
            }
            CloseClipboard();
            done
        }
    }

    pub fn get() -> Option<String> {
        // SAFETY: as above; the data is only read while it is locked, and
        // only up to its terminating zero.
        unsafe {
            if IsClipboardFormatAvailable(u32::from(CF_UNICODETEXT)) == 0
                || OpenClipboard(null_mut()) == 0
            {
                return None;
            }
            let memory = GetClipboardData(u32::from(CF_UNICODETEXT));
            let mut text = None;
            if !memory.is_null() {
                let from = GlobalLock(memory).cast::<u16>();
                if !from.is_null() {
                    let mut n = 0;
                    while *from.add(n) != 0 {
                        n += 1;
                    }
                    let wide = std::slice::from_raw_parts(from, n);
                    text = Some(String::from_utf16_lossy(wide).replace("\r\n", "\n"));
                    GlobalUnlock(memory);
                }
            }
            CloseClipboard();
            text
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn base64_is_the_standard_kind() {
        for (plain, coded) in [
            ("", ""),
            ("f", "Zg=="),
            ("fo", "Zm8="),
            ("foo", "Zm9v"),
            ("foob", "Zm9vYg=="),
            ("hello, world", "aGVsbG8sIHdvcmxk"),
            ("é", "w6k="),
        ] {
            assert_eq!(base64(plain.as_bytes()), coded, "{plain:?}");
        }
    }

    #[test]
    fn without_the_system_tiny_keeps_its_own_copy() {
        let mut clip = Clipboard::new(false);
        assert_eq!(clip.paste(), None, "nothing copied yet");
        clip.copy("a line\n".into(), true);
        assert_eq!(clip.paste(), Some(("a line\n".to_string(), true)));
        clip.copy("a word".into(), false);
        assert_eq!(clip.paste(), Some(("a word".to_string(), false)));
    }

    #[test]
    fn whole_lines_are_known_again_whatever_their_line_breaks() {
        let mut clip = Clipboard::new(false);
        clip.copy("one\ntwo\n".into(), true);
        assert!(
            clip.whole_lines("one\r\ntwo\r\n"),
            "as Windows hands it back"
        );
        assert!(!clip.whole_lines("one\ntwo"), "not quite the same text");
        clip.copy("one\ntwo\n".into(), false);
        assert!(!clip.whole_lines("one\ntwo\n"), "copied as a selection");
    }
}

