//! Turning git's output into values, with no process anywhere near it.
//!
//! Every function here is text in and values out, which is the whole point:
//! the cases that are awkward to produce in a real repository (a rename whose
//! two halves arrive as separate records, a conflicted file, a diff with no
//! trailing newline) are tested as strings.

use super::{Branch, Change, Code, Diff, DiffLine, LineKind, Status};

/// Parse `git status --porcelain=v1 --branch -z`.
///
/// The `-z` form is the one worth parsing: records are NUL-separated and paths
/// are never quoted or escaped, so a file with a space, a quote or a newline in
/// its name arrives intact. The readable form escapes those, and unescaping it
/// correctly is more work than this.
///
/// Each record is `XY <path>`, where `X` is what the index has and `Y` is what
/// the working tree has. A rename or copy spends two records: the new name,
/// then the old one.
pub fn status(out: &str) -> Status {
    let mut status = Status::default();
    let mut records = out.split('\0').filter(|r| !r.is_empty());
    while let Some(record) = records.next() {
        if let Some(head) = record.strip_prefix("## ") {
            status.branch = branch(head);
            continue;
        }
        let (codes, path) = record.split_at(record.len().min(2));
        let path = path.trim_start().to_string();
        let mut chars = codes.chars();
        let (x, y) = (chars.next().unwrap_or(' '), chars.next().unwrap_or(' '));

        // A rename or a copy is followed by the name it came from, in a record
        // of its own. Take it now, whichever side the change lands on.
        let from = if x == 'R' || x == 'C' || y == 'R' || y == 'C' {
            records.next().map(str::to_string)
        } else {
            None
        };

        // Untracked and ignored are both spelled with a `?` or a `!` twice
        // over, and neither is a change to the index.
        if x == '?' || y == '?' {
            status.unstaged.push(Change {
                code: Code::Untracked,
                path,
                from: None,
            });
            continue;
        }
        if x == '!' || y == '!' {
            continue;
        }
        // Unmerged, in all its spellings: either side is a `U`, or both sides
        // agree on a letter that only a conflict produces.
        if x == 'U' || y == 'U' || (x == y && (x == 'A' || x == 'D')) {
            status.unstaged.push(Change {
                code: Code::Conflict,
                path,
                from,
            });
            continue;
        }
        if let Some(code) = code_of(x) {
            status.staged.push(Change {
                code,
                path: path.clone(),
                from: from.clone(),
            });
        }
        if let Some(code) = code_of(y) {
            status.unstaged.push(Change { code, path, from });
        }
    }
    status
}

/// The `## main...origin/main [ahead 1, behind 2]` line.
///
/// Everything after the name is optional: a branch with no upstream has no
/// `...`, and one that is level has no bracket.
fn branch(head: &str) -> Branch {
    let (names, counts) = match head.split_once(" [") {
        Some((n, c)) => (n, c.trim_end_matches(']')),
        None => (head, ""),
    };
    let (name, upstream) = match names.split_once("...") {
        Some((n, u)) => (n, Some(u.to_string())),
        None => (names, None),
    };
    let count = |word: &str| -> usize {
        counts
            .split(", ")
            .find_map(|part| part.strip_prefix(word)?.trim().parse().ok())
            .unwrap_or(0)
    };
    Branch {
        // A repository with no commits yet says `No commits yet on main`.
        name: name.rsplit(' ').next().unwrap_or(name).to_string(),
        upstream,
        ahead: count("ahead "),
        behind: count("behind "),
    }
}

/// One status letter, or `None` for "nothing on this side".
fn code_of(c: char) -> Option<Code> {
    match c {
        'A' => Some(Code::Added),
        'M' => Some(Code::Modified),
        'D' => Some(Code::Deleted),
        'R' => Some(Code::Renamed),
        'C' => Some(Code::Copied),
        'T' => Some(Code::Modified), // a type change is a change
        _ => None,
    }
}

/// Parse a unified diff into two columns that stay level with each other.
///
/// With `-U1000000` git emits the whole file as one hunk, so this walks a
/// complete before and after rather than fragments. A removed line puts a real
/// line on the left and a [`LineKind::Filler`] on the right; an added line does
/// the reverse; a context line goes on both. The two sides therefore always
/// have the same length, which is what makes reading across them mean anything.
///
/// Runs of removals followed by additions (the ordinary shape of an edit) are
/// paired up rather than stacked, so a changed line sits opposite the line it
/// replaced instead of below a column of blanks.
pub fn diff(out: &str) -> Diff {
    let mut diff = Diff::default();
    let mut removed: Vec<String> = Vec::new();
    let mut added: Vec<String> = Vec::new();
    let mut in_hunk = false;

    // Nothing has changed: `git diff` says nothing at all.
    if out.trim().is_empty() {
        return diff;
    }

    let flush = |diff: &mut Diff, removed: &mut Vec<String>, added: &mut Vec<String>| {
        for i in 0..removed.len().max(added.len()) {
            diff.before.push(match removed.get(i) {
                Some(text) => DiffLine {
                    text: text.clone(),
                    kind: LineKind::Changed,
                },
                None => filler(),
            });
            diff.after.push(match added.get(i) {
                Some(text) => DiffLine {
                    text: text.clone(),
                    kind: LineKind::Changed,
                },
                None => filler(),
            });
        }
        removed.clear();
        added.clear();
    };

    for line in out.lines() {
        if line.starts_with("@@") {
            in_hunk = true;
            continue;
        }
        if !in_hunk {
            continue;
        }
        match line.as_bytes().first() {
            Some(b'-') => removed.push(line[1..].to_string()),
            Some(b'+') => added.push(line[1..].to_string()),
            // `\ No newline at end of file` is a note about the line above, not
            // a line of the file.
            Some(b'\\') => {}
            _ => {
                flush(&mut diff, &mut removed, &mut added);
                let text = line.strip_prefix(' ').unwrap_or(line).to_string();
                diff.before.push(DiffLine {
                    text: text.clone(),
                    kind: LineKind::Same,
                });
                diff.after.push(DiffLine {
                    text,
                    kind: LineKind::Same,
                });
            }
        }
    }
    flush(&mut diff, &mut removed, &mut added);
    diff
}

/// A file git has never seen: nothing on the left, all of it on the right.
pub fn whole_file_added(text: &str) -> Diff {
    let mut diff = Diff::default();
    for line in text.lines() {
        diff.before.push(filler());
        diff.after.push(DiffLine {
            text: line.to_string(),
            kind: LineKind::Changed,
        });
    }
    diff
}

fn filler() -> DiffLine {
    DiffLine {
        text: String::new(),
        kind: LineKind::Filler,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Records are NUL-separated, so a fixture reads better written with `\0`
    /// spelled out.
    fn z(records: &[&str]) -> String {
        records.iter().map(|r| format!("{r}\0")).collect::<String>()
    }

    #[test]
    fn a_branch_line_gives_up_its_name_and_its_distance() {
        let b = branch("main...origin/main [ahead 2, behind 1]");
        assert_eq!(b.name, "main");
        assert_eq!(b.upstream.as_deref(), Some("origin/main"));
        assert_eq!((b.ahead, b.behind), (2, 1));

        let plain = branch("wip");
        assert_eq!(plain.name, "wip");
        assert_eq!(plain.upstream, None);
        assert_eq!((plain.ahead, plain.behind), (0, 0));

        let one_way = branch("main...origin/main [behind 3]");
        assert_eq!((one_way.ahead, one_way.behind), (0, 3));
    }

    #[test]
    fn a_fresh_repository_still_names_its_branch() {
        // Before the first commit git writes the whole sentence out.
        assert_eq!(branch("No commits yet on main").name, "main");
    }

    #[test]
    fn the_two_columns_are_two_different_questions() {
        // `MM` is a file changed, staged, and then changed again.
        let s = status(&z(&[
            "## main",
            "MM both.rs",
            "M  staged.rs",
            " M dirty.rs",
        ]));
        assert_eq!(
            s.staged.iter().map(|c| c.path.as_str()).collect::<Vec<_>>(),
            ["both.rs", "staged.rs"]
        );
        assert_eq!(
            s.unstaged
                .iter()
                .map(|c| c.path.as_str())
                .collect::<Vec<_>>(),
            ["both.rs", "dirty.rs"]
        );
    }

    #[test]
    fn untracked_is_its_own_letter_and_never_staged() {
        let s = status(&z(&["## main", "?? scratch.txt"]));
        assert!(s.staged.is_empty());
        assert_eq!(s.unstaged[0].code, Code::Untracked);
        assert_eq!(s.unstaged[0].code.letter(), 'U');
    }

    #[test]
    fn an_ignored_file_is_not_a_change() {
        let s = status(&z(&["## main", "!! target/"]));
        assert!(s.is_clean(), "ignored files are not news");
    }

    #[test]
    fn a_rename_carries_the_name_it_came_from() {
        let s = status(&z(&["## main", "R  new.md", "old.md"]));
        assert_eq!(s.staged[0].code, Code::Renamed);
        assert_eq!(s.staged[0].path, "new.md");
        assert_eq!(s.staged[0].from.as_deref(), Some("old.md"));
        assert_eq!(s.staged[0].label("→"), "old.md → new.md");
    }

    #[test]
    fn a_path_with_a_space_in_it_survives() {
        let s = status(&z(&["## main", " M my notes.md"]));
        assert_eq!(s.unstaged[0].path, "my notes.md");
    }

    #[test]
    fn a_conflict_is_neither_staged_nor_a_plain_change() {
        for record in ["UU both.rs", "AA both.rs", "DD both.rs"] {
            let s = status(&z(&["## main", record]));
            assert!(s.staged.is_empty(), "{record} is not ready to commit");
            assert_eq!(s.unstaged[0].code, Code::Conflict, "{record}");
        }
    }

    #[test]
    fn a_diff_becomes_two_columns_of_the_same_height() {
        let out = "\
diff --git a/a.txt b/a.txt
index 111..222 100644
--- a/a.txt
+++ b/a.txt
@@ -1,3 +1,3 @@
 first
-second
+SECOND
 third
";
        let d = diff(out);
        assert_eq!(d.before.len(), d.after.len(), "the sides stay level");
        assert_eq!(
            d.before.iter().map(|l| l.text.as_str()).collect::<Vec<_>>(),
            ["first", "second", "third"]
        );
        assert_eq!(
            d.after.iter().map(|l| l.text.as_str()).collect::<Vec<_>>(),
            ["first", "SECOND", "third"]
        );
        assert_eq!(d.before[1].kind, LineKind::Changed);
        assert_eq!(d.before[0].kind, LineKind::Same);
    }

    #[test]
    fn a_line_with_no_opposite_gets_a_blank_to_face() {
        let out = "\
@@ -1,1 +1,3 @@
 kept
+one
+two
";
        let d = diff(out);
        assert_eq!(d.before.len(), 3);
        assert_eq!(d.before[1].kind, LineKind::Filler);
        assert_eq!(d.before[2].kind, LineKind::Filler);
        assert_eq!(d.after[2].text, "two");
    }

    #[test]
    fn the_no_newline_note_is_not_a_line_of_the_file() {
        let out = "@@ -1 +1 @@\n-old\n\\ No newline at end of file\n+new\n";
        let d = diff(out);
        assert_eq!(d.before.len(), 1, "one line each side");
        assert_eq!(d.before[0].text, "old");
        assert_eq!(d.after[0].text, "new");
    }

    #[test]
    fn nothing_changed_is_an_empty_diff_and_not_a_panic() {
        assert!(diff("").is_empty());
        assert!(diff("\n").is_empty());
    }

    #[test]
    fn an_untracked_file_is_all_right_hand_side() {
        let d = whole_file_added("one\ntwo\n");
        assert_eq!(d.before.len(), 2);
        assert!(d.before.iter().all(|l| l.kind == LineKind::Filler));
        assert_eq!(d.after[1].text, "two");
    }
}

files.src/git/run.rs:
//! Starting `git`, and waiting for it, or not.
//!
//! # Two ways, split by what they wait on
//!
//! Reading the repository is fast and local: `git status` on a large project
//! is milliseconds, and [`git`] runs it in the foreground where the answer is
//! immediately usable.
//!
//! Talking to a remote is neither. A push over a slow link is seconds at best,
//! and a synchronous one would freeze the window with no way to say what it was
//! doing: the worst possible moment to look broken. [`Job::start`] runs those
//! on a thread and hands back a receiver; the event loop already wakes twice a
//! second for the disk watcher, and it collects finished jobs on the same tick.
//!
//! # Environment
//!
//! Every call sets `GIT_OPTIONAL_LOCKS=0`, which stops a mere status check from
//! taking the index lock. Without it, a window left open on a repository would
//! fight `git` in a terminal next door over a file neither of them is writing.
//!
//! # Git never asks the terminal anything
//!
//! tiny is drawing on that terminal, in raw mode. A password prompt would land
//! in the middle of the picture, and the Enter typed to answer it arrives as a
//! `\r` that git never takes for the end of a line, so the command would wait
//! forever and every button after it would say it is still running. So git
//! gets no input, `GIT_TERMINAL_PROMPT=0` stops it asking for a password, and
//! ssh runs in batch mode (unless you have set your own ssh command). Anything
//! that needed asking fails instead, with git's own message: set up a
//! credential helper or an ssh agent, and the buttons work.

use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::sync::mpsc::{Receiver, TryRecvError, channel};

use anyhow::{Context, Result, anyhow};

/// Run git in `dir` and give back its standard output.
///
/// A non-zero exit is an error carrying git's own message, because git's
/// complaints are already written for a person to read and anything we put in
/// front of them would be in the way.
pub fn git(dir: &Path, args: &[&str]) -> Result<String> {
    run(dir, args, &[])
}

/// [`git`], with `env` set as well.
fn run(dir: &Path, args: &[&str], env: &[(&str, &str)]) -> Result<String> {
    let out = Command::new("git")
        .current_dir(dir)
        .stdin(Stdio::null())
        .env("GIT_OPTIONAL_LOCKS", "0")
        .env("GIT_TERMINAL_PROMPT", "0")
        .envs(env.iter().copied())
        .args(args)
        .output()
        .with_context(|| match args.first() {
            Some(a) => format!("cannot run git {a}"),
            None => "cannot run git".to_string(),
        })?;
    if !out.status.success() {
        let stderr = String::from_utf8_lossy(&out.stderr);
        let message = stderr.trim();
        return Err(anyhow!(
            "{}",
            if message.is_empty() {
                format!("git {} failed", args.first().unwrap_or(&""))
            } else {
                message.to_string()
            }
        ));
    }
    Ok(String::from_utf8_lossy(&out.stdout).into_owned())
}

/// A git command running somewhere else, with its answer still to come.
///
/// Held on `App` while it runs. Nothing else can start while one is in flight
/// (see `App::start_job`) because two pushes at once is not a thing anyone
/// means to do, and a queue would only hide the first one's failure.
pub struct Job {
    /// What to call it on screen: `pushing`, `pulling`.
    pub what: String,
    done: Receiver<Result<String, String>>,
}

impl std::fmt::Debug for Job {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Job").field("what", &self.what).finish()
    }
}

impl Job {
    /// Start each of `steps` in turn in `dir`, on a thread, and return at
    /// once. A step that fails stops the ones after it, and what the last one
    /// to run said is the answer.
    ///
    /// The thread is detached deliberately: if tiny exits while a push is in
    /// flight, the push is already git's business and killing it half way
    /// through would be worse than letting it finish.
    pub fn start(dir: &Path, what: &str, steps: &[&[&str]]) -> Self {
        let (tx, done) = channel();
        let dir: PathBuf = dir.to_path_buf();
        let steps: Vec<Vec<String>> = steps
            .iter()
            .map(|args| args.iter().map(|a| a.to_string()).collect())
            .collect();
        std::thread::spawn(move || {
            // Batch mode, so ssh fails rather than asking for a passphrase or
            // about an unknown host on the terminal tiny is drawing on; but
            // never over an ssh command someone has chosen for themselves.
            let quiet = std::env::var_os("GIT_SSH_COMMAND").is_none()
                && git(&dir, &["config", "--get", "core.sshCommand"]).is_err();
            let env: &[(&str, &str)] = if quiet {
                &[("GIT_SSH_COMMAND", "ssh -o BatchMode=yes")]
            } else {
                &[]
            };
            let mut result = Ok(String::new());
            for args in &steps {
                let borrowed: Vec<&str> = args.iter().map(String::as_str).collect();
                result = run(&dir, &borrowed, env).map_err(|e| format!("{e:#}"));
                if result.is_err() {
                    break;
                }
            }
            // The receiver is gone if tiny has closed the window or quit, and
            // there is nothing to report to.
            let _ = tx.send(result);
        });
        Self {
            what: what.to_string(),
            done,
        }
    }

    /// Has it finished? `None` while it is still running.
    pub fn finished(&self) -> Option<Result<String, String>> {
        match self.done.try_recv() {
            Ok(result) => Some(result),
            Err(TryRecvError::Empty) => None,
            // The thread died without sending, which a panic in `git` would do.
            Err(TryRecvError::Disconnected) => {
                Some(Err(format!("{} stopped without saying why", self.what)))
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_failing_git_command_carries_gits_own_complaint() {
        let td = tempfile::tempdir().unwrap();
        let err = git(td.path(), &["rev-parse", "--show-toplevel"])
            .expect_err("a temp dir is not a repository");
        let text = format!("{err:#}").to_lowercase();
        assert!(
            text.contains("not a git repository"),
            "git's own words, not ours: {text}"
        );
    }

    #[test]
    fn a_job_that_finishes_reports_what_it_did() {
        let td = tempfile::tempdir().unwrap();
        let job = Job::start(td.path(), "asking", &[&["--version"]]);
        // Give the thread a moment; this is the one place a test waits.
        let mut answer = None;
        for _ in 0..200 {
            if let Some(result) = job.finished() {
                answer = Some(result);
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        let answer = answer.expect("git --version finishes").expect("and works");
        assert!(answer.starts_with("git version"), "{answer}");
    }
}

files.src/licenses.rs:
//! Who owns what is in the binary.
//!
//! Three layers, and `tiny --licenses` prints all three:
//!
//! - tiny itself, MIT, reproduced from the `LICENSE` file beside this source
//!   so the two can never drift apart.
//! - Everything it is compiled with, in `THIRD-PARTY-NOTICES.txt`: each crate
//!   with its copyright lines and the license it is offered under, Lua (which
//!   is built from source into the binary), and the color themes syntect
//!   bundles, then the text of each license once. Their code is *inside*
//!   the binary, which is what makes this a redistribution and their notices
//!   tiny's to carry. Every one is permissive; nothing here is copyleft,
//!   which is what keeps the MIT above honest.
//! - The syntax definitions, which are third-party data files and carry their
//!   own notices, see [`crate::text::highlight::acknowledgments`].
//!
//! The notices file goes into every release download beside `LICENSE` too,
//! for anyone reading them without running tiny.
//!
//! # Keeping it true
//!
//! The notices are generated, from the crates' own license files, by a test
//! that is skipped unless asked for:
//!
//! ```text
//! cargo test write_third_party_notices -- --ignored
//! ```
//!
//! What it documents is `CRATES`, the written-down list of every crate in the
//! binary, in the tests below. Two tests keep both honest: every crate in
//! `Cargo.lock` that ships has to be in the list, and every crate in the list
//! has to be in the notices, so a new dependency fails the suite until it is
//! listed and the notices are written again.
//!
//! To rebuild the list after changing dependencies, take every target a
//! release is built for (see `release.yml`), since Windows compiles in
//! crates the others do not:
//!
//! ```text
//! for t in aarch64-apple-darwin x86_64-apple-darwin x86_64-unknown-linux-gnu \
//!          aarch64-unknown-linux-gnu x86_64-pc-windows-msvc \
//!          aarch64-pc-windows-msvc; do
//!   cargo tree -e normal,build --prefix none --no-dedupe --target $t
//! done | awk 'NF{print $1}' | sort -u
//! ```
//!
//! and take each crate's `license` field from `cargo metadata`.

/// tiny's own terms, everything it is compiled with, and the grammars it
/// bundles: the whole of what `tiny --licenses` prints.
pub fn notice() -> String {
    let mut out = String::new();
    out.push_str(concat!("tiny ", env!("CARGO_PKG_VERSION"), "\n\n"));
    out.push_str(include_str!("../LICENSE"));
    out.push('\n');
    out.push_str(include_str!("../THIRD-PARTY-NOTICES.txt"));
    out.push('\n');
    out.push_str(&crate::text::highlight::acknowledgments());
    out
}

