/// `--help` output. Kept here as one literal rather than assembled from an
/// argument parser: there are only six options, and a contributor changing
/// the CLI should be able to see the whole surface in one place.
const USAGE: &str = "\
tiny: an IDE, text editor, knowledge manager and file browser in the terminal

USAGE:
    tiny                open the current directory
    tiny <DIR>          open a folder; one that does not exist is created
    tiny <FILE>         edit one file, across the window: Esc shows its
                        folder. A file that does not exist is created too

OPTIONS:
    -h, --help          show this message
    -V, --version       show the version
        --update        install the newest release, if there is one
        --config        print the path of the config file
        --licenses      terms of the bundled syntax definitions
        --uninstall     remove tiny; your notes are not touched

tiny writes nothing into a folder of yours that you did not name: no starter
page, no dotfiles, no per-project settings.

KEYS:
    ?                   every key and command, from inside the app
    /                   the bar: searches, or `*` first for a command
    Ctrl+G  Ctrl+L      source control, the project map
    Ctrl+W  Ctrl+O      the next pane, the terminal

`man tiny` has every key.
";

/// Where the installer puts the manual page, under the folder that holds the
/// binary's `bin`: `~/.local/share/man/man1` for `~/.local/bin`, which is
/// where `man` looks, given that `bin` is on the PATH.
const MAN_PAGE: &str = "share/man/man1/tiny.1";

/// Print to stdout, and do not mind if nobody is listening.
///
/// `print!` panics when the pipe it is writing into closes, which is what
/// happens the moment someone quits the pager they piped `--licenses` into.
/// Every one of these outputs is a whole answer written in one go, so a reader
/// who stops early has read as much as they wanted and there is nothing to
/// report.
fn emit(text: &str) {
    let _ = std::io::Write::write_all(&mut std::io::stdout(), text.as_bytes());
}

/// Thin wrapper so the real work can use `?`.
///
/// Errors are printed with `{e:#}`, which walks anyhow's whole context chain,
/// so "cannot open /nope: No such file or directory" reaches the user instead
/// of just the innermost io error. Exit code 1 on failure, for scripts.
fn main() {
    if let Err(e) = real_main() {
        eprintln!("tiny: {e:#}");
        std::process::exit(1);
    }
}

/// Startup, in the order things have to happen.
///
/// The ordering here is not arbitrary; each step needs the one before it:
///
/// 1. Handle the options that never touch the disk (`--help`, `--version`,
///    `--config`) and return early.
/// 2. Load the config, which [`files::project::resolve`] needs for
///    `default_root` before it can decide what to do with the argument.
/// 3. Resolve the argument into a [`files::project::Target`], creating the
///    project if it does not exist.
/// 4. Write out the defaults on first run.
/// 5. Build the `App`, take over the terminal, loop, and restore.
///
/// There is one config file and it is read once, before anything else: which
/// folder ends up open cannot change how the program behaves. Only one warning
/// survives to the status bar, the more urgent first: a broken config file
/// beats "we just wrote you a config file".
fn real_main() -> Result<()> {
    // A name that is not UTF-8 is said to be one, where `env::args` would
    // have panicked on it.
    let args: Vec<String> = std::env::args_os()
        .skip(1)
        .map(|a| {
            a.into_string().map_err(|a| {
                anyhow!(
                    "{} is not a name tiny can open: it is not valid UTF-8",
                    a.to_string_lossy()
                )
            })
        })
        .collect::<Result<_>>()?;
    match args.first().map(String::as_str) {
        Some("-h") | Some("--help") => {
            emit(USAGE);
            return Ok(());
        }
        Some("-V") | Some("--version") => {
            println!("tiny {}", update::running());
            return Ok(());
        }
        Some("--update") => return update::run_cli(),
        Some("--config") => {
            match Config::user_path() {
                Some(p) => println!("{}", p.display()),
                None => return Err(anyhow!("no config directory available")),
            }
            return Ok(());
        }
        Some("--licenses") => {
            emit(&licenses::notice());
            return Ok(());
        }
        Some("--uninstall") => return uninstall(),
        Some(a) if a.starts_with('-') => {
            return Err(anyhow!("unknown option `{a}`, try `tiny --help`"));
        }
        _ => {}
    }

    let (cfg, warn_config) = Config::load();
    let target = files::project::resolve(args.first().map(String::as_str), &cfg)?;

    // First run: write the defaults out so there is a file to edit. Done here
    // rather than in `load` so `--help` never touches the disk.
    let warn_first_run = match Config::user_path() {
        Some(p) if !p.exists() => match cfg.save() {
            Ok(p) => Some(format!("wrote {} to {}", CONF_NAME, p.display())),
            Err(e) => Some(format!("could not write {CONF_NAME}: {e}")),
        },
        _ => None,
    };

    let warning = warn_config.or(warn_first_run);
    let mut app = App::new(target, cfg, warning)?;
    // Which keys the terminal keeps for itself is known from the environment
    // alone, so it is settled before the first frame, see `Keyboard`.
    app.set_keyboard(Keyboard::detect());
    // And what it can draw: which characters, and how many colors. The
    // settings that are left at `auto` follow it, see `config::host`.
    app.set_host(Host::detect());
    // The plugins, from the one real folder: the app is only ever told where
    // it is from here, so a test never loads anybody's plugins.
    app.plugins_dir = Config::plugins_dir();
    app.config_path = Config::user_path();
    // And the real clipboard, which no test may write over.
    app.text_clipboard = clipboard::Clipboard::new(true);
    app.load_plugins();
    app.tell_plugins_what_is_open();
    // A release build asks, once, whether there is a newer one. A debug build
    // is somebody working on tiny, and is left alone, see `update`.
    if app.config.update_check && !cfg!(debug_assertions) {
        app.start_update_check(false);
    }

    // A clean message beats a panic when there is no terminal to draw on:
    // piping the binary or running it from a script hits this.
    let mut terminal = ratatui::try_init().map_err(|e| {
        anyhow!("no interactive terminal available ({e}); tiny needs a real terminal")
    })?;
    hand_back_the_terminal_on_panic();
    // Wheel events only reach a program that asks for them. Without this the
    // terminal translates a notch into three arrow keys of its own, which is
    // why scrolling used to jump. Best-effort: a terminal that will not report
    // the mouse is still perfectly usable from the keyboard.
    let mouse = execute!(std::io::stdout(), EnableMouseCapture).is_ok();
    // A paste from the terminal's own paste key then arrives as one piece,
    // rather than as keys typed so fast that auto-indent indents each line
    // a little more than the last.
    let paste = execute!(std::io::stdout(), EnableBracketedPaste).is_ok();
    let result = run(&mut terminal, &mut app);
    // The terminal's own cursor back, whatever shape tiny was asked for.
    let _ = execute!(std::io::stdout(), SetCursorStyle::DefaultUserShape);
    if paste {
        let _ = execute!(std::io::stdout(), DisableBracketedPaste);
    }
    if mouse {
        let _ = execute!(std::io::stdout(), DisableMouseCapture);
    }
    ratatui::restore();
    result?;

    // A yes to the update question, carried out now that the terminal is an
    // ordinary terminal again: the installer's progress, and any question it
    // asks, need it.
    if let Some(version) = app.update_on_exit.take() {
        println!("updating tiny {} to {version}\n", update::running());
        let exe = update::install(&version)?;
        println!("\ntiny {version} installed, starting it");
        update::relaunch(&exe)?;
    }
    Ok(())
}

/// Turn off the mouse reporting and the paste brackets tiny asked for, if it
/// panics.
///
/// `ratatui::try_init` already leaves a hook that gives back raw mode and the
/// alternate screen. It cannot know about the requests tiny makes on its own
/// account, so without this a panic drops you back at a shell whose terminal
/// is still reporting wheel events, with nothing on screen to say why.
///
/// It is safe to send when it was never turned on: the terminal is being told
/// to stop doing something it is not doing. That matters, because a hook runs
/// at a moment when what did and did not get set up is not knowable.
///
/// Ours runs first and ratatui's second, so the escape sequence goes out while
/// the alternate screen is still up and the panic message is the last thing
/// written.
fn hand_back_the_terminal_on_panic() {
    let next = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        let _ = execute!(
            std::io::stdout(),
            DisableMouseCapture,
            DisableBracketedPaste,
            SetCursorStyle::DefaultUserShape
        );
        next(info);
    }));
}

/// How long the loop will wait for a key before going to look at the disk.
///
/// Half a second reads as "instantly" for a file changed by another program
/// while you are looking at it, and costs a stat of each open file and each
/// open directory twice a second: microseconds. Shorter would not be
/// noticeably quicker; much longer starts to feel like the screen is lying.
const IDLE: Duration = Duration::from_millis(500);

/// How often a running shell is looked at for something new to show: often
/// enough that output scrolls by smoothly, and only while there is a shell.
const TICK: Duration = Duration::from_millis(16);

/// The cursor the settings ask for: the terminal's own, or a shape, blinking
/// or not.
fn cursor_style(config: &Config) -> SetCursorStyle {
    match (config.cursor_shape, config.cursor_blink) {
        (CursorShape::Default, _) => SetCursorStyle::DefaultUserShape,
        (CursorShape::Block, true) => SetCursorStyle::BlinkingBlock,
        (CursorShape::Block, false) => SetCursorStyle::SteadyBlock,
        (CursorShape::Bar, true) => SetCursorStyle::BlinkingBar,
        (CursorShape::Bar, false) => SetCursorStyle::SteadyBar,
        (CursorShape::Underline, true) => SetCursorStyle::BlinkingUnderScore,
        (CursorShape::Underline, false) => SetCursorStyle::SteadyUnderScore,
    }
}

/// The event loop: draw, wait for something to happen, dispatch, repeat.
///
/// Note the order: the frame is drawn *before* the quit check, so the last
/// action a user takes is visible on screen before the program exits.
///
/// The inner loop is what keeps "one frame per thing that happened" true now
/// that waiting can end without an event. A timeout that finds nothing changed
/// on disk goes back to waiting rather than falling out and redrawing an
/// identical screen, so an idle tiny still draws nothing at all. The one
/// exception is colors being read in behind a guess, see
/// `highlight::Resume::behind`: they are drawn again until they are exact,
/// and then that stops too.
///
/// `ratatui::restore` in the caller runs whether or not this returns an error,
/// so a failure in here still gives the terminal back.
fn run(terminal: &mut ratatui::DefaultTerminal, app: &mut App) -> Result<()> {
    let mut looked = std::time::Instant::now();
    app.input_waiting = || event::poll(Duration::ZERO).unwrap_or(false);
    // Whether the next frame is drawn only for colors still to read.
    let mut reading = false;
    // What the cursor was last set to, so it is only said again when a
    // setting changes it. Nothing yet: the terminal's own is what it has.
    let mut cursor = (CursorShape::Default, true);
    loop {
        let wanted = (app.config.cursor_shape, app.config.cursor_blink);
        if wanted != cursor {
            cursor = wanted;
            let _ = execute!(std::io::stdout(), cursor_style(&app.config));
        }
        app.reading_colors = reading;
        terminal.draw(|f| ui::draw(f, app))?;
        app.reading_colors = false;
        reading = false;
        if app.should_quit {
            return Ok(());
        }
        loop {
            // A shell writes whenever it likes, and there is no telling the
            // terminal to wake us when it does, so while there is one it is
            // looked at every tick. Colors still being read in behind a
            // guess are drawn again the moment nothing else is happening,
            // see `highlight::Resume::behind`.
            let wait = if app.colors_behind {
                Duration::ZERO
            } else if app.has_terminal() {
                TICK
            } else {
                IDLE
            };
            if !event::poll(wait)? {
                let shell = app.poll_terminal();
                reading = app.colors_behind;
                if looked.elapsed() < IDLE {
                    if shell || reading {
                        break;
                    }
                    continue;
                }
                looked = std::time::Instant::now();
                // Nobody typed anything. Has anyone else been writing, has
                // the push we started come back, is there a newer tiny?
                // Each is asked every time: one with news must not keep the
                // others from being heard.
                let git = app.poll_git_job();
                let disk = app.rescan_disk();
                let update = app.poll_update();
                if shell || git || disk || update || reading {
                    break;
                }
                continue;
            }
            if dispatch(app, event::read()?) {
                break;
            }
        }
        // Whatever else arrived while that was being handled (fast typing, a
        // paste) is taken now, before the one frame it will all appear in.
        // Each key is cheap on its own; what is not, a search of the whole
        // project, waits for `settle` and happens once for the lot.
        while !app.should_quit && event::poll(Duration::ZERO)? {
            dispatch(app, event::read()?);
            // Someone is waiting on this frame after all.
            reading = false;
        }
        app.settle();
    }
}

/// Hand one terminal event to the app. Returns whether there is anything new
/// to draw.
///
/// Mouse reporting, once on, reports every movement across the window, and
/// Windows reports every key's release as well as its press. Each of those
/// is nothing to tiny, and drawing a frame for each was most of what it did
/// while the mouse moved over a long note.
fn dispatch(app: &mut App, event: Event) -> bool {
    match event {
        // Only presses, and the repeats from holding a key down.
        Event::Key(k) if matches!(k.kind, KeyEventKind::Press | KeyEventKind::Repeat) => {
            app.handle_key(k);
            true
        }
        // The wheel, a click, a drag. A mouse moving with no button down is
        // nothing to tiny, and draws nothing.
        Event::Mouse(m) => app.on_mouse(m),
        // The terminal's own paste, all of it at once.
        Event::Paste(text) => {
            app.on_paste(text);
            true
        }
        // Nothing to handle, but everything has to be laid out again.
        Event::Resize(..) => true,
        // A key's release, focus coming and going.
        _ => false,
    }
}

// ---- uninstall -------------------------------------------------------------

/// Everything an uninstall would delete.
///
/// Built in full before a single file is removed, so the prompt can show the
/// whole list and the user agrees to it as one thing. An uninstaller that
/// discovers what to delete as it goes is one you cannot say no to halfway.
///
/// Note what is *not* in here: anything under a project. tiny never wrote a
/// file into a folder of yours that you did not name, so there is nothing of
/// its own to take back. Deleting notes is not what removing a program means.
#[derive(Debug, Default, PartialEq, Eq)]
struct Removal {
    /// The running binary: whatever `tiny` you just typed.
    bin: Option<PathBuf>,
    /// `tiny.conf`, if one was ever written.
    conf: Option<PathBuf>,
    /// The plugins folder, only when there is nothing in it: the settings
    /// area's button makes it, and an empty one is nobody's work. One with
    /// plugins in it stays, and so does the folder around it.
    plugins_dir: Option<PathBuf>,
    /// The config directory, only when `tiny.conf` is the last thing in it,
    /// beside an empty plugins folder at most. A directory someone put their
    /// own files in stays.
    conf_dir: Option<PathBuf>,
    /// The manual page the installer put beside the binary, in
    /// `share/man/man1` next to its `bin`.
    man: Option<PathBuf>,
    /// The `--root` cargo installed into, when its bookkeeping names tiny.
    /// `cargo uninstall` is then the right way to remove the binary, because
    /// it also forgets the entry; unlinking alone leaves cargo believing
    /// tiny is still installed.
    cargo_root: Option<PathBuf>,
}

impl Removal {
    /// Work out what to delete, given where the binary and the config live.
    ///
    /// Both are passed in rather than looked up so this is testable against a
    /// temporary directory instead of against the machine it runs on.
    fn plan(bin: Option<PathBuf>, conf: Option<PathBuf>) -> Self {
        let conf = conf.filter(|p| p.is_file());
        let is_empty = |d: &std::path::Path| {
            std::fs::read_dir(d)
                .map(|mut it| it.next().is_none())
                .unwrap_or(false)
        };
        let plugins_dir = conf
            .as_ref()
            .and_then(|p| p.parent())
            .map(|d| d.join(PLUGINS_NAME))
            .filter(|p| p.is_dir() && is_empty(p));
        let conf_dir = conf
            .as_ref()
            .and_then(|p| p.parent())
            // Nothing in it but what we are about to remove: the file, and an
            // empty plugins folder if there is one.
            .filter(|d| {
                std::fs::read_dir(d)
                    .map(|entries| {
                        entries.flatten().all(|e| {
                            e.file_name() == CONF_NAME
                                || (e.file_name() == PLUGINS_NAME && plugins_dir.is_some())
                        })
                    })
                    .unwrap_or(false)
            })
            .map(PathBuf::from);
        // `cargo install --root R` puts the binary in `R/bin` and its record
        // in `R/.crates.toml`, so the root is two levels up from the binary.
        let cargo_root = bin
            .as_ref()
            .filter(|p| p.is_file())
            .and_then(|p| p.parent()?.parent())
            .filter(|root| {
                std::fs::read_to_string(root.join(".crates.toml"))
                    .map(|s| s.contains("\"tiny "))
                    .unwrap_or(false)
            })
            .map(PathBuf::from);
        let man = bin
            .as_ref()
            .filter(|p| p.is_file())
            .and_then(|p| p.parent()?.parent())
            .map(|prefix| prefix.join(MAN_PAGE))
            .filter(|p| p.is_file());
        Self {
            bin: bin.filter(|p| p.is_file()),
            conf,
            plugins_dir,
            conf_dir,
            man,
            cargo_root,
        }
    }

    /// The list shown at the prompt, in the order things are removed.
    fn lines(&self) -> Vec<String> {
        let mut out = Vec::new();
        if let Some(p) = &self.conf {
            out.push(format!("  {}", p.display()));
        }
        if let Some(p) = &self.plugins_dir {
            out.push(format!("  {}/", p.display()));
        }
        if let Some(p) = &self.conf_dir {
            out.push(format!("  {}/", p.display()));
        }
        if let Some(p) = &self.man {
            out.push(format!("  {}", p.display()));
        }
        if let Some(p) = &self.bin {
            out.push(format!("  {}", p.display()));
        }
        out
    }

    /// Delete everything, collecting failures rather than stopping at the
    /// first. A config file that will not budge should not leave the binary
    /// behind as well; you would have to run the uninstaller again to finish,
    /// and it would have less to work with the second time.
    ///
    /// Config goes before the binary so that a failure part-way leaves `tiny`
    /// still runnable, and therefore still able to try again.
    fn perform(&self) -> Vec<String> {
        let mut errors = Vec::new();
        if let Some(p) = &self.conf
            && let Err(e) = std::fs::remove_file(p)
        {
            errors.push(format!("{}: {e}", p.display()));
        }
        if let Some(p) = &self.plugins_dir
            && let Err(e) = std::fs::remove_dir(p)
        {
            errors.push(format!("{}: {e}", p.display()));
        }
        if let Some(p) = &self.conf_dir
            && let Err(e) = std::fs::remove_dir(p)
        {
            errors.push(format!("{}: {e}", p.display()));
        }
        if let Some(p) = &self.man
            && let Err(e) = std::fs::remove_file(p)
        {
            errors.push(format!("{}: {e}", p.display()));
        }
        let Some(bin) = &self.bin else {
            return errors;
        };
        // Hand it to cargo when cargo owns it, so its bookkeeping is updated
        // too. Best effort: an old install whose cargo has since been removed
        // still gets unlinked below.
        if let Some(root) = &self.cargo_root {
            let done = std::process::Command::new("cargo")
                .args(["uninstall", "--quiet", "--root"])
                .arg(root)
                .arg("tiny")
                .status()
                .map(|s| s.success())
                .unwrap_or(false);
            if done {
                return errors;
            }
        }
        // Unix unlinks a running executable happily; Windows will not, so say
        // what to do about it rather than only that it did not work.
        if let Err(e) = std::fs::remove_file(bin) {
            let hint = if cfg!(target_os = "windows") {
                ". Windows will not delete a running program: close tiny and delete it"
            } else {
                ""
            };
            errors.push(format!("{}: {e}{hint}", bin.display()));
        }
        errors
    }
}

/// `tiny --uninstall`: show what will go, ask, then remove it.
///
/// The prompt reads from stdin rather than from the terminal directly, so
/// `echo y | tiny --uninstall` works for anyone scripting it and there is no
/// `--yes` flag to document. End-of-file counts as "no": a program removing
/// itself should need to be told, not merely left alone.
fn uninstall() -> Result<()> {
    let bin = std::env::current_exe().ok();
    let removal = Removal::plan(bin, Config::user_path());
    let lines = removal.lines();
    if lines.is_empty() {
        println!("nothing to remove: no tiny binary or config file found");
        return Ok(());
    }

    println!("This will remove:");
    for line in &lines {
        println!("{line}");
    }
    println!("\nYour notes and projects are not touched.");
    print!("\nRemove tiny? [y/N] ");
    let _ = std::io::Write::flush(&mut std::io::stdout());

    let mut reply = String::new();
    if std::io::BufRead::read_line(&mut std::io::stdin().lock(), &mut reply).is_err()
        || !matches!(reply.trim(), "y" | "Y" | "yes" | "Yes")
    {
        println!("canceled, nothing was removed");
        return Ok(());
    }

    let errors = removal.perform();
    if errors.is_empty() {
        println!("tiny is gone. Thanks for trying it.");
        return Ok(());
    }
    for e in &errors {
        eprintln!("tiny: could not remove {e}");
    }
    Err(anyhow!("{} item(s) could not be removed", errors.len()))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use std::path::Path;

    /// A fake install: `<root>/bin/tiny` plus cargo's record of it, and a
    /// config file in its own directory.
    fn fake_install(td: &Path) -> (PathBuf, PathBuf) {
        let bin_dir = td.join("root").join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        let bin = bin_dir.join("tiny");
        fs::write(&bin, "#!/bin/sh\n").unwrap();
        let conf_dir = td.join("config").join("tiny");
        fs::create_dir_all(&conf_dir).unwrap();
        let conf = conf_dir.join(CONF_NAME);
        fs::write(&conf, "borders = true\n").unwrap();
        (bin, conf)
    }

    #[test]
    fn uninstall_removes_the_binary_and_the_config_and_nothing_else() {
        let td = tempfile::tempdir().unwrap();
        let (bin, conf) = fake_install(td.path());
        // A note living beside the install, to prove it survives.
        let note = td.path().join("notes.md");
        fs::write(&note, "mine").unwrap();

        let removal = Removal::plan(Some(bin.clone()), Some(conf.clone()));
        assert!(removal.perform().is_empty(), "clean removal");

        assert!(!bin.exists(), "the binary is gone");
        assert!(!conf.exists(), "the config is gone");
        assert!(
            !conf.parent().unwrap().exists(),
            "its directory went with it"
        );
        assert!(note.exists(), "a note beside it is untouched");
    }

    #[test]
    fn a_config_directory_holding_someone_elses_files_is_left_alone() {
        let td = tempfile::tempdir().unwrap();
        let (_, conf) = fake_install(td.path());
        let theirs = conf.parent().unwrap().join("notes-to-self.txt");
        fs::write(&theirs, "keep me").unwrap();

        let removal = Removal::plan(None, Some(conf.clone()));
        assert_eq!(
            removal.conf_dir, None,
            "the directory is not ours to delete"
        );
        removal.perform();
        assert!(!conf.exists(), "our file still goes");
        assert!(theirs.exists(), "theirs stays");
    }

    #[test]
    fn an_empty_plugins_folder_goes_with_the_config() {
        let td = tempfile::tempdir().unwrap();
        let (_, conf) = fake_install(td.path());
        let plugins = conf.parent().unwrap().join(PLUGINS_NAME);
        fs::create_dir(&plugins).unwrap();

        let removal = Removal::plan(None, Some(conf.clone()));
        assert_eq!(removal.plugins_dir.as_ref(), Some(&plugins));
        assert!(removal.perform().is_empty());
        assert!(!conf.parent().unwrap().exists(), "the whole folder went");
    }

    #[test]
    fn installed_plugins_are_kept_and_so_is_their_folder() {
        let td = tempfile::tempdir().unwrap();
        let (_, conf) = fake_install(td.path());
        let plugins = conf.parent().unwrap().join(PLUGINS_NAME);
        fs::create_dir(&plugins).unwrap();
        fs::write(plugins.join("words.lua"), "-- mine").unwrap();

        let removal = Removal::plan(None, Some(conf.clone()));
        assert_eq!(removal.plugins_dir, None, "somebody's plugins");
        assert_eq!(removal.conf_dir, None, "and the folder they are in");
        removal.perform();
        assert!(!conf.exists(), "the config still goes");
        assert!(plugins.join("words.lua").exists(), "the plugin stays");
    }

    #[test]
    fn a_cargo_install_is_recognized_by_its_bookkeeping() {
        let td = tempfile::tempdir().unwrap();
        let (bin, _) = fake_install(td.path());
        let root = td.path().join("root");

        assert_eq!(
            Removal::plan(Some(bin.clone()), None).cargo_root,
            None,
            "no record means no cargo"
        );

        fs::write(
            root.join(".crates.toml"),
            "[v1]\n\"tiny 0.1.2 (path+file:///src)\" = [\"tiny\"]\n",
        )
        .unwrap();
        assert_eq!(
            Removal::plan(Some(bin), None).cargo_root,
            Some(root),
            "a record naming tiny means cargo should do the removing"
        );
    }

    #[test]
    fn the_manual_page_beside_the_binary_goes_too() {
        let td = tempfile::tempdir().unwrap();
        let (bin, _) = fake_install(td.path());
        let man = td.path().join("root").join(MAN_PAGE);
        fs::create_dir_all(man.parent().unwrap()).unwrap();
        fs::write(&man, ".TH TINY 1\n").unwrap();
        let theirs = man.with_file_name("ls.1");
        fs::write(&theirs, ".TH LS 1\n").unwrap();

        let removal = Removal::plan(Some(bin), None);
        assert_eq!(removal.man.as_ref(), Some(&man));
        assert!(removal.perform().is_empty());
        assert!(!man.exists(), "the page is gone");
        assert!(theirs.exists(), "another program's page is not ours");
    }

    /// `docs/tiny.1`, which is written by hand.
    const MANUAL: &str = include_str!("../docs/tiny.1");

    /// The lines of one `.SH` section of the manual.
    fn manual_section(name: &str) -> Vec<&'static str> {
        MANUAL
            .lines()
            .skip_while(|l| *l != format!(".SH {name}"))
            .skip(1)
            .take_while(|l| !l.starts_with(".SH "))
            .collect()
    }

    /// What each `.TP` entry of a section is about: the words on the line
    /// after it, without the quotes, the escapes and the commas.
    fn manual_tags(section: &str) -> Vec<String> {
        let lines = manual_section(section);
        lines
            .windows(2)
            .filter(|w| w[0] == ".TP")
            .flat_map(|w| {
                let tag = w[1].split_once(' ').map_or("", |(_, rest)| rest);
                let tag = tag.replace("\\-", "-").replace('"', "");
                tag.split(", ")
                    .map(|k| k.trim().to_string())
                    .collect::<Vec<_>>()
            })
            .collect()
    }

    /// A key as the manual writes it: `Ctrl+S`, `Page Up`, `Shift+I`.
    fn as_written(spec: &str) -> String {
        let (mods, base) = match spec.rfind('+') {
            Some(i) if i + 1 < spec.len() => (&spec[..i], &spec[i + 1..]),
            _ => ("", spec),
        };
        let mut out = String::new();
        for m in mods.split('+').filter(|m| !m.is_empty()) {
            let mut c = m.chars();
            out.extend(c.next().map(|f| f.to_ascii_uppercase()));
            out.push_str(c.as_str());
            out.push('+');
        }
        let base = match base {
            "pageup" => "Page Up".to_string(),
            "pagedown" => "Page Down".to_string(),
            b if b.chars().count() == 1 => {
                let c = b.chars().next().unwrap();
                if !mods.is_empty() {
                    c.to_ascii_uppercase().to_string()
                } else if c.is_ascii_uppercase() {
                    format!("Shift+{c}")
                } else {
                    c.to_string()
                }
            }
            b => {
                let mut c = b.chars();
                c.next()
                    .map(|f| f.to_ascii_uppercase())
                    .into_iter()
                    .chain(c)
                    .collect()
            }
        };
        out + &base
    }

    #[test]
    fn the_manual_names_every_key_and_nothing_else() {
        use config::keys::{Action, Keymap};
        let keymap = Keymap::default();
        let shipped: Vec<String> = Action::all()
            .flat_map(|a| keymap.keys(a).iter().map(|k| as_written(&k.to_string())))
            .collect();
        let written = manual_tags("CONTROLS");
        for key in &shipped {
            assert!(
                written.contains(key),
                "the manual does not say what {key} does"
            );
        }
        for key in &written {
            assert!(
                shipped.contains(key),
                "the manual names {key}, which does nothing"
            );
        }
    }

    #[test]
    fn the_manual_names_every_option_and_this_version() {
        let mut options: Vec<String> = USAGE
            .lines()
            .skip_while(|l| *l != "OPTIONS:")
            .skip(1)
            .take_while(|l| !l.is_empty())
            .flat_map(|l| l.split_whitespace().take_while(|w| w.starts_with('-')))
            .map(|w| w.trim_end_matches(',').to_string())
            .collect();
        let mut written = manual_tags("OPTIONS");
        options.sort();
        written.sort();
        assert_eq!(written, options);
        let title = MANUAL.lines().find(|l| l.starts_with(".TH ")).unwrap();
        assert!(
            title.contains(&format!("\"tiny {}\"", env!("CARGO_PKG_VERSION"))),
            "the manual is for another version: {title}"
        );
    }

    #[test]
    fn planning_against_nothing_finds_nothing_to_remove() {
        let td = tempfile::tempdir().unwrap();
        let removal = Removal::plan(Some(td.path().join("nope")), Some(td.path().join("gone")));
        assert_eq!(removal, Removal::default());
        assert!(removal.lines().is_empty(), "the prompt would be empty");
    }
}

