//! Fixtures shared by the map's own tests.
//!
//! [`view`](super::view) and [`layout`](super::layout) are two halves of one
//! `ProjectMap`, so their tests want the same small project to look at: two
//! notes that link to each other, two source files that call across, and one
//! file nothing reaches. Building it in one place keeps the two halves
//! agreeing about what they are describing.

use std::path::Path;

use crossterm::event::{KeyCode, KeyEvent};

use crate::config::keys::Action;
use crate::map::graph;
use crate::map::view::ProjectMap;

use crossterm::event::{KeyEventKind, KeyModifiers};
use std::fs;

pub(crate) fn write(dir: &Path, rel: &str, body: &str) {
    let p = dir.join(rel);
    fs::create_dir_all(p.parent().unwrap()).unwrap();
    fs::write(p, body).unwrap();
}

/// Two notes that link to each other, two code files that call across,
/// and one file connected to nothing.
pub(crate) fn fixture() -> (tempfile::TempDir, ProjectMap) {
    let td = tempfile::tempdir().unwrap();
    write(td.path(), "notes/design.md", "see [[architecture]]\n");
    write(td.path(), "notes/architecture.md", "back to [[design]]\n");
    write(td.path(), "src/utils.py", "def load():\n    return 1\n");
    write(td.path(), "src/main.py", "import utils\nutils.load()\n");
    write(td.path(), "notes/alone.md", "nothing points here\n");
    let view = ProjectMap::build(td.path(), &graph::Options::default(), "…");
    (td, view)
}

pub(crate) fn k(code: KeyCode) -> KeyEvent {
    KeyEvent {
        code,
        modifiers: KeyModifiers::NONE,
        kind: KeyEventKind::Press,
        state: crossterm::event::KeyEventState::NONE,
    }
}

pub(crate) fn ch(c: char) -> KeyEvent {
    k(KeyCode::Char(c))
}

/// What the shipped keyboard makes of a key. These tests are about the
/// view, not the bindings.
pub(crate) fn act(key: KeyEvent) -> Option<Action> {
    crate::config::keys::Keymap::default().find(crate::config::keys::Context::Map, &key)
}

pub(crate) fn rel_of(view: &ProjectMap, i: usize) -> &str {
    &view.graph.nodes[i].rel
}

pub(crate) fn visible_names(view: &ProjectMap) -> Vec<&str> {
    view.visible_indices()
        .into_iter()
        .map(|i| rel_of(view, i))
        .collect()
}

files.src/map/view.rs:
//! The project map: what is on it, and what the keyboard does to it.
//!
//! Every file in the project is a box with its name in it, and the connections
//! between them are lines, the way anyone would draw this on paper. This half
//! owns the *state*: which file is selected, which connection kinds are
//! switched on, what the filter is hiding. Where each box physically sits is
//! [`super::layout`]'s job, and painting it is `ui::map`'s.
//!
//! Folders are not boxes. They are not selectable, nothing connects to one,
//! and opening one does nothing: a folder is *where files are*, and the
//! heading is how the picture says so.
//!
//! Navigation is spatial: the arrow keys move to the nearest file in that
//! direction, so the graph is something you walk around rather than a list
//! that happens to be drawn as dots.
//!
//! # Division of labor
//!
//! [`super::graph`] decides *what connects to what*; this module decides
//! *what you can see and do*; [`super::layout`] decides *where it sits*. The
//! `Graph` itself is never mutated after construction; filtering happens by
//! asking [`ProjectMap::node_visible`] and [`ProjectMap::edge_visible`] at
//! draw time, so toggling an edge kind is instant and reversible.
//!
//! # Every frame is per file, never per file per edge
//!
//! A frame asks, for every file, whether anything reaches it, and draws the
//! selected file's lines. Scanning the whole edge list to answer either is
//! quadratic, and on a vault of twenty thousand notes that was two seconds a
//! keypress. So the answers are indexed once, at build time: `touching` lists
//! each file's edges, and `shown` holds the filter's verdict on each file
//! until the filter changes.
//!
//! # Coordinates
//!
//! `pos` is written by [`super::layout`] in **grid** units (one per box, not
//! one per character) with **y running upwards**, which is why `Up` calls
//! `move_towards(0.0, 1.0)`. Navigation then walks the picture exactly as it
//! is drawn.

use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};

use crate::config::keys::Action;
use crate::map::graph::{self, Edge, EdgeKind, Graph, Node};
use crate::map::layout::{self, Link};

/// What a keypress asked the app to do. Named for the request rather than
/// the key, since `keys::Action` is now what a key resolves to.
///
/// The view handles its own navigation but cannot open files or close itself:
/// both need `App`. Returning an intent keeps this module free of any
/// dependency on application state.
pub enum Intent {
    /// Handled internally; nothing for `App` to do.
    None,
    /// Leave the map and go back to the tree.
    Close,
    /// Open this file in the editor, closing the map.
    Open(PathBuf),
    /// Read the project again and draw a fresh map of it, kept as it was
    /// being looked at (see [`ProjectMap::carry_over`]): what this is for is
    /// picking up files and links that changed on disk.
    Rebuild,
}

/// The link graph plus everything about how it is currently being looked at.
pub struct ProjectMap {
    /// Built once and never modified. All filtering is applied at read time.
    pub graph: Graph,
    /// The project folder the map is of. Nothing above it is ever walked, so
    /// this is the whole extent of the picture.
    pub(super) root: PathBuf,
    /// Laid-out position of each node, parallel to `graph.nodes`.
    pub pos: Vec<(f64, f64)>,
    /// Index of the node under the cursor. May point at something currently
    /// filtered out, which is why [`ProjectMap::selected_node`] checks
    /// visibility and [`ProjectMap::ensure_selection`] repairs it.
    pub selected: usize,
    /// Which edge kinds to draw: wikilink, link, call. Indexed by
    /// [`kind_index`], and bound to the `1`-`3` keys.
    pub kinds: [bool; 3],
    /// Substring matched against each node's relative path, case-insensitively.
    /// Empty means no filtering. Changed only through
    /// [`ProjectMap::set_filter`], which keeps `shown` in step with it.
    filter: String,
    /// Whether each node passes the filter, parallel to `graph.nodes`.
    shown: Vec<bool>,
    /// The edges touching each node, as indices into `graph.edges` in edge
    /// order. What a file connects to costs that file's edges to find, not
    /// the whole graph's.
    touching: Vec<Vec<usize>>,
    /// Each file's name as drawn in its box, see [`layout::label_of`].
    pub(super) labels: Vec<String>,
    /// Each file's name as the detail strip lists it, see [`short_names`].
    short: Vec<String>,
    /// How many connections are drawn, as the title counts them. Counted
    /// when what is drawn changes rather than on every frame.
    links_drawn: usize,
    /// The folder each file sits in, as an index into `folders`.
    pub(super) folder: Vec<usize>,
    /// Every folder holding a file, in path order, without a trailing slash.
    /// The project root is `""`, so it comes first.
    pub(super) folders: Vec<String>,
}

/// Position of an edge kind in [`ProjectMap::kinds`], and in the `1`-`3` key
/// bindings. `pub` because `ui` needs it to draw the toggle row.
pub fn kind_index(kind: EdgeKind) -> usize {
    match kind {
        EdgeKind::Wikilink => 0,
        EdgeKind::Link => 1,
        EdgeKind::Call => 2,
    }
}

/// What to call each file in a list of names: its name, or as much of the end
/// of its path as tells it apart from the files that share the name, so a
/// Rust project's `out:` reads `app/mod.rs ui/mod.rs` rather than `mod.rs
/// mod.rs`.
fn short_names(nodes: &[Node]) -> Vec<String> {
    let mut by_name: HashMap<&str, Vec<usize>> = HashMap::new();
    for (i, n) in nodes.iter().enumerate() {
        by_name.entry(n.name.as_str()).or_default().push(i);
    }
    nodes
        .iter()
        .enumerate()
        .map(|(i, n)| {
            let same = &by_name[n.name.as_str()];
            if same.len() == 1 {
                return n.name.clone();
            }
            let parts: Vec<&str> = n.rel.split('/').collect();
            (2..=parts.len())
                .map(|k| parts[parts.len() - k..].join("/"))
                .find(|end| {
                    same.iter().filter(|j| **j != i).all(|&j| {
                        let other = &nodes[j].rel;
                        other != end && !other.ends_with(&format!("/{end}"))
                    })
                })
                .unwrap_or_else(|| n.rel.clone())
        })
        .collect()
}

impl ProjectMap {
    /// Shorten every name to fit its box again, cut with `ellipsis`: the
    /// glyph set's, so a map drawn in ASCII has nothing else in it either.
    /// Labels are as long either way, so nothing has to be laid out again.
    pub fn label_with(&mut self, ellipsis: &str) {
        self.labels = self
            .graph
            .nodes
            .iter()
            .map(|n| layout::label_of(&n.name, ellipsis))
            .collect();
    }

    /// Build the graph and put the cursor somewhere sensible, with names cut
    /// short with `ellipsis`. Laying it out is `place`'s job, and happens per
    /// frame against the pane it has.
    ///
    /// Everything expensive happens here, synchronously; this is what
    /// opening the map costs.
    pub fn build(root: &Path, opts: &graph::Options, ellipsis: &str) -> Self {
        let graph = graph::build(root, opts);
        let mut touching = vec![Vec::new(); graph.nodes.len()];
        for (n, e) in graph.edges.iter().enumerate() {
            touching[e.from].push(n);
            touching[e.to].push(n);
        }
        let (folder, folders) = layout::folders_of(&graph.nodes);
        let mut view = Self {
            pos: vec![(0.0, 0.0); graph.nodes.len()],
            shown: vec![true; graph.nodes.len()],
            short: short_names(&graph.nodes),
            graph,
            root: root.to_path_buf(),
            selected: 0,
            kinds: [true; 3],
            filter: String::new(),
            touching,
            labels: Vec::new(),
            links_drawn: 0,
            folder,
            folders,
        };
        view.label_with(ellipsis);
        view.recount();
        view.select_busiest();
        // `pos` is written by `place`, which only runs when a frame is drawn.
        // Seed it against a nominal pane so the arrow keys mean something if a
        // key ever arrives before the first draw; the first frame overwrites
        // this with the real geometry.
        view.place(100, 30);
        view
    }

    // ---- what is on screen ------------------------------------------------

    /// Whether a file is drawn at all.
    ///
    /// Only the bar's filter can hide one. A file that links to nothing is still
    /// part of the project; it is filed under its own heading rather than
    /// left out, because a map that quietly omits things is a map you cannot
    /// trust to tell you what is there. See [`ProjectMap::connected`].
    pub fn node_visible(&self, i: usize) -> bool {
        self.shown.get(i).copied().unwrap_or(false)
    }

    /// What the map is narrowed to, as typed. Empty when it is not.
    pub fn filter(&self) -> &str {
        &self.filter
    }

    /// A file's name as it is written in its box.
    pub fn label(&self, i: usize) -> &str {
        &self.labels[i]
    }

    /// A file's name as the detail strip lists it, see [`short_names`].
    pub fn short_name(&self, i: usize) -> &str {
        &self.short[i]
    }

    /// Look at the project the way `old` was looking at it: the same kinds
    /// of connection switched off, the same filter, and the cursor on the
    /// same file if it is still there. What `r` does after reading the
    /// project again, so a rebuilt map is the old one brought up to date
    /// rather than a fresh one.
    pub fn carry_over(&mut self, old: &ProjectMap) {
        self.kinds = old.kinds;
        self.set_filter(&old.filter);
        if let Some(rel) = old.selected_node().map(|n| &n.rel)
            && let Some(i) = self.graph.nodes.iter().position(|n| &n.rel == rel)
        {
            self.selected = i;
        }
        self.ensure_selection();
        self.recount();
    }

    /// Whether any connection reaches this file, in either direction.
    ///
    /// Depends on which edge kinds are switched on, which is the point: turn
    /// `call` off in a code project and most files move to the unconnected
    /// heading, because with calls hidden nothing does connect them.
    ///
    /// Deliberately blind to the filter. A filter narrows what you are
    /// looking at; it does not change what a file is joined to, and filing
    /// every file as unconnected the moment you type into the box would be
    /// telling you something untrue about your project.
    pub(super) fn connected(&self, i: usize) -> bool {
        self.touching[i]
            .iter()
            .any(|&e| self.kind_on(&self.graph.edges[e]))
    }

    /// Whether this edge's kind is switched on, ignoring everything else.
    pub(super) fn kind_on(&self, e: &Edge) -> bool {
        self.kinds[kind_index(e.kind)]
    }

    /// An edge is drawn only when its kind is on *and* both endpoints are
    /// visible; otherwise a filter would leave lines dangling into nothing.
    pub fn edge_visible(&self, e: &Edge) -> bool {
        self.kind_on(e) && self.node_visible(e.from) && self.node_visible(e.to)
    }

    /// Every drawn node, in index order. Also the order `Tab` steps through.
    pub fn visible_indices(&self) -> Vec<usize> {
        (0..self.graph.nodes.len())
            .filter(|i| self.shown[*i])
            .collect()
    }

    /// The node under the cursor, or `None` when the cursor is on something
    /// currently filtered out.
    pub fn selected_node(&self) -> Option<&Node> {
        let i = self.selected;
        self.node_visible(i).then(|| self.graph.nodes.get(i))?
    }

    /// The drawn edges touching a file, in edge order.
    fn edges_of(&self, i: usize) -> impl Iterator<Item = &Edge> {
        self.touching
            .get(i)
            .into_iter()
            .flatten()
            .map(|&e| &self.graph.edges[e])
            .filter(|e| self.edge_visible(e))
    }

    /// Edges touching a node, split into the ones it points at and the ones
    /// that point at it.
    pub fn connections(&self, i: usize) -> (Vec<&Edge>, Vec<&Edge>) {
        self.edges_of(i).partition(|e| e.from == i)
    }

    /// The files drawn joined to this one, each once however many edges run
    /// between them: the far ends of the lines the map draws for it.
    pub fn neighbors(&self, i: usize) -> Vec<usize> {
        let mut seen = HashSet::new();
        self.edges_of(i)
            .map(|e| if e.from == i { e.to } else { e.from })
            .filter(|other| seen.insert(*other))
            .collect()
    }

    /// Every drawn connection, with all the edges between a pair of files
    /// merged into one.
    ///
    /// Two files that share a dozen function names are one connection, not a
    /// dozen parallel lines. The lines were the tangle: the graph is keyed per
    /// symbol so that the detail strip can name them, but the picture only has
    /// to say *that* they are connected.
    pub fn links(&self) -> Vec<Link> {
        let mut seen = HashSet::new();
        self.graph
            .edges
            .iter()
            .filter(|e| self.edge_visible(e))
            .map(|e| Link {
                a: e.from.min(e.to),
                b: e.from.max(e.to),
            })
            .filter(|l| seen.insert((l.a, l.b)))
            .collect()
    }

    // ---- layout -----------------------------------------------------------

    /// Park the cursor on the first drawn node, used at build time and
    /// whenever a filter change strands it.
    fn select_first_visible(&mut self) {
        if let Some(i) = self.shown.iter().position(|s| *s) {
            self.selected = i;
        }
    }

    /// Put the cursor on the file with the most connections.
    ///
    /// Only used when the map is first opened, and only because the map draws
    /// the cursor's connections rather than everyone's: landing on whichever
    /// file happens to sort first would often mean opening on a picture with
    /// no lines in it. The busiest file is the one that says the most about
    /// how a project fits together, so it is the right thing to be looking at
    /// before you have asked for anything in particular.
    fn select_busiest(&mut self) {
        let degree = |i: usize| {
            self.touching[i]
                .iter()
                .filter(|&&e| self.kind_on(&self.graph.edges[e]))
                .count()
        };
        // The first of the busiest, so a project with no links at all opens
        // on its first file rather than its last.
        if let Some(i) = self
            .visible_indices()
            .into_iter()
            .max_by(|a, b| degree(*a).cmp(&degree(*b)).then(b.cmp(a)))
        {
            self.selected = i;
        }
    }

    /// Move to the nearest visible node in a direction.
    ///
    /// `(dx, dy)` is a unit vector. Each candidate is decomposed into distance
    /// *along* that direction and distance *across* it; anything with a
    /// non-positive `along` is behind the cursor and skipped. The score
    /// `along + across * 2.0` weights sideways displacement double, so the
    /// cursor prefers something straight ahead over something closer but well
    /// off-axis; otherwise arrow keys feel like they teleport.
    fn move_towards(&mut self, dx: f64, dy: f64) {
        let visible = self.visible_indices();
        if visible.is_empty() {
            return;
        }
        if !self.node_visible(self.selected) {
            self.selected = visible[0];
            return;
        }
        let (sx, sy) = self.pos[self.selected];
        let mut best: Option<(f64, usize)> = None;
        for i in visible {
            if i == self.selected {
                continue;
            }
            let (x, y) = self.pos[i];
            let (ox, oy) = (x - sx, y - sy);
            let along = ox * dx + oy * dy;
            if along <= 0.0 {
                continue; // behind us
            }
            let across = (ox * dy - oy * dx).abs();
            // Prefer straight ahead, then near. Weighting the sideways part
            // stops the cursor leaping across the graph to a distant node
            // that happens to be a degree off the axis.
            let score = along + across * 2.0;
            if best.is_none_or(|(b, _)| score < b) {
                best = Some((score, i));
            }
        }
        if let Some((_, i)) = best {
            self.selected = i;
        }
    }

    /// `Tab` / `Shift+Tab`: step through every visible node in index order,
    /// wrapping. The exhaustive alternative to spatial movement, for when a
    /// node is not reachable by arrow keys.
    fn cycle(&mut self, forward: bool) {
        let visible = self.visible_indices();
        if visible.is_empty() {
            return;
        }
        let at = visible.iter().position(|i| *i == self.selected);
        let next = match (at, forward) {
            (Some(p), true) => (p + 1) % visible.len(),
            (Some(p), false) => (p + visible.len() - 1) % visible.len(),
            (None, _) => 0,
        };
        self.selected = visible[next];
    }

    // ---- keys -------------------------------------------------------------

    /// Handle one keypress and say what, if anything, `App` should do.
    ///
    /// Takes what the key *meant* rather than the key: `App` resolves it, and
    /// anything the map has no binding for (every global chord, and the `/`
    /// that opens the bar) arrives as `None` and is left alone.
    pub fn on_key(&mut self, action: Option<Action>) -> Intent {
        let Some(action) = action else {
            return Intent::None;
        };
        match action {
            Action::Back => return Intent::Close,
            Action::Open => {
                if let Some(n) = self.selected_node() {
                    return Intent::Open(n.path.clone());
                }
            }
            Action::Left => self.move_towards(-1.0, 0.0),
            Action::Right => self.move_towards(1.0, 0.0),
            // Screen coordinates run downwards; the layout runs upwards.
            Action::Up => self.move_towards(0.0, 1.0),
            Action::Down => self.move_towards(0.0, -1.0),
            Action::MapNext => self.cycle(true),
            Action::MapPrevious => self.cycle(false),
            Action::MapWikilinks => self.toggle_kind(0),
            Action::MapLinks => self.toggle_kind(1),
            Action::MapCalls => self.toggle_kind(2),
            Action::Refresh => return Intent::Rebuild,
            _ => {}
        }
        Intent::None
    }

    /// Narrow the map to the paths containing `query`, and keep the cursor on
    /// something that is still drawn.
    ///
    /// Called by the bar. The map has no filter box of its own: filtering the
    /// map and searching the project are the same act, so they are the same
    /// field in the same place on screen, see `App::open_bar`.
    pub fn set_filter(&mut self, query: &str) {
        self.filter = query.trim().to_string();
        let wanted = self.filter.to_lowercase();
        for (shown, n) in self.shown.iter_mut().zip(&self.graph.nodes) {
            *shown = wanted.is_empty() || n.rel.to_lowercase().contains(&wanted);
        }
        self.ensure_selection();
        self.recount();
    }

    /// Turn one kind of connection on or off. No file is hidden by it (see
    /// [`ProjectMap::node_visible`]), so the cursor stays where it is.
    fn toggle_kind(&mut self, i: usize) {
        self.kinds[i] = !self.kinds[i];
        self.recount();
    }

    /// Count the connections drawn, for the title.
    fn recount(&mut self) {
        self.links_drawn = self.links().len();
    }

    /// Keep the cursor on something that is actually drawn.
    fn ensure_selection(&mut self) {
        if !self.node_visible(self.selected) {
            self.select_first_visible();
        }
    }

    /// One-line summary for the pane title.
    pub fn summary(&self) -> String {
        let shown = self.shown.iter().filter(|s| **s).count();
        // Connections, not edges: the picture draws one line per pair of
        // files, so counting per-symbol edges here would promise lines that
        // are not there.
        let links = self.links_drawn;
        let hidden = self.graph.nodes.len() - shown;
        let mut out = format!("{shown}/{} files | {links} links", self.graph.nodes.len());
        if hidden > 0 {
            out.push_str(&format!(" | {hidden} hidden"));
        }
        if self.graph.truncated {
            out.push_str(&format!(" | the first {} of more", graph::MAX_FILES));
        }
        out
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::map::testing::*;
    use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};

    // ---- what is shown ----------------------------------------------------

    #[test]
    fn turning_off_an_edge_kind_never_takes_a_file_off_the_map() {
        let (_td, mut view) = fixture();
        let all: Vec<String> = visible_names(&view).iter().map(|s| s.to_string()).collect();
        assert!(all.iter().any(|r| r == "notes/design.md"));

        // The notes are held on only by wikilinks, so switching those off
        // leaves nothing reaching them, but they are still files in the
        // project, and the map still has to show them.
        view.kinds[kind_index(EdgeKind::Wikilink)] = false;
        assert_eq!(
            visible_names(&view),
            all,
            "what a connection kind changes is the arrangement, not the census"
        );
        assert!(
            !view.connected(
                view.graph
                    .nodes
                    .iter()
                    .position(|n| n.rel == "notes/design.md")
                    .unwrap()
            )
        );
    }

    #[test]
    fn the_filter_narrows_to_matching_paths() {
        let (_td, mut view) = fixture();
        view.set_filter("src/");
        let shown = visible_names(&view);
        assert!(shown.iter().all(|r| r.starts_with("src/")), "{shown:?}");
        assert!(!shown.is_empty());
    }

    #[test]
    fn the_summary_counts_what_is_actually_drawn() {
        let (_td, view) = fixture();
        assert!(view.summary().contains("/5 files"), "{}", view.summary());
        assert!(view.summary().starts_with("5/5"), "{}", view.summary());
    }

    #[test]
    fn connections_are_split_into_outgoing_and_incoming() {
        let (_td, view) = fixture();
        let main = view
            .graph
            .nodes
            .iter()
            .position(|n| n.rel == "src/main.py")
            .unwrap();
        let (out, incoming) = view.connections(main);
        assert!(!out.is_empty(), "main.py calls utils.load");
        assert!(incoming.is_empty(), "nothing points at main.py");
        assert!(out.iter().all(|e| e.from == main));
    }

    // ---- moving around ----------------------------------------------------

    #[test]
    fn arrows_move_to_the_nearest_file_in_that_direction() {
        let (_td, mut view) = fixture();
        // Put two nodes in known places and check the cursor goes the right way.
        view.selected = 0;
        view.pos[0] = (0.0, 0.0);
        view.pos[1] = (100.0, 0.0);
        view.pos[2] = (-100.0, 0.0);
        view.pos[3] = (0.0, 100.0);
        view.pos[4] = (0.0, -100.0);

        view.on_key(act(k(KeyCode::Right)));
        assert_eq!(view.selected, 1);
        view.selected = 0;
        view.on_key(act(k(KeyCode::Left)));
        assert_eq!(view.selected, 2);
        view.selected = 0;
        view.on_key(act(k(KeyCode::Up)));
        assert_eq!(view.selected, 3, "up is up on screen");
        view.selected = 0;
        view.on_key(act(k(KeyCode::Down)));
        assert_eq!(view.selected, 4);
    }

    #[test]
    fn moving_towards_nothing_leaves_the_cursor_alone() {
        let (_td, mut view) = fixture();
        view.selected = 0;
        view.pos = vec![
            (0.0, 0.0),
            (-50.0, 0.0),
            (-60.0, 0.0),
            (-70.0, 0.0),
            (-80.0, 0.0),
        ];
        view.on_key(act(k(KeyCode::Right)));
        assert_eq!(view.selected, 0, "everything is to the left");
    }

    #[test]
    fn tab_cycles_through_every_visible_file_and_wraps() {
        let (_td, mut view) = fixture();
        let visible = view.visible_indices();
        view.selected = visible[0];
        for _ in 0..visible.len() {
            view.on_key(act(k(KeyCode::Tab)));
        }
        assert_eq!(view.selected, visible[0], "a full lap comes back round");
    }

    #[test]
    fn the_cursor_never_sits_on_something_hidden() {
        let (_td, mut view) = fixture();
        let alone = view
            .graph
            .nodes
            .iter()
            .position(|n| n.rel == "notes/alone.md")
            .unwrap();
        view.selected = alone;

        // The filter is the only thing that can take a file off the map now.
        view.set_filter("utils");
        assert!(
            view.node_visible(view.selected),
            "the cursor should have moved to something still drawn"
        );
    }

    #[test]
    fn a_file_nothing_reaches_is_still_on_the_map() {
        let (_td, view) = fixture();
        let alone = view
            .graph
            .nodes
            .iter()
            .position(|n| n.rel == "notes/alone.md")
            .unwrap();
        assert!(
            view.node_visible(alone),
            "a file with no links is part of the project too"
        );
        assert!(!view.connected(alone), "it just has nothing pointing at it");
    }

    #[test]
    fn unconnected_files_are_filed_under_their_own_heading_last() {
        let (_td, mut view) = fixture();
        let place = view.place(120, 60);
        let headings: Vec<&str> = place.folders.iter().map(|f| f.label.as_str()).collect();

        assert_eq!(
            headings.last(),
            Some(&"unconnected"),
            "and it comes after the folders, not among them: {headings:?}"
        );
        let lonely = place
            .folders
            .last()
            .expect("there is an unconnected heading");
        assert_eq!(lonely.files, 1, "just alone.md");
        assert!(
            headings.contains(&"notes/") && headings.contains(&"src/"),
            "the folders are still there: {headings:?}"
        );
    }

    #[test]
    fn turning_a_connection_kind_off_moves_its_files_to_unconnected() {
        let (_td, mut view) = fixture();
        let before = view.place(120, 60);
        let notes = before
            .folders
            .iter()
            .find(|f| f.label == "notes/")
            .expect("design and architecture link to each other")
            .files;
        assert_eq!(notes, 2, "alone.md is already elsewhere");

        // With wikilinks hidden, nothing reaches the two notes either.
        view.toggle_kind(0);
        let after = view.place(120, 60);
        let lonely = after
            .folders
            .iter()
            .find(|f| f.label == "unconnected")
            .expect("still a heading for them");
        assert_eq!(
            lonely.files, 3,
            "the map should say which files it has nothing to tell you about"
        );
    }

    // ---- keys -------------------------------------------------------------

    #[test]
    fn escape_closes_the_graph_and_nothing_else_does() {
        let (_td, mut view) = fixture();
        assert!(matches!(view.on_key(act(k(KeyCode::Esc))), Intent::Close));
        // `m` and `q` used to close it too. One window, one way out.
        for key in [ch('m'), ch('q')] {
            let (_td, mut view) = fixture();
            assert!(!matches!(view.on_key(act(key)), Intent::Close), "{key:?}");
        }
    }

    #[test]
    fn enter_asks_for_the_selected_file_to_be_opened() {
        let (td, mut view) = fixture();
        view.selected = view.visible_indices()[0];
        let want = view.graph.nodes[view.selected].path.clone();
        match view.on_key(act(k(KeyCode::Enter))) {
            Intent::Open(p) => {
                assert_eq!(p, want);
                assert!(p.starts_with(td.path()));
            }
            _ => panic!("Enter should open the file"),
        }
    }

    #[test]
    fn the_number_keys_toggle_edge_kinds() {
        let (_td, mut view) = fixture();
        assert!(view.kinds.iter().all(|k| *k));
        view.on_key(act(ch('3')));
        assert!(!view.kinds[kind_index(EdgeKind::Call)]);
        view.on_key(act(ch('3')));
        assert!(view.kinds[kind_index(EdgeKind::Call)]);
    }

    #[test]
    fn a_filter_narrows_the_map_and_clearing_it_brings_everything_back() {
        let (_td, mut view) = fixture();
        let all = visible_names(&view).len();

        view.set_filter("src");
        assert!(visible_names(&view).iter().all(|r| r.contains("src")));
        assert!(visible_names(&view).len() < all, "something was hidden");

        view.set_filter("");
        assert_eq!(visible_names(&view).len(), all, "and comes back");
    }

    #[test]
    fn a_key_the_map_does_not_use_does_nothing_at_all() {
        let (_td, mut view) = fixture();
        // `/` is the bar's, and the bar is opened by `App` before the map is
        // ever asked, so as far as the map is concerned it means nothing.
        assert!(matches!(view.on_key(None), Intent::None));
        assert!(matches!(view.on_key(act(ch('q'))), Intent::None));
        assert!(view.filter.is_empty());
    }

    #[test]
    fn control_chords_are_ignored_rather_than_acted_on() {
        let (_td, mut view) = fixture();
        let ctrl_c = KeyEvent {
            modifiers: KeyModifiers::CONTROL,
            ..ch('c')
        };
        assert!(matches!(view.on_key(act(ctrl_c)), Intent::None));
    }

    #[test]
    fn r_asks_for_the_project_to_be_read_again() {
        // Reading it is `App`'s; what the rebuilt map keeps is tested there.
        let (_td, mut view) = fixture();
        assert!(matches!(view.on_key(act(ch('r'))), Intent::Rebuild));
    }
}

files.src/parallel.rs:
//! Spreading one job over every core.
//!
//! The two things tiny does to a whole project at once (search it, and map
//! it) are a loop over files where no file needs another's answer. Reading
//! and parsing them one at a time leaves every core but one idle while the
//! user waits, so both hand the loop to [`par_map`] instead.
//!
//! Plain scoped threads rather than a thread-pool crate: the work arrives as
//! one batch, the threads live exactly as long as it, and nothing outlives the
//! call, which is all a pool would be for.

use std::sync::atomic::{AtomicUsize, Ordering};

/// `work` over every item on every core, each answer kept at its item's index
/// so the result is the same as a plain loop would give.
///
/// Items are handed out one at a time from a shared counter rather than split
/// into fixed chunks up front, because what they cost is wildly uneven (one
/// generated parser is worth a thousand notes) and a fixed split leaves
/// cores idle behind whichever chunk drew the expensive ones. Each thread
/// gets its own `state`, for things like a tree-sitter context that cannot be
/// shared.
pub fn par_map<T: Sync, R: Send, S>(
    items: &[T],
    state: impl Fn() -> S + Sync,
    work: impl Fn(&mut S, usize, &T) -> R + Sync,
) -> Vec<R> {
    let threads = std::thread::available_parallelism()
        .map_or(1, |n| n.get())
        .min(items.len());
    let next = AtomicUsize::new(0);
    let mut out: Vec<Option<R>> = (0..items.len()).map(|_| None).collect();
    std::thread::scope(|scope| {
        let workers: Vec<_> = (0..threads)
            .map(|_| {
                scope.spawn(|| {
                    let mut st = state();
                    let mut done = Vec::new();
                    loop {
                        let i = next.fetch_add(1, Ordering::Relaxed);
                        let Some(item) = items.get(i) else { break };
                        done.push((i, work(&mut st, i, item)));
                    }
                    done
                })
            })
            .collect();
        for worker in workers {
            for (i, r) in worker.join().expect("a worker thread panicked") {
                out[i] = Some(r);
            }
        }
    });
    out.into_iter()
        .map(|r| r.expect("every item is taken by some worker"))
        .collect()
}

/// How many threads [`par_map`] will use, for callers that size their batches
/// by it.
pub fn threads() -> usize {
    std::thread::available_parallelism().map_or(1, |n| n.get())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn answers_come_back_in_the_order_of_the_items() {
        let items: Vec<usize> = (0..1000).collect();
        let out = par_map(&items, || (), |_, i, x| (i, x * 2));
        for (n, (i, doubled)) in out.into_iter().enumerate() {
            assert_eq!((i, doubled), (n, n * 2));
        }
    }

    #[test]
    fn nothing_to_do_is_nothing_done() {
        let out: Vec<u8> = par_map(&[] as &[u8], || (), |_, _, x| *x);
        assert!(out.is_empty());
    }
}

files.src/plugins.rs:
//! Plugins: Lua files that add commands to tiny, and act when a file is opened
//! or saved.
//!
//! # What a plugin is, and where it goes
//!
//! A plugin is a `.lua` file in the plugins folder (`~/.config/tiny/plugins`,
//! or `%APPDATA%\tiny\plugins` on Windows, which the settings area's `Plugins`
//! button opens) or a folder there with an `init.lua` in it, for a plugin
//! that wants more than one file. Every one is loaded when tiny starts, and
//! again on `*reload`.
//!
//! The same file works on every system. Lua is compiled into tiny, so a plugin
//! needs nothing installed and nothing built: drop it in, and it runs.
//!
//! # What a plugin can do
//!
//! Everything goes through one table, `tiny`:
//!
//! ```lua
//! tiny.command("words", function(args) end) -- `*words` runs it
//! tiny.on("save", function(path) end)       -- and "open"
//! tiny.status("hello")                      -- the status line
//! tiny.text()   tiny.set_text(s)            -- the file being edited
//! tiny.insert(s)                            -- at the cursor
//! tiny.cursor() tiny.go(line, col)          -- counted from 1
//! tiny.path()   tiny.root()                 -- the file, the project
//! tiny.open(path)                           -- a file, in tiny
//! tiny.set("glyphs", "ascii")               -- any setting, as *set
//! tiny.version
//! ```
//!
//! What a plugin asks for while it loads (at the top of its file, outside any
//! function) is carried out once every plugin has loaded. That is where a
//! plugin that sets up tiny's look calls `tiny.set`.
//!
//! A command a plugin adds cannot replace one tiny has: `*delete` always means
//! tiny's own delete, whatever is installed.
//!
//! # Why a plugin never touches `App`
//!
//! A plugin runs while tiny is in the middle of handling a key, with `App`
//! borrowed. So nothing a plugin calls reaches into it. Each call is handed a
//! [`Snapshot`] of what it can read, and gives back the [`Effect`]s it asked
//! for, in order; `App` carries them out once the plugin has returned. A plugin
//! never sees tiny half way through something, and never leaves it that way.
//!
//! # A plugin cannot hang tiny
//!
//! Lua runs on tiny's own thread, so a plugin stuck in a loop would freeze the
//! window. Every call has a deadline ([`PATIENCE`]) checked every few
//! thousand instructions, and a call that runs past it is stopped with an
//! error naming the plugin. An error is all a broken plugin can cause: it is
//! reported on the status line, and tiny carries on.

use std::cell::RefCell;
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::rc::Rc;
use std::time::{Duration, Instant};

use mlua::{Function, HookTriggers, Lua, VmState};

/// How long one call into a plugin may run before it is stopped.
pub const PATIENCE: Duration = Duration::from_secs(2);

/// What a plugin can ask to be told about.
const EVENTS: &[&str] = &["open", "save"];

/// What a plugin can read during a call: the state of tiny as it was when the
/// plugin was called.
#[derive(Debug, Clone, Default)]
pub struct Snapshot {
    /// The project folder.
    pub root: String,
    /// What the cursor is on, if anything.
    pub path: Option<String>,
    /// The file being edited, if one is open.
    pub text: Option<String>,
    /// Its cursor, as line and column counted from 1.
    pub cursor: Option<(usize, usize)>,
}

/// Something a plugin asked for, carried out once it has returned.
#[derive(Debug, Clone, PartialEq)]
pub enum Effect {
    Status(String),
    /// Replace the whole file being edited.
    SetText(String),
    /// Put text in at the cursor.
    Insert(String),
    /// Move the cursor to a line and column, counted from 1.
    Go(usize, usize),
    /// Open a file: a path from the project folder, or an absolute one.
    Open(String),
    /// Change a setting, the way `*set` does: for this run, and written to
    /// `tiny.conf` only if the settings area is saved.
    Set(String, String),
}

/// What the plugins and tiny share while a plugin runs.
#[derive(Default)]
struct Shared {
    /// The plugin being loaded, so what it registers is filed under its name.
    loading: String,
    /// `*name` → the plugin that added it, and its function.
    commands: BTreeMap<String, (String, Function)>,
    /// Event, plugin, function, in the order they were registered.
    hooks: Vec<(String, String, Function)>,
    snapshot: Snapshot,
    effects: Vec<Effect>,
    /// When the running call has to stop.
    deadline: Option<Instant>,
}

/// Every plugin, loaded.
#[derive(Default)]
pub struct Plugins {
    /// `None` until there is a plugin to run: a tiny with no plugins starts no
    /// Lua at all.
    lua: Option<Lua>,
    shared: Rc<RefCell<Shared>>,
    /// The plugins that loaded, by name.
    pub loaded: Vec<String>,
    /// What the plugins asked for while they loaded, in order, waiting for
    /// `App` to carry it out. A plugin that failed to load asks for nothing.
    pub startup: Vec<Effect>,
    /// One line for each that did not, saying why.
    pub errors: Vec<String>,
}

impl Plugins {
    /// Load every plugin in `dir`, for the project at `root`. A folder that
    /// is not there is no plugins, which is the ordinary case and not an
    /// error.
    pub fn load(dir: &Path, root: &Path) -> Self {
        let mut plugins = Plugins::default();
        let found = Self::find(dir);
        if found.is_empty() {
            return plugins;
        }
        let lua = Lua::new();
        if let Err(e) = plugins.install(&lua, dir) {
            plugins.errors.push(format!("plugins: {}", first_line(&e)));
            return plugins;
        }
        // What a plugin's top level can ask about: the project, and nothing
        // open yet.
        plugins.shared.borrow_mut().snapshot = Snapshot {
            root: root.to_string_lossy().into_owned(),
            ..Snapshot::default()
        };
        for (name, file) in found {
            plugins.shared.borrow_mut().loading = name.clone();
            let ran = std::fs::read_to_string(&file)
                .map_err(|e| e.to_string())
                .and_then(|source| {
                    // Notepad on older Windows starts a UTF-8 file with a
                    // byte order mark, which Lua reads as a syntax error.
                    let source = source.strip_prefix('\u{feff}').unwrap_or(&source);
                    with_deadline(&plugins.shared, || {
                        lua.load(source)
                            .set_name(format!("@{}", display(&file, dir)))
                            .exec()
                    })
                    .map_err(|e| first_line(&e))
                });
            // Taken either way, so one plugin's requests never leak into the
            // next one's, and kept only from a plugin that loaded.
            let asked = std::mem::take(&mut plugins.shared.borrow_mut().effects);
            match ran {
                Ok(()) => {
                    plugins.startup.extend(asked);
                    plugins.loaded.push(name);
                }
                Err(e) => {
                    // A plugin that failed half way through loading takes
                    // back the half it got through: its commands and hooks
                    // were registered for a plugin that is not there.
                    let mut s = plugins.shared.borrow_mut();
                    s.commands.retain(|_, (owner, _)| *owner != name);
                    s.hooks.retain(|(_, owner, _)| *owner != name);
                    drop(s);
                    plugins.errors.push(format!("{name}: {e}"));
                }
            }
        }
        plugins.lua = Some(lua);
        plugins
    }

    /// The plugins in `dir`, by name, in the order they load: alphabetical,
    /// so it is the same on every machine.
    fn find(dir: &Path) -> Vec<(String, PathBuf)> {
        let Ok(entries) = std::fs::read_dir(dir) else {
            return Vec::new();
        };
        let mut found: Vec<(String, PathBuf)> = entries
            .flatten()
            .filter_map(|entry| {
                let path = entry.path();
                let name = path.file_stem()?.to_string_lossy().into_owned();
                if path.is_dir() {
                    let init = path.join("init.lua");
                    init.is_file().then_some((name, init))
                } else if path.extension().is_some_and(|e| e == "lua") {
                    Some((name, path))
                } else {
                    None
                }
            })
            .collect();
        found.sort();
        found
    }

    /// Give Lua the `tiny` table, the plugins folder to `require` from, and
    /// the deadline.
    fn install(&self, lua: &Lua, dir: &Path) -> mlua::Result<()> {
        let tiny = lua.create_table()?;
        tiny.set("version", crate::update::running())?;

        let shared = self.shared.clone();
        tiny.set(
            "command",
            lua.create_function(move |_, (name, f): (String, Function)| {
                let mut s = shared.borrow_mut();
                let owner = s.loading.clone();
                s.commands.insert(name, (owner, f));
                Ok(())
            })?,
        )?;

        let shared = self.shared.clone();
        tiny.set(
            "on",
            lua.create_function(move |_, (event, f): (String, Function)| {
                if !EVENTS.contains(&event.as_str()) {
                    return Err(mlua::Error::RuntimeError(format!(
                        "there is no event called `{event}`; there is {}",
                        EVENTS.join(" and ")
                    )));
                }
                let mut s = shared.borrow_mut();
                let owner = s.loading.clone();
                s.hooks.push((event, owner, f));
                Ok(())
            })?,
        )?;

        let shared = self.shared.clone();
        tiny.set(
            "root",
            lua.create_function(move |_, ()| Ok(shared.borrow().snapshot.root.clone()))?,
        )?;
        let shared = self.shared.clone();
        tiny.set(
            "path",
            lua.create_function(move |_, ()| Ok(shared.borrow().snapshot.path.clone()))?,
        )?;
        let shared = self.shared.clone();
        tiny.set(
            "text",
            lua.create_function(move |_, ()| Ok(shared.borrow().snapshot.text.clone()))?,
        )?;
        let shared = self.shared.clone();
        tiny.set(
            "cursor",
            lua.create_function(move |_, ()| {
                let cursor = shared.borrow().snapshot.cursor;
                Ok((cursor.map(|c| c.0), cursor.map(|c| c.1)))
            })?,
        )?;

        let shared = self.shared.clone();
        tiny.set(
            "status",
            lua.create_function(move |_, message: String| {
                shared.borrow_mut().effects.push(Effect::Status(message));
                Ok(())
            })?,
        )?;
        let shared = self.shared.clone();
        tiny.set(
            "set_text",
            lua.create_function(move |_, text: String| {
                let mut s = shared.borrow_mut();
                if s.snapshot.text.is_none() {
                    return Err(no_file());
                }
                // What `tiny.text()` says from here on, in this same call.
                s.snapshot.text = Some(text.clone());
                s.effects.push(Effect::SetText(text));
                Ok(())
            })?,
        )?;
        let shared = self.shared.clone();
        tiny.set(
            "insert",
            lua.create_function(move |_, text: String| {
                let mut s = shared.borrow_mut();
                if s.snapshot.text.is_none() {
                    return Err(no_file());
                }
                s.effects.push(Effect::Insert(text));
                Ok(())
            })?,
        )?;
        let shared = self.shared.clone();
        tiny.set(
            "go",
            lua.create_function(move |_, (line, col): (usize, Option<usize>)| {
                let mut s = shared.borrow_mut();
                if s.snapshot.text.is_none() {
                    return Err(no_file());
                }
                s.effects
                    .push(Effect::Go(line.max(1), col.unwrap_or(1).max(1)));
                Ok(())
            })?,
        )?;
        let shared = self.shared.clone();
        tiny.set(
            "open",
            lua.create_function(move |_, path: String| {
                shared.borrow_mut().effects.push(Effect::Open(path));
                Ok(())
            })?,
        )?;
        let shared = self.shared.clone();
        tiny.set(
            "set",
            lua.create_function(move |_, (name, value): (String, mlua::Value)| {
                let value = match value {
                    mlua::Value::String(s) => s.to_str()?.to_string(),
                    mlua::Value::Integer(n) => n.to_string(),
                    mlua::Value::Number(n) => n.to_string(),
                    mlua::Value::Boolean(b) => b.to_string(),
                    other => {
                        return Err(mlua::Error::RuntimeError(format!(
                            "a setting is text, a number or true or false, not a {}",
                            other.type_name()
                        )));
                    }
                };
                // Tried against a spare config first, so a misspelled name or
                // a value that will not parse is an error at the line of Lua
                // that wrote it, rather than a status message later.
                crate::config::Config::default()
                    .set(&name, &value)
                    .map_err(|e| mlua::Error::RuntimeError(e.to_string()))?;
                shared.borrow_mut().effects.push(Effect::Set(name, value));
                Ok(())
            })?,
        )?;
        lua.globals().set("tiny", tiny)?;

        // `require("mine.helpers")` finds `plugins/mine/helpers.lua`, so a
        // plugin in a folder can be more than one file.
        let package: mlua::Table = lua.globals().get("package")?;
        let path: String = package.get("path")?;
        let ours = format!(
            "{};{}",
            dir.join("?.lua").display(),
            dir.join("?").join("init.lua").display()
        );
        package.set("path", format!("{ours};{path}"))?;

        // Global, so a coroutine a plugin starts is held to it too.
        let shared = self.shared.clone();
        lua.set_global_hook(
            HookTriggers::new().every_nth_instruction(10_000),
            move |_, _| match shared.borrow().deadline {
                Some(deadline) if Instant::now() > deadline => {
                    Err(mlua::Error::RuntimeError(format!(
                        "took longer than {} seconds, and was stopped",
                        PATIENCE.as_secs()
                    )))
                }
                _ => Ok(VmState::Continue),
            },
        )
    }

    /// Every command a plugin added, by name, for completion and the help.
    pub fn commands(&self) -> Vec<String> {
        self.shared.borrow().commands.keys().cloned().collect()
    }

    /// The plugin that added `*name`, if one did.
    pub fn command_owner(&self, name: &str) -> Option<String> {
        self.shared
            .borrow()
            .commands
            .get(name)
            .map(|(owner, _)| owner.clone())
    }

    /// Run `*name`, if a plugin added it. `None` when none did; otherwise
    /// what the plugin asked for, or what went wrong.
    pub fn run(
        &self,
        name: &str,
        args: &[String],
        snapshot: Snapshot,
    ) -> Option<Result<Vec<Effect>, String>> {
        let lua = self.lua.as_ref()?;
        // Cloned out, so nothing is borrowed while the plugin runs and the
        // `tiny` functions it calls borrow in their turn.
        let (owner, f) = self.shared.borrow().commands.get(name).cloned()?;
        Some(self.call(&owner, snapshot, || {
            let args = lua.create_sequence_from(args.iter().cloned())?;
            f.call::<()>(args)
        }))
    }

    /// Whether any plugin listens for `event`, so tiny can skip putting a
    /// snapshot together for nobody.
    pub fn listens(&self, event: &str) -> bool {
        self.shared.borrow().hooks.iter().any(|(e, ..)| e == event)
    }

    /// Tell every plugin listening for `event` about `path`. Returns what they
    /// asked for, and one line for each that failed.
    pub fn fire(&self, event: &str, path: &Path, snapshot: Snapshot) -> (Vec<Effect>, Vec<String>) {
        let listening: Vec<(String, Function)> = self
            .shared
            .borrow()
            .hooks
            .iter()
            .filter(|(e, ..)| e == event)
            .map(|(_, owner, f)| (owner.clone(), f.clone()))
            .collect();
        let path = path.to_string_lossy().into_owned();
        let (mut effects, mut errors) = (Vec::new(), Vec::new());
        for (owner, f) in listening {
            match self.call(&owner, snapshot.clone(), || f.call::<()>(path.clone())) {
                Ok(asked) => effects.extend(asked),
                Err(e) => errors.push(e),
            }
        }
        (effects, errors)
    }

    /// One call into a plugin: hand it `snapshot`, run it against the
    /// deadline, and take back what it asked for. A call that fails asks for
    /// nothing: half of what a broken plugin meant to do is not worth doing.
    fn call(
        &self,
        owner: &str,
        snapshot: Snapshot,
        run: impl FnOnce() -> mlua::Result<()>,
    ) -> Result<Vec<Effect>, String> {
        {
            let mut s = self.shared.borrow_mut();
            s.snapshot = snapshot;
            s.effects.clear();
        }
        let result = with_deadline(&self.shared, run);
        let effects = std::mem::take(&mut self.shared.borrow_mut().effects);
        match result {
            Ok(()) => Ok(effects),
            Err(e) => Err(format!("{owner}: {}", first_line(&e))),
        }
    }
}

/// Run `f` with the deadline set, and cleared again afterwards however it
/// went.
fn with_deadline<T>(shared: &Rc<RefCell<Shared>>, f: impl FnOnce() -> T) -> T {
    shared.borrow_mut().deadline = Some(Instant::now() + PATIENCE);
    let result = f();
    shared.borrow_mut().deadline = None;
    result
}

/// The error for an editing call made with no file open.
fn no_file() -> mlua::Error {
    mlua::Error::RuntimeError("no file is open to edit".into())
}

/// A file's path from the plugins folder, for error messages: `words.lua`,
/// or `mine/init.lua`.
fn display(file: &Path, dir: &Path) -> String {
    file.strip_prefix(dir)
        .unwrap_or(file)
        .to_string_lossy()
        .replace('\\', "/")
}

/// The part of a Lua error worth a status line: what went wrong and where,
/// without the traceback.
fn first_line(e: &mlua::Error) -> String {
    let text = match e {
        mlua::Error::CallbackError { cause, .. } => cause.to_string(),
        other => other.to_string(),
    };
    let line = text.lines().next().unwrap_or("").trim();
    line.strip_prefix("runtime error: ")
        .unwrap_or(line)
        .to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn folder(files: &[(&str, &str)]) -> tempfile::TempDir {
        let td = tempfile::tempdir().unwrap();
        for (name, source) in files {
            let path = td.path().join(name);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(path, source).unwrap();
        }
        td
    }

    fn editing(text: &str) -> Snapshot {
        Snapshot {
            root: "/project".into(),
            path: Some("/project/notes.md".into()),
            text: Some(text.into()),
            cursor: Some((1, 1)),
        }
    }

    #[test]
    fn a_folder_with_no_plugins_starts_no_lua() {
        let td = folder(&[("notes.txt", "not a plugin")]);
        let plugins = Plugins::load(td.path(), td.path());
        assert!(plugins.lua.is_none());
        assert!(plugins.loaded.is_empty() && plugins.errors.is_empty());
        let missing = Plugins::load(&td.path().join("nope"), td.path());
        assert!(missing.loaded.is_empty() && missing.errors.is_empty());
    }

    #[test]
    fn a_plugin_adds_a_command_that_reads_the_file_and_says_so() {
        let td = folder(&[(
            "words.lua",
            r#"
            tiny.command("words", function(args)
              local n = 0
              for _ in tiny.text():gmatch("%S+") do n = n + 1 end
              tiny.status(n .. " words, " .. #args .. " args")
            end)
            "#,
        )]);
        let plugins = Plugins::load(td.path(), td.path());
        assert_eq!(plugins.loaded, ["words"]);
        assert_eq!(plugins.commands(), ["words"]);
        let effects = plugins
            .run("words", &["a".into()], editing("one two three"))
            .expect("the plugin answers")
            .expect("and does not fail");
        assert_eq!(effects, [Effect::Status("3 words, 1 args".into())]);
    }

    #[test]
    fn edits_come_back_in_the_order_they_were_asked_for() {
        let td = folder(&[(
            "shout.lua",
            r#"
            tiny.command("shout", function()
              tiny.set_text(tiny.text():upper())
              tiny.insert("!")
              tiny.go(2, 3)
              tiny.open("other.md")
            end)
            "#,
        )]);
        let plugins = Plugins::load(td.path(), td.path());
        let effects = plugins.run("shout", &[], editing("hey")).unwrap().unwrap();
        assert_eq!(
            effects,
            [
                Effect::SetText("HEY".into()),
                Effect::Insert("!".into()),
                Effect::Go(2, 3),
                Effect::Open("other.md".into()),
            ]
        );
    }

    #[test]
    fn a_plugin_hears_about_saves() {
        let td = folder(&[(
            "log.lua",
            r#"tiny.on("save", function(path) tiny.status("saved " .. path) end)"#,
        )]);
        let plugins = Plugins::load(td.path(), td.path());
        let (effects, errors) = plugins.fire("save", Path::new("/p/a.md"), editing(""));
        assert!(errors.is_empty(), "{errors:?}");
        assert_eq!(effects, [Effect::Status("saved /p/a.md".into())]);
        let (effects, _) = plugins.fire("open", Path::new("/p/a.md"), editing(""));
        assert!(effects.is_empty(), "nobody asked to hear about opening");
    }

    #[test]
    fn a_broken_plugin_is_reported_and_the_rest_still_load() {
        let td = folder(&[
            ("a_broken.lua", "this is not lua"),
            ("b_fine.lua", r#"tiny.command("fine", function() end)"#),
        ]);
        let plugins = Plugins::load(td.path(), td.path());
        assert_eq!(plugins.loaded, ["b_fine"]);
        assert_eq!(plugins.errors.len(), 1);
        assert!(
            plugins.errors[0].starts_with("a_broken: "),
            "{:?}",
            plugins.errors
        );
        assert!(plugins.errors[0].contains("a_broken.lua"), "it says where");
    }

    #[test]
    fn a_plugin_that_fails_half_way_through_loading_leaves_nothing_behind() {
        let td = folder(&[(
            "half.lua",
            r#"
            tiny.command("early", function() end)
            tiny.on("save", function() tiny.status("saw it") end)
            error("and then it broke")
            "#,
        )]);
        let plugins = Plugins::load(td.path(), td.path());
        assert!(plugins.loaded.is_empty());
        assert!(
            plugins.commands().is_empty(),
            "the command it added before the error is gone"
        );
        assert!(!plugins.listens("save"), "and so is its hook");
    }

    #[test]
    fn a_plugin_saved_with_a_byte_order_mark_still_loads() {
        let td = folder(&[("bom.lua", "\u{feff}tiny.command(\"bom\", function() end)")]);
        let plugins = Plugins::load(td.path(), td.path());
        assert_eq!(plugins.loaded, ["bom"], "{:?}", plugins.errors);
    }

    #[test]
    fn a_plugin_can_ask_where_the_project_is_while_it_loads() {
        let td = folder(&[("where.lua", r#"tiny.status(tiny.root())"#)]);
        let plugins = Plugins::load(td.path(), Path::new("/projects/notes"));
        assert_eq!(
            plugins.startup,
            [Effect::Status("/projects/notes".into())],
            "{:?}",
            plugins.errors
        );
    }

    #[test]
    fn an_error_while_running_names_the_plugin_and_asks_for_nothing() {
        let td = folder(&[(
            "oops.lua",
            r#"tiny.command("oops", function() tiny.status("half") error("broke") end)"#,
        )]);
        let plugins = Plugins::load(td.path(), td.path());
        let err = plugins.run("oops", &[], editing("")).unwrap().unwrap_err();
        assert!(err.starts_with("oops: "), "{err}");
        assert!(err.contains("broke"), "{err}");
    }

    #[test]
    fn a_plugin_that_never_finishes_is_stopped() {
        let td = folder(&[(
            "spin.lua",
            r#"tiny.command("spin", function() while true do end end)"#,
        )]);
        let plugins = Plugins::load(td.path(), td.path());
        let started = Instant::now();
        let err = plugins.run("spin", &[], editing("")).unwrap().unwrap_err();
        assert!(err.contains("stopped"), "{err}");
        assert!(started.elapsed() < PATIENCE * 3, "and promptly");
    }

    #[test]
    fn editing_with_no_file_open_says_so() {
        let td = folder(&[(
            "edit.lua",
            r#"tiny.command("edit", function() tiny.insert("x") end)"#,
        )]);
        let plugins = Plugins::load(td.path(), td.path());
        let browsing = Snapshot {
            root: "/project".into(),
            ..Snapshot::default()
        };
        let err = plugins.run("edit", &[], browsing).unwrap().unwrap_err();
        assert!(err.contains("no file is open"), "{err}");
    }

    #[test]
    fn a_plugin_in_a_folder_can_require_its_own_files() {
        let td = folder(&[
            (
                "mine/init.lua",
                r#"local h = require("mine.helpers")
                   tiny.command("mine", function() tiny.status(h.greet()) end)"#,
            ),
            (
                "mine/helpers.lua",
                r#"return { greet = function() return "hi" end }"#,
            ),
        ]);
        let plugins = Plugins::load(td.path(), td.path());
        assert_eq!(plugins.loaded, ["mine"], "{:?}", plugins.errors);
        let effects = plugins.run("mine", &[], editing("")).unwrap().unwrap();
        assert_eq!(effects, [Effect::Status("hi".into())]);
    }

    #[test]
    fn an_unknown_event_is_refused_by_name() {
        let td = folder(&[("bad.lua", r#"tiny.on("sav", function() end)"#)]);
        let plugins = Plugins::load(td.path(), td.path());
        assert!(plugins.errors[0].contains("`sav`"), "{:?}", plugins.errors);
    }

    #[test]
    fn a_command_nobody_added_is_none() {
        let td = folder(&[("x.lua", "")]);
        let plugins = Plugins::load(td.path(), td.path());
        assert!(plugins.run("nothing", &[], editing("")).is_none());
        assert_eq!(plugins.command_owner("nothing"), None);
    }
}

