//! The source-control window: `Ctrl+G`.
//!
//! Three parts, laid out the way the questions are asked. On the left, what has
//! changed. On the right, the file the cursor is on: before on one side, after
//! on the other. Underneath, the branch map, because "what have I done" and
//! "where am I" are the two halves of the same look.
//!
//! # Reading across, not down
//!
//! The two halves of the diff are drawn from [`crate::git::Diff`], whose sides are the
//! same length by construction: where one has a line the other does not, the
//! other has a blank. So line 12 on the left is the same place in the file as
//! line 12 on the right, and the eye can read across without counting.
//!
//! # Color is the code
//!
//! The letter and the color say the same thing twice on purpose: the letters
//! are git's own, and on a terminal with no color the window still works.

use ratatui::Frame;
use ratatui::layout::{Constraint, Direction, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, Borders, Paragraph};

use super::parts::highlight_row;

use crate::app::{App, Divider, GIT_BUTTONS, GitFocus, GitHit, GitRow, Moves};
use crate::config::Palette;
use crate::config::keys::Action;
use crate::git::{Code, DiffLine, LineKind};
use crate::text::highlight::Piece;
use crate::text::tabs;
use unicode_width::UnicodeWidthStr;

/// How many rows the branch map gets, when there is room for it at all.
const GRAPH_HEIGHT: u16 = 8;

/// The color of a status letter.
///
/// Git's own scheme is two colors (green for staged, red for not) which
/// says where a change is but not what it is. These say what it is, which is
/// the question the letter answers too.
fn code_style(code: Code, pal: &Palette) -> Style {
    let color = match code {
        Code::Added => Color::Green,
        Code::Modified => Color::Yellow,
        Code::Deleted => Color::Red,
        Code::Renamed => Color::Cyan,
        Code::Copied => Color::Magenta,
        Code::Untracked => Color::Blue,
        Code::Conflict => Color::LightRed,
    };
    pal.text.fg(color).add_modifier(Modifier::BOLD)
}

pub(super) fn draw_source(f: &mut Frame, app: &mut App, area: Rect) {
    let pal = app.palette;

    // The map goes at the bottom and gives up its space first: on a short
    // window, what has changed matters more than what happened before.
    let graph_h = if area.height >= 20 && !app.git.graph.is_empty() {
        GRAPH_HEIGHT
    } else {
        0
    };
    let rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Min(6), Constraint::Length(graph_h)])
        .split(area);

    // The list is as wide as the browser, and its edge moves the same way.
    let room = rows[0];
    let w = f32::from(room.width);
    let width = app.config.tree_width.clamp(0.15, 0.5);
    let (lo, hi) = (
        (w * 0.15).ceil() as u16,
        ((w * 0.5) as u16).min(room.width.saturating_sub(20)),
    );
    let list_w = ((w * width).round() as u16).clamp(lo.min(hi), hi);
    let columns = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Length(list_w), Constraint::Min(20)])
        .split(room);
    app.last_dividers.push(Divider::new(
        Moves::Changes { area: room },
        room,
        true,
        columns[1].x,
        (room.x + lo, room.x + hi),
    ));

    draw_changes(f, app, columns[0], &pal);
    // The message box stands in for both diff columns rather than squeezing in
    // beside them: writing is the only thing happening while it is open, and a
    // paragraph wants the width.
    if app.git.message.is_some() {
        draw_message(f, app, columns[1], &pal);
    } else {
        draw_diff(f, app, columns[1], &pal);
    }
    app.git.diff_area = Some(columns[1]);
    if graph_h > 0 {
        draw_graph(f, app, rows[1], &pal);
    }
}

/// The left column: buttons, then what has changed, in two sections.
///
/// Steps back when the keyboard is not in it, exactly as the browser does in
/// the main window: dim border, dim title, and the cursor's row shown quietly
/// rather than reversed. Two panes that both hold a list have to say "you are
/// not typing here" the same way, or the answer to "which one is live" becomes
/// a thing you work out instead of see.
///
/// Scrolls the way the browser does too: by as little as keeps the cursor's
/// row on screen. Counted in drawn lines rather than rows, because the button
/// row wraps to as many lines as the width needs.
fn draw_changes(f: &mut Frame, app: &mut App, area: Rect, pal: &Palette) {
    let git = &app.git;
    let focused = git.focus == GitFocus::List;
    let after = match (&git.error, &git.job) {
        (Some(_), _) => String::new(),
        (_, Some(job)) => format!(" {}{} ", job.what, pal.glyphs.ellipsis),
        _ => format!(" {} ", git.status.branch.summary(pal.glyphs.arrow)),
    };
    let block = Block::default()
        .borders(Borders::ALL)
        .border_set(pal.glyphs.border)
        .border_style(if focused {
            pal.border_focus
        } else {
            pal.border
        })
        .title(Line::from(vec![
            Span::raw(" "),
            Span::styled(
                "SOURCE CONTROL",
                if focused {
                    pal.text.add_modifier(Modifier::BOLD)
                } else {
                    pal.dim
                },
            ),
            Span::styled(after, pal.dim),
        ]));
    let inner = block.inner(area);

    if let Some(error) = &git.error {
        let lines = vec![
            Line::from(Span::styled(format!("  {error}"), pal.marker)),
            Line::from(""),
            Line::from(Span::styled("  Esc back to the browser", pal.dim)),
        ];
        f.render_widget(block, area);
        f.render_widget(Paragraph::new(lines), inner);
        return;
    }

    let mut lines: Vec<Line> = Vec::new();
    // Which row each line is of, and where its buttons are, for the mouse.
    let mut line_rows: Vec<(usize, Spots)> = Vec::new();
    // The lines the cursor's row was drawn on.
    let mut cursor = 0..0;
    for (i, row) in git.rows.iter().enumerate() {
        let on = i == git.selected;
        let first = lines.len();
        match row {
            GitRow::Buttons => {
                for (line, buttons) in button_lines(git.button, on && focused, inner.width, pal) {
                    lines.push(line);
                    line_rows.push((i, buttons));
                }
            }
            GitRow::Header { staged } => {
                let (word, n) = if *staged {
                    ("STAGED", git.status.staged.len())
                } else {
                    ("UNSTAGED", git.status.unstaged.len())
                };
                let mut spans = vec![Span::styled(format!(" {word} {n}"), pal.heading)];
                if on {
                    highlight_row(&mut spans, inner.width as usize, *pal, focused);
                }
                lines.push(Line::from(spans));
                line_rows.push((i, Vec::new()));
            }
            GitRow::File { staged, index } => {
                let list = if *staged {
                    &git.status.staged
                } else {
                    &git.status.unstaged
                };
                let Some(change) = list.get(*index) else {
                    continue;
                };
                let mut spans = vec![
                    Span::styled(
                        format!(" {} ", change.code.letter()),
                        code_style(change.code, pal),
                    ),
                    Span::styled(change.label(pal.glyphs.arrow), pal.text),
                ];
                // The same full-width bar the browser draws, and the same
                // quiet version of it when the keyboard is elsewhere.
                if on {
                    highlight_row(&mut spans, inner.width as usize, *pal, focused);
                }
                lines.push(Line::from(spans));
                line_rows.push((i, Vec::new()));
            }
        }
        if on {
            cursor = first..lines.len();
        }
    }
    if git.rows.len() <= 1 {
        lines.push(Line::from(Span::styled("  nothing to commit", pal.dim)));
    }

    let height = inner.height as usize;
    let mut scroll = app.git.list_scroll;
    if cursor.start < scroll {
        scroll = cursor.start;
    } else if cursor.end > scroll + height {
        // A row taller than the pane shows its top.
        scroll = (cursor.end - height).min(cursor.start);
    }
    let scroll = scroll.min(lines.len().saturating_sub(height));
    app.git.list_scroll = scroll;
    app.git.list_cols = Some((area.x, area.x + area.width));
    app.git.list_hits = line_rows
        .into_iter()
        .enumerate()
        .skip(scroll)
        .take(height)
        .map(|(k, (row, buttons))| GitHit {
            y: inner.y + (k - scroll) as u16,
            row,
            buttons: buttons
                .into_iter()
                .map(|(x0, x1, b)| (inner.x + x0, inner.x + x1, b))
                .collect(),
        })
        .collect();

    // What is out of sight below, said on the border, since a list cut off
    // at a row boundary looks exactly like a list that ends there.
    let below = lines.len().saturating_sub(scroll + height);
    let block = if below > 0 {
        block.title_bottom(
            Line::from(Span::styled(format!(" {below} more "), pal.dim)).right_aligned(),
        )
    } else {
        block
    };
    f.render_widget(block, area);
    let shown: Vec<Line> = lines.into_iter().skip(scroll).take(height).collect();
    f.render_widget(Paragraph::new(shown), inner);
}

/// The columns each button on a line covers, from where to where, and which
/// button it is.
type Spots = Vec<(u16, u16, usize)>;

/// The button row, wrapped to the pane's width, each line with the columns
/// its buttons cover, from the pane's left edge.
///
/// Wrapping is a drawing decision and nothing more: the buttons are one row as
/// far as the cursor is concerned, and left and right walk them however many
/// lines they take to show.
fn button_lines(
    selected: usize,
    on_row: bool,
    width: u16,
    pal: &Palette,
) -> Vec<(Line<'static>, Spots)> {
    let mut lines = Vec::new();
    let mut spans: Vec<Span> = Vec::new();
    let mut at: Spots = Vec::new();
    let mut used = 0usize;
    for (i, button) in GIT_BUTTONS.iter().enumerate() {
        let label = format!(" {} ", button.label());
        let w = label.chars().count() + 1;
        if used + w > width as usize && !spans.is_empty() {
            lines.push((
                Line::from(std::mem::take(&mut spans)),
                std::mem::take(&mut at),
            ));
            used = 0;
        }
        at.push((used as u16, (used + w - 1) as u16, i));
        let style = match (on_row, i == selected) {
            (true, true) => pal.text.add_modifier(Modifier::REVERSED),
            (true, false) => pal.text,
            _ => pal.dim,
        };
        spans.push(Span::styled(label, style));
        spans.push(Span::raw(" "));
        used += w;
    }
    if !spans.is_empty() {
        lines.push((Line::from(spans), at));
    }
    lines
}

/// The right column: the file before, and the file after.
///
/// Both sides are syntax-highlighted, by the grammar the file's own name picks:
/// a diff of a `.rs` file reads as Rust on both sides. The two sides are
/// highlighted separately, because they *are* two different texts: a line that
/// opens a string on the right may not exist on the left at all.
///
/// Only the visible window is parsed for color, resuming from each side's
/// saved highlighting the way the editor does, so paging down a diff of a long
/// file costs what is on screen rather than everything above it.
fn draw_diff(f: &mut Frame, app: &mut App, area: Rect, pal: &Palette) {
    let tab_width = app.config.tab_width;
    let (reading, waiting) = (app.reading_colors, app.input_waiting);
    // Halves, unless the line between them has been dragged elsewhere.
    let (lo, hi) = (area.x + 12, area.right().saturating_sub(12));
    let first = ((f32::from(area.width) * app.diff_share).round() as u16).clamp(
        12.min(area.width),
        area.width.saturating_sub(12).max(12.min(area.width)),
    );
    let halves = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Length(first), Constraint::Min(0)])
        .split(area);
    app.last_dividers.push(Divider::new(
        Moves::Halves { area },
        area,
        true,
        halves[1].x,
        (lo, hi),
    ));
    let highlighter = &app.highlighter;
    let git = &mut app.git;

    let name = git
        .current()
        .map(|(c, staged)| {
            let where_ = if staged { "staged" } else { "not staged" };
            format!(" {}  {} ", c.label(pal.glyphs.arrow), where_)
        })
        .unwrap_or_else(|| " nothing selected ".to_string());

    // The grammar comes from the file being looked at, so both halves agree.
    let syntax = git
        .current()
        .map(|(change, _)| {
            let path = std::path::Path::new(&change.path);
            let first = git
                .diff
                .after
                .iter()
                .chain(git.diff.before.iter())
                .find(|l| l.kind != LineKind::Filler)
                .map(|l| l.text.as_str())
                .unwrap_or("");
            highlighter.syntax_for_path(path, first)
        })
        .unwrap_or_else(|| highlighter.syntax_for_token(""));
    let file = git
        .current()
        .map(|(change, _)| std::path::PathBuf::from(&change.path))
        .unwrap_or_default();

    let mut behind = false;
    for (i, half) in halves.iter().enumerate() {
        let side = if i == 0 { "before" } else { "after" };
        let title = if i == 0 {
            format!(" {side} ")
        } else {
            format!(" {side}:{name}")
        };
        // The border says which half the arrow keys are in, the same way the
        // two panes of the main window do.
        let border = if git.focus == GitFocus::Diff {
            pal.border_focus
        } else {
            pal.border
        };
        let block = Block::default()
            .borders(Borders::ALL)
            .border_set(pal.glyphs.border)
            .border_style(border)
            .title(Line::from(Span::styled(title, pal.dim)));
        let inner = block.inner(*half);
        f.render_widget(block, *half);

        if git.diff.is_empty() {
            let word = match git.current() {
                Some((c, _)) if c.code == Code::Deleted && i == 1 => "the file is gone",
                Some(_) => "no lines changed",
                None => "",
            };
            f.render_widget(
                Paragraph::new(Line::from(Span::styled(format!("  {word}"), pal.dim))),
                inner,
            );
            continue;
        }
        let lines = if i == 0 {
            &git.diff.before
        } else {
            &git.diff.after
        };
        // Syntect wants plain lines; a filler is a line that is not there, and
        // its empty text is the closest true thing to hand it.
        let top = git.diff_scroll;
        let resume = &mut git.diff_highlight[i];
        resume.sync(&file, &syntax.name, None);
        let colored = highlighter.highlight_cached(
            resume,
            &git.diff_text[i],
            syntax,
            top,
            inner.height as usize,
        );
        if reading {
            highlighter.read_on(resume, &git.diff_text[i], syntax, waiting);
        }
        behind |= resume.behind();
        let rows: Vec<Line> = lines
            .iter()
            .enumerate()
            .skip(top)
            .take(inner.height as usize)
            .map(|(n, l)| {
                let pieces = colored.get(n - top);
                diff_line(
                    l,
                    pieces,
                    i == 0,
                    gap_label(lines, n, top, i == 0),
                    pal,
                    tab_width,
                )
            })
            .collect();
        f.render_widget(Paragraph::new(rows), inner);
    }
    // Written back for the same reason every other height is: paging cannot
    // know how tall the columns are until they have been drawn.
    let height = halves[0].height.saturating_sub(2) as usize;
    app.git.diff_height = height;
    app.colors_behind |= behind;
}

/// What to write on the first line of a run of fillers, and nothing on the rest
/// of them.
///
/// A gap on one side is lines the other side has, so the two stay level. Marking
/// every line of it (which is what a `~` per row was) turns a twelve-line
/// addition into a twelve-row column of marks sitting where the file's own text
/// should be, and the eye reads it as content. One quiet line saying how many
/// lines are missing and why says the same thing and then gets out of the way.
///
/// The count is of the whole run, so it is the same number wherever the run is
/// cut off by the top of the pane, and the first row on screen (`top`) says it
/// when the run began above the pane.
fn gap_label(lines: &[DiffLine], n: usize, top: usize, before: bool) -> Option<String> {
    let filler = |i: usize| lines.get(i).is_some_and(|l| l.kind == LineKind::Filler);
    if !filler(n) {
        return None;
    }
    // Mid-run: the line above already said it, if it is on screen.
    if n > top && filler(n - 1) {
        return Some(String::new());
    }
    let start = (0..=n).rev().take_while(|&i| filler(i)).last().unwrap_or(n);
    let run = (start..lines.len()).take_while(|&i| filler(i)).count();
    let plural = if run == 1 { "" } else { "s" };
    // A gap on the left is what the right gained; a gap on the right is what
    // it lost.
    let what = if before { "added" } else { "removed" };
    Some(format!("  {run} line{plural} {what}"))
}

/// One line of one side: a two-character gutter, then the line itself in
/// whatever colors its grammar gives it.
///
/// The gutter is what carries the diff (`-` red on the left, `+` green on the
/// right) because the text is already spoken for by the syntax colors, and a
/// line cannot be two colors at once. Keeping them apart means a change is
/// still obvious at a glance *and* the code still reads as code.
///
/// A filler is the absence of a line rather than an empty one; the run it
/// belongs to says so once, on its first row, see [`gap_label`].
fn diff_line(
    line: &DiffLine,
    pieces: Option<&Vec<Piece>>,
    before: bool,
    gap: Option<String>,
    pal: &Palette,
    tab_width: usize,
) -> Line<'static> {
    if let Some(label) = gap {
        return Line::from(Span::styled(label, pal.dim));
    }
    let gutter = match (line.kind, before) {
        (LineKind::Changed, true) => {
            Span::styled("- ", pal.text.fg(Color::Red).add_modifier(Modifier::BOLD))
        }
        (LineKind::Changed, false) => {
            Span::styled("+ ", pal.text.fg(Color::Green).add_modifier(Modifier::BOLD))
        }
        _ => Span::styled("  ", pal.dim),
    };
    let mut spans = vec![gutter];
    // Counted from the file's own column zero, not from after the `-` or `+`:
    // the gutter is tiny's, and a tab stop belongs to the line as written.
    // Without this a tab-indented file shows every line flat against the
    // margin, which for a Makefile is the whole of its structure.
    let mut col = 0usize;
    match pieces {
        Some(pieces) if !pieces.is_empty() => spans.extend(pieces.iter().map(|(style, text)| {
            let text = tabs::expand(text, tab_width, col).into_owned();
            col += text.width();
            Span::styled(text, *style)
        })),
        // No grammar matched, or the line is past what syntect will parse.
        _ => spans.push(Span::styled(
            tabs::expand(&line.text, tab_width, 0).into_owned(),
            pal.text,
        )),
    }
    Line::from(spans)
}

/// The commit message, over the width of both diff columns.
///
/// Drawn from a real [`Editor`](crate::text::editor::Editor), so it has a
/// cursor you can see and a keyboard that works the way the editor pane's does.
/// The first line is shown apart from the rest because git treats it apart:
/// it is the summary every log and every UI shows on its own. A message taller
/// or wider than the box scrolls to keep the cursor in it, as the editor does.
fn draw_message(f: &mut Frame, app: &mut App, area: Rect, pal: &Palette) {
    let tab_width = app.config.tab_width;
    let staged = app.git.status.staged.len();
    // Put down with Esc, the box stays on screen with its text, and says how
    // to send it or go on with it, the way the list says it does not have
    // the keyboard: a dim border, a dim title, and no cursor.
    let focused = app.git.focus == GitFocus::Message;
    let footer = if focused {
        format!(
            " {} commits | {} puts it down ",
            app.key_name(Action::Save),
            app.key_name(Action::Back)
        )
    } else {
        format!(
            " the commit button sends it | {} to write more ",
            app.key_name(Action::Right)
        )
    };
    let Some(editor) = app.git.message.as_mut() else {
        return;
    };
    let files = if staged == 1 { "file" } else { "files" };
    let block = Block::default()
        .borders(Borders::ALL)
        .border_set(pal.glyphs.border)
        .border_style(if focused {
            pal.border_focus
        } else {
            pal.border
        })
        .title(Line::from(vec![
            Span::styled(
                " commit message ",
                if focused {
                    pal.text.add_modifier(Modifier::BOLD)
                } else {
                    pal.dim
                },
            ),
            Span::styled(format!("for {staged} staged {files} "), pal.dim),
        ]))
        .title_bottom(Line::from(Span::styled(footer, pal.dim)));
    let inner = block.inner(area);
    f.render_widget(block, area);

    // The text starts one column in, so that is one column less to show it.
    let text_w = inner.width.saturating_sub(1) as usize;
    let height = inner.height as usize;
    editor.sync_scroll(text_w.saturating_sub(1), height, tab_width);
    let (scroll_y, scroll_x) = (editor.scroll_y, editor.scroll_x);

    let lines: Vec<Line> = if editor.lines().iter().all(String::is_empty) {
        // An empty box says what it is for rather than sitting there blank.
        vec![Line::from(Span::styled(
            " a line saying what changed, then a blank line, then why",
            pal.dim,
        ))]
    } else {
        editor
            .lines()
            .iter()
            .enumerate()
            .skip(scroll_y)
            .take(height)
            .map(|(n, text)| {
                // The summary line reads as the title it is; the body is body
                // text.
                let style = if n == 0 {
                    pal.text.add_modifier(Modifier::BOLD)
                } else {
                    pal.text
                };
                // Clipped the way the editor clips a line, so a tab or a wide
                // character before the cursor is counted the way it is drawn.
                let mut spans = vec![Span::raw(" ")];
                spans.extend(super::editor::clip_pieces(
                    &[(style, text.clone())],
                    scroll_x,
                    text_w,
                    *pal,
                    tab_width,
                ));
                Line::from(spans)
            })
            .collect()
    };
    f.render_widget(Paragraph::new(lines), inner);

    // The real cursor, so typing looks like typing: counted in columns, the
    // way the text was drawn, so a tab or a wide character before it does
    // not leave it blinking somewhere the text is not.
    let line = editor
        .lines()
        .get(editor.cursor_line)
        .map(String::as_str)
        .unwrap_or("");
    let col = tabs::column(line, editor.cursor_col, tab_width).saturating_sub(scroll_x);
    let row = editor.cursor_line.saturating_sub(scroll_y);
    if focused && col < text_w && row < height {
        f.set_cursor_position((inner.x + 1 + col as u16, inner.y + row as u16));
    }
}

/// The branch map, exactly as `git log --graph` drew it.
fn draw_graph(f: &mut Frame, app: &App, area: Rect, pal: &Palette) {
    let block = Block::default()
        .borders(Borders::ALL)
        .border_set(pal.glyphs.border)
        .border_style(pal.border)
        .title(Line::from(Span::styled(" branches ", pal.dim)));
    let inner = block.inner(area);
    f.render_widget(block, area);
    let lines: Vec<Line> = app
        .git
        .graph
        .iter()
        .take(inner.height as usize)
        .map(|row| {
            // The commit the window is on is the one at the top of the graph;
            // git marks it itself with `HEAD`, so nothing here has to guess.
            let style = if row.contains("HEAD") {
                pal.text
            } else {
                pal.dim
            };
            Line::from(Span::styled(format!(" {row}"), style))
        })
        .collect();
    f.render_widget(Paragraph::new(lines), inner);
}

