//! Knowing when a newer tiny is out, and installing it.
//!
//! # Asking
//!
//! A release is a tag on GitHub, and `…/releases/latest` redirects to the
//! newest one. [`Check::start`] asks for that redirect on a thread of its own
//! (with `curl`, the program the installers already depend on, so tiny carries
//! no HTTP or TLS code of its own) and the event loop collects the answer on
//! its idle tick, the way it collects a git push. Nothing ever waits on it:
//! offline, behind a firewall, or with no `curl`, the answer is simply that
//! there is nothing newer.
//!
//! It asks once per run, and only from a release build with `update_check` on.
//! A `cargo run` is somebody working on tiny, and should not be nagged about
//! the version they are in the middle of writing.
//!
//! # Installing
//!
//! [`install`] runs the platform's installer (the same one-liner the README
//! gives) once tiny has handed the terminal back, so its progress bar and any
//! question it asks reach the person who said yes. It is pointed at the folder
//! the running binary is in, so the update replaces *this* tiny rather than
//! putting a second one somewhere else on the PATH. Then the new binary is
//! asked its version, which is the only reliable way to know the install
//! worked: a pipe from `curl` into `sh` exits cleanly even when the download
//! did not.

use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::mpsc::{Receiver, TryRecvError, channel};

use anyhow::{Context, Result, anyhow};

/// The version of the tiny that is running.
pub fn running() -> &'static str {
    env!("CARGO_PKG_VERSION")
}

/// The GitHub repository releases come from, from `Cargo.toml`, so a fork
/// that changes `repository` checks its own releases, not these.
fn repo() -> &'static str {
    env!("CARGO_PKG_REPOSITORY").trim_end_matches('/')
}

/// Where the installers are served from: the raw files on `main`.
fn raw() -> String {
    format!(
        "{}/main",
        repo().replacen(
            "https://github.com/",
            "https://raw.githubusercontent.com/",
            1
        )
    )
}

/// What the release check found.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Answer {
    /// A newer tiny, by its version.
    Newer(String),
    /// The one running is the newest.
    Newest,
    /// GitHub could not be asked: offline, no `curl`, or no release yet.
    /// Not the same as "nothing newer", and not to be reported as it.
    Unknown,
}

/// The release check, running somewhere else with its answer still to come.
pub struct Check {
    answer: Receiver<Answer>,
}

impl Check {
    /// Ask GitHub for the newest release, on a thread.
    pub fn start() -> Self {
        let (tx, answer) = channel();
        std::thread::spawn(move || {
            let found = match latest() {
                Some(v) if is_newer(&v, running()) => Answer::Newer(v),
                Some(_) => Answer::Newest,
                None => Answer::Unknown,
            };
            // The receiver is gone only if tiny has already quit, and then
            // nobody is left to tell.
            let _ = tx.send(found);
        });
        Self { answer }
    }

    /// The answer, once there is one, and `None` while it is still asking.
    pub fn finished(&self) -> Option<Answer> {
        match self.answer.try_recv() {
            Ok(found) => Some(found),
            Err(TryRecvError::Empty) => None,
            // A thread that panicked has nothing to report either.
            Err(TryRecvError::Disconnected) => Some(Answer::Unknown),
        }
    }
}

/// The newest released version, without the `v`, or `None` if GitHub could
/// not be asked or has no release to name.
///
/// A `HEAD` request: only the redirect is wanted, not the page it points at.
pub fn latest() -> Option<String> {
    let out = Command::new("curl")
        .args(["-fsSI", "--max-time", "8"])
        .arg(format!("{}/releases/latest", repo()))
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    tag_from_headers(&String::from_utf8_lossy(&out.stdout))
        .map(|tag| tag.trim_start_matches('v').to_string())
}

/// The release a `…/releases/latest` redirect points at, from the response
/// headers.
///
/// A repository with no release yet redirects to the release *list* instead,
/// which has no tag in it, and that is a `None` rather than an error.
fn tag_from_headers(headers: &str) -> Option<String> {
    let location = headers.lines().find_map(|line| {
        let (name, value) = line.split_once(':')?;
        name.trim()
            .eq_ignore_ascii_case("location")
            .then(|| value.trim())
    })?;
    let (_, tag) = location.rsplit_once("/releases/tag/")?;
    let tag = tag.trim_end_matches('/');
    (!tag.is_empty()).then(|| tag.to_string())
}

/// `0.4.5` as three numbers. A leading `v` is allowed, and anything after a
/// `-` (a pre-release label) is ignored rather than refused.
fn parse(version: &str) -> Option<(u64, u64, u64)> {
    let core = version.trim().trim_start_matches('v');
    let core = core.split('-').next()?;
    let mut parts = core.split('.').map(|p| p.parse::<u64>().ok());
    let version = (parts.next()??, parts.next()??, parts.next()??);
    parts.next().is_none().then_some(version)
}

/// Whether `latest` is a later version than `current`. Anything that does not
/// read as a version is never newer: an update offered on a misread number
/// would be an update to who knows what.
pub fn is_newer(latest: &str, current: &str) -> bool {
    match (parse(latest), parse(current)) {
        (Some(latest), Some(current)) => latest > current,
        _ => false,
    }
}

/// Install `version` over the running binary, with the terminal already given
/// back. Returns where the new binary is.
///
/// The installer runs in the temp directory, not here: run from inside a tiny
/// checkout, it would build that checkout instead of fetching the release.
///
/// Where tiny lives is read once, before the installer runs, and handed back
/// for [`relaunch`] rather than asked again afterwards: on Linux the answer
/// comes from `/proc/self/exe`, which by then names the file the update just
/// replaced (`…/tiny (deleted)`).
pub fn install(version: &str) -> Result<PathBuf> {
    let exe = std::env::current_exe().context("cannot tell where tiny is installed")?;
    let folder = exe
        .parent()
        .ok_or_else(|| anyhow!("cannot tell where tiny is installed"))?;
    let status = installer()
        .env("TINY_PREFIX", folder)
        // So the installer does not ask again about git and ffmpeg: that was
        // answered when tiny was first installed.
        .env("TINY_UPDATE", "1")
        .current_dir(std::env::temp_dir())
        .status()
        .context("could not start the installer")?;
    let now = Command::new(&exe)
        .arg("--version")
        .output()
        .ok()
        .map(|out| String::from_utf8_lossy(&out.stdout).trim().to_string())
        .unwrap_or_default();
    if now == format!("tiny {version}") {
        return Ok(exe);
    }
    Err(anyhow!(
        "the update did not install{}; {} is still {}",
        if status.success() {
            ""
        } else {
            " (the installer failed; its output is above)"
        },
        exe.display(),
        now.strip_prefix("tiny ").unwrap_or("unchanged")
    ))
}

/// The README's install line for this platform, as a command to run.
fn installer() -> Command {
    if cfg!(windows) {
        let mut cmd = Command::new("powershell");
        // `exit` hands the installer's verdict to the exit code: it sets
        // `LASTEXITCODE` on failure rather than exiting, because piped
        // through `iex` an exit would close the user's own window.
        cmd.args(["-NoProfile", "-ExecutionPolicy", "Bypass", "-Command"])
            .arg(format!(
                "irm {}/install.ps1 | iex; exit $global:LASTEXITCODE",
                raw()
            ));
        cmd
    } else {
        let mut cmd = Command::new("sh");
        cmd.arg("-c")
            .arg(format!("curl -fsSL {}/install.sh | sh", raw()));
        cmd
    }
}

/// Start the freshly installed tiny at `exe` with the arguments this one was
/// given, in place of this one.
///
/// Unix replaces the process outright, so the shell that started tiny is
/// waiting on the new one with nothing in between. Windows has no `exec`, so
/// the old process waits for the new one and leaves with its exit code.
pub fn relaunch(exe: &Path) -> Result<()> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut cmd = Command::new(exe);
    cmd.args(&args);
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;
        // `exec` only comes back if it failed.
        Err(cmd.exec()).context("could not start the new tiny")
    }
    #[cfg(not(unix))]
    {
        let status = cmd.status().context("could not start the new tiny")?;
        std::process::exit(status.code().unwrap_or(0));
    }
}

/// `tiny --update`: the same check and the same install, without a window.
pub fn run_cli() -> Result<()> {
    println!("tiny {}, asking GitHub for a newer one", running());
    let Some(latest) = latest() else {
        println!("no release found (or GitHub could not be reached)");
        return Ok(());
    };
    if !is_newer(&latest, running()) {
        println!("tiny {} is the newest", running());
        return Ok(());
    }
    println!("updating to {latest}\n");
    install(&latest)?;
    println!("\ntiny {latest} installed");
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn versions_compare_as_numbers_not_as_text() {
        assert!(is_newer("0.4.10", "0.4.9"), "10 is more than 9");
        assert!(is_newer("v0.5.0", "0.4.5"));
        assert!(is_newer("1.0.0", "0.99.99"));
        assert!(!is_newer("0.4.5", "0.4.5"), "the same is not newer");
        assert!(
            !is_newer("0.4.4", "0.4.5"),
            "an older release is not offered"
        );
    }

    #[test]
    fn something_that_is_not_a_version_is_never_newer() {
        assert!(!is_newer("latest", "0.4.5"));
        assert!(!is_newer("0.5", "0.4.5"), "two numbers is not a version");
        assert!(!is_newer("0.5.0.1", "0.4.5"), "nor is four");
        assert!(!is_newer("", "0.4.5"));
        assert!(
            is_newer("0.5.0-rc1", "0.4.5"),
            "a pre-release label is read past, not refused"
        );
    }

    #[test]
    fn the_running_version_reads_as_a_version() {
        assert!(parse(running()).is_some(), "{}", running());
    }

    #[test]
    fn the_newest_release_is_read_off_the_redirect() {
        let headers = "HTTP/2 302 \r\n\
                       date: Sat, 10 Oct 2026 22:00:00 GMT\r\n\
                       location: https://github.com/mattsaund/tiny/releases/tag/v0.4.6\r\n\
                       \r\n";
        assert_eq!(tag_from_headers(headers).as_deref(), Some("v0.4.6"));
        // Header names are not case-sensitive, and HTTP/1.1 capitalizes them.
        let headers = "HTTP/1.1 302 Found\nLocation: https://github.com/a/b/releases/tag/v1.2.3\n";
        assert_eq!(tag_from_headers(headers).as_deref(), Some("v1.2.3"));
    }

    #[test]
    fn a_repository_with_no_release_names_none() {
        // GitHub sends the release list instead, which has no tag in it.
        let headers = "HTTP/2 302\r\nlocation: https://github.com/mattsaund/tiny/releases\r\n";
        assert_eq!(tag_from_headers(headers), None);
        assert_eq!(
            tag_from_headers("HTTP/2 200\r\n"),
            None,
            "no redirect at all"
        );
    }

    #[test]
    fn the_installers_come_from_the_same_repository_as_the_releases() {
        assert!(repo().starts_with("https://github.com/"), "{}", repo());
        assert!(
            raw().starts_with("https://raw.githubusercontent.com/"),
            "{}",
            raw()
        );
        assert!(raw().ends_with("/main"));
        let program = installer().get_program().to_string_lossy().into_owned();
        assert!(matches!(program.as_str(), "sh" | "powershell"), "{program}");
    }
}

files.tests/terminals.rs:
//! tiny in a terminal, as near to a real one as a test can get.
//!
//! The rest of the suite draws into ratatui's test backend, which shows what
//! tiny means to put on the screen. These run the binary itself in a
//! pseudo-terminal and read what comes back through a terminal emulator, so
//! they show the rest: that it starts, takes the screen, reads keys spelled
//! the ways terminals spell them, draws at whatever size it is given, follows
//! the window when it changes, and leaves the terminal as it found it.
//!
//! On Windows the pseudo-terminal is a ConPTY, the one Windows Terminal and
//! VS Code are built on, which turns the bytes typed here into the key events
//! a console program reads.
//!
//! # What varies, and why that is enough
//!
//! The terminals people use need a desktop to run, and CI has none. But what
//! tells one terminal from another, to a program, is small: the name it puts
//! in `TERM`, the size of the window, and how it spells each key. Those are
//! what change from test to test below. tmux and GNU screen, which are
//! terminals themselves and need no desktop, are run in the CI workflow.

use std::io::{Read, Write};
use std::num::NonZeroU16;
use std::sync::{Arc, Mutex};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

use portable_pty::{Child, CommandBuilder, MasterPty, PtySize, native_pty_system};

/// How long anything may take to appear. Generous on purpose: a debug build
/// on a busy CI machine starts slowly, and a wait that ends early costs
/// nothing.
const PATIENCE: Duration = Duration::from_secs(30);

/// One tiny, running in a terminal of its own, on a small project of its own.
struct Tiny {
    master: Box<dyn MasterPty + Send>,
    child: Box<dyn Child + Send + Sync>,
    /// Shared with the reader, which answers what the program asks the
    /// terminal, as a terminal does.
    keys: Arc<Mutex<Box<dyn Write + Send>>>,
    screen: Arc<Mutex<vt100::Parser>>,
    reader: Option<JoinHandle<()>>,
    project: tempfile::TempDir,
    /// Where its config lives, so nobody's real one is read or written.
    _config: tempfile::TempDir,
}

fn nz(n: u16) -> NonZeroU16 {
    NonZeroU16::new(n.max(1)).expect("at least one")
}

/// Everything a terminal says about itself, which tiny reads to decide
/// what to draw with: none of it is taken from the terminal running the
/// tests, or what tiny draws would depend on where they run.
const TERMINAL_VARIABLES: &[&str] = &[
    "TERM",
    "COLORTERM",
    "TERM_PROGRAM",
    "NO_COLOR",
    "LANG",
    "LC_ALL",
    "LC_CTYPE",
    "WT_SESSION",
    "TMUX",
    "STY",
    "KITTY_WINDOW_ID",
    "WEZTERM_PANE",
    "KONSOLE_VERSION",
    "VTE_VERSION",
    "ALACRITTY_WINDOW_ID",
    "GHOSTTY_RESOURCES_DIR",
    "TERMINAL_EMULATOR",
    "ConEmuANSI",
];

impl Tiny {
    /// tiny in a modern terminal called `term`, `cols` wide and `rows` high:
    /// UTF-8, and on Windows, Windows Terminal rather than the bare console.
    fn start(term: &str, cols: u16, rows: u16) -> Self {
        let mut env = vec![("TERM", term), ("LANG", "en_US.UTF-8")];
        if cfg!(windows) {
            env.push(("WT_SESSION", "tests"));
        }
        Self::start_in(cols, rows, &env)
    }

    /// tiny in a terminal that says exactly `env` about itself.
    fn start_in(cols: u16, rows: u16, env: &[(&str, &str)]) -> Self {
        Self::start_through(&[], cols, rows, env)
    }

    /// tiny started by `through` (a program and its arguments, to which
    /// tiny and its project are added) rather than by the terminal itself:
    /// a multiplexer, say, which is a terminal of its own in between.
    fn start_through(through: &[String], cols: u16, rows: u16, env: &[(&str, &str)]) -> Self {
        let project = tempfile::tempdir().unwrap();
        let p = project.path();
        std::fs::create_dir(p.join("src")).unwrap();
        std::fs::write(
            p.join("src/main.rs"),
            "fn main() {\n    println!(\"hi\");\n}\n",
        )
        .unwrap();
        std::fs::write(p.join("notes.md"), "# Notes\n\nfirst line\n").unwrap();
        std::fs::write(p.join("README.md"), "# Hello\n\nThe readme.\n").unwrap();

        // `XDG_CONFIG_HOME` comes first wherever tiny looks for its config,
        // Windows included. No update check: nothing here should touch the
        // network.
        let config = tempfile::tempdir().unwrap();
        std::fs::create_dir(config.path().join("tiny")).unwrap();
        std::fs::write(
            config.path().join("tiny/tiny.conf"),
            "update_check = false\n",
        )
        .unwrap();

        let size = PtySize {
            rows,
            cols,
            pixel_width: 0,
            pixel_height: 0,
        };
        let pty = native_pty_system().openpty(size).unwrap();
        let tiny = env!("CARGO_BIN_EXE_tiny");
        let mut cmd = match through.split_first() {
            Some((program, args)) => {
                let mut cmd = CommandBuilder::new(program);
                cmd.args(args);
                cmd.arg(tiny);
                cmd
            }
            None => CommandBuilder::new(tiny),
        };
        cmd.arg(p);
        cmd.cwd(p);
        cmd.env("XDG_CONFIG_HOME", config.path());
        for var in TERMINAL_VARIABLES {
            cmd.env_remove(var);
        }
        for (var, value) in env {
            cmd.env(var, value);
        }
        let child = pty.slave.spawn_command(cmd).unwrap();
        // The child has its own end now. Ours would keep the terminal open
        // after tiny quits, so the reader below would never see the end.
        drop(pty.slave);

        let screen = Arc::new(Mutex::new(vt100::Parser::new(nz(rows), nz(cols), 0)));
        let keys = Arc::new(Mutex::new(pty.master.take_writer().unwrap()));
        let mut from_tiny = pty.master.try_clone_reader().unwrap();
        let into = Arc::clone(&screen);
        let answer = Arc::clone(&keys);
        let reader = std::thread::spawn(move || {
            let mut buf = [0u8; 16 * 1024];
            loop {
                let n = match from_tiny.read(&mut buf) {
                    Ok(0) | Err(_) => break,
                    Ok(n) => n,
                };
                let mut parser = into.lock().unwrap();
                parser.process(&buf[..n]);
                // Where the cursor is, when asked. Windows' ConPTY asks
                // before it shows anything at all, and waits for the answer.
                if buf[..n].windows(4).any(|w| w == b"\x1b[6n") {
                    let (row, col) = parser.screen().cursor_position();
                    let reply = format!("\x1b[{};{}R", row + 1, col + 1);
                    let mut keys = answer.lock().unwrap();
                    let _ = keys.write_all(reply.as_bytes());
                    let _ = keys.flush();
                }
            }
        });
        Self {
            master: pty.master,
            child,
            keys,
            screen,
            reader: Some(reader),
            project,
            _config: config,
        }
    }

    /// Type `bytes` the way a terminal would send them.
    fn send(&mut self, bytes: &str) {
        let mut keys = self.keys.lock().unwrap();
        keys.write_all(bytes.as_bytes()).unwrap();
        keys.flush().unwrap();
    }

    /// The screen as text, a line per row.
    fn text(&self) -> String {
        self.screen.lock().unwrap().screen().contents()
    }

    /// One row of the screen, every column of it.
    fn row(&self, n: u16) -> String {
        let parser = self.screen.lock().unwrap();
        let (_, cols) = parser.screen().size();
        parser
            .screen()
            .rows(0, cols.get())
            .nth(n as usize)
            .unwrap_or_default()
    }

    /// Wait for the screen to satisfy `ok`, and say what it showed if it
    /// never does.
    fn wait_until(&self, what: &str, ok: impl Fn(&Self) -> bool) {
        let start = Instant::now();
        while !ok(self) {
            if start.elapsed() > PATIENCE {
                panic!("never saw {what} on:\n{}", self.text());
            }
            std::thread::sleep(Duration::from_millis(20));
        }
    }

    fn wait_for(&self, text: &str) {
        self.wait_until(&format!("{text:?}"), |t| t.text().contains(text));
    }

    /// Whether the screen comes to show `text` within `limit`, for what is
    /// worth knowing but not worth failing over.
    fn shows_within(&self, text: &str, limit: Duration) -> bool {
        let start = Instant::now();
        while start.elapsed() < limit {
            if self.text().contains(text) {
                return true;
            }
            std::thread::sleep(Duration::from_millis(20));
        }
        false
    }

    /// Where `text` first is on the screen: its column and row, from 0.
    fn find(&self, text: &str) -> Option<(u16, u16)> {
        let rows = self.screen.lock().unwrap().screen().size().0.get();
        (0..rows).find_map(|y| {
            let row = self.row(y);
            row.find(text).map(|i| (row[..i].chars().count() as u16, y))
        })
    }

    /// The mouse, as a terminal reports it once asked to: SGR, counted from
    /// 1. `button` 0 is the left; 32 more is a drag.
    fn mouse(&mut self, button: u8, (x, y): (u16, u16), down: bool) {
        let end = if down { 'M' } else { 'm' };
        self.send(&format!("\x1b[<{button};{};{}{end}", x + 1, y + 1));
    }

    fn click(&mut self, at: (u16, u16)) {
        self.mouse(0, at, true);
        self.mouse(0, at, false);
    }

    /// What the pane beside the browser is titled: whatever the browser's
    /// cursor is on, since the pane follows it.
    fn on(&self) -> String {
        let top = self.row(0);
        // Corners in either set of characters tiny draws with.
        let Some((_, after)) = top
            .split_once("\u{2510}\u{250c} ")
            .or_else(|| top.split_once("++ "))
        else {
            return String::new();
        };
        after
            .split([' ', '\u{2500}'])
            .next()
            .unwrap_or("")
            .to_string()
    }

    /// Press a key and wait for the browser's cursor to land somewhere else.
    fn move_off(&mut self, key: &str) -> String {
        let from = self.on();
        self.send(key);
        self.wait_until(&format!("the cursor to leave {from}"), |t| {
            let now = t.on();
            !now.is_empty() && now != from
        });
        self.on()
    }

    /// The window changes size, as when someone drags its corner.
    fn resize(&mut self, cols: u16, rows: u16) {
        self.screen
            .lock()
            .unwrap()
            .screen_mut()
            .set_size(nz(rows), nz(cols));
        self.master
            .resize(PtySize {
                rows,
                cols,
                pixel_width: 0,
                pixel_height: 0,
            })
            .unwrap();
    }

    /// `Ctrl+Q`, then the terminal as tiny left it, once it has gone.
    fn quit(mut self) -> vt100::Screen {
        self.send("\x11");
        let start = Instant::now();
        let status = loop {
            if let Some(status) = self.child.try_wait().unwrap() {
                break status;
            }
            if start.elapsed() > PATIENCE {
                let _ = self.child.kill();
                panic!("tiny did not quit:\n{}", self.text());
            }
            std::thread::sleep(Duration::from_millis(20));
        };
        assert!(status.success(), "tiny exited {status:?}:\n{}", self.text());
        // Everything it wrote on the way out, before reading the result. A
        // ConPTY keeps its end open until it is closed from this side, so on
        // Windows the reader is not waited for.
        if cfg!(unix)
            && let Some(reader) = self.reader.take()
        {
            let start = Instant::now();
            while !reader.is_finished() && start.elapsed() < PATIENCE {
                std::thread::sleep(Duration::from_millis(20));
            }
        }
        self.screen.lock().unwrap().screen().clone()
    }
}

/// The names terminals give themselves in `TERM`, from the oldest to the
/// newest. tiny reads none of them, so it has to start the same under all.
const TERMS: &[&str] = &[
    "xterm-256color",
    "xterm",
    "vt100",
    "linux",
    "screen-256color",
    "tmux-256color",
    "xterm-kitty",
    "alacritty",
    "wezterm",
    "foot",
    "dumb",
];

#[test]
fn it_starts_and_hands_the_terminal_back_under_every_name() {
    // A ConPTY is one terminal whatever `TERM` says, so there it runs once.
    let terms = if cfg!(windows) { &TERMS[..1] } else { TERMS };
    for term in terms {
        let tiny = Tiny::start(term, 100, 30);
        tiny.wait_for("BROWSER");
        tiny.wait_for("README.md");
        let screen = tiny.quit();
        if cfg!(unix) {
            assert!(
                !screen.alternate_screen(),
                "{term}: the shell's screen is back"
            );
            assert!(!screen.hide_cursor(), "{term}: the cursor is shown again");
            assert_eq!(
                screen.mouse_protocol_mode(),
                vt100::MouseProtocolMode::None,
                "{term}: the mouse is the terminal's again"
            );
        }
    }
}

#[test]
fn it_fills_the_window_at_any_size_and_follows_it_when_it_changes() {
    for (cols, rows) in [(40, 12), (80, 24), (200, 60)] {
        let mut tiny = Tiny::start("xterm-256color", cols, rows);
        // Not a file name: at forty columns the browser shortens them.
        tiny.wait_for("BROWSER");
        let filled = |t: &Tiny, cols: u16| {
            let top = t.row(0);
            top.starts_with('\u{250c}')
                && top.ends_with('\u{2510}')
                && top.chars().count() == cols as usize
        };
        tiny.wait_until(&format!("a frame {cols} wide"), |t| filled(t, cols));
        // Wider and taller, then narrower than it started.
        for (wider, taller) in [(cols + 30, rows + 6), (cols - 10, rows - 2)] {
            tiny.resize(wider, taller);
            tiny.wait_until(&format!("a frame {wider} wide"), |t| filled(t, wider));
            tiny.wait_until("the status line on the last row", |t| {
                t.row(taller - 1).contains("KiB") || t.row(taller - 1).contains(" B")
            });
        }
        tiny.quit();
    }
}

