#[test]
fn the_arrows_work_however_the_terminal_spells_them() {
    let mut tiny = Tiny::start("xterm-256color", 100, 30);
    tiny.wait_for("README.md");
    let root = tiny.on();
    // CSI is what a terminal sends normally, SS3 what it sends once a
    // program has asked for the cursor keys' "application" mode.
    let first = tiny.move_off("\x1b[B");
    let second = tiny.move_off("\x1bOB");
    assert_ne!(first, second);
    assert_eq!(tiny.move_off("\x1bOA"), first);
    assert_eq!(tiny.move_off("\x1b[A"), root);
    tiny.quit();
}

#[test]
fn home_and_end_work_however_the_terminal_spells_them() {
    let mut tiny = Tiny::start("xterm-256color", 100, 30);
    tiny.wait_for("README.md");
    let root = tiny.on();
    // xterm's two spellings, the VT220's, and rxvt's. ConPTY reads the
    // common ones; the others only ever reach a program on Unix.
    let mut pairs = vec![
        ("\x1b[F", "\x1b[H"),
        ("\x1bOF", "\x1bOH"),
        ("\x1b[4~", "\x1b[1~"),
    ];
    if cfg!(unix) {
        pairs.push(("\x1b[8~", "\x1b[7~"));
    }
    let last = tiny.move_off(pairs[0].0);
    assert_eq!(tiny.move_off(pairs[0].1), root);
    for (end, home) in &pairs[1..] {
        assert_eq!(tiny.move_off(end), last, "end as {end:?}");
        assert_eq!(tiny.move_off(home), root, "home as {home:?}");
    }
    tiny.quit();
}

#[test]
fn typing_editing_and_saving_reach_the_file() {
    let mut tiny = Tiny::start("xterm-256color", 100, 30);
    tiny.wait_for("README.md");
    while tiny.on() != "notes.md" {
        tiny.move_off("\x1b[B");
    }
    tiny.send("\r");
    tiny.wait_for("EDIT");
    tiny.send("abcd");
    tiny.wait_for("abcd# Notes");
    // Backspace as nearly every terminal sends it, and as the ones that send
    // Ctrl+H do.
    tiny.send("\x7f");
    tiny.wait_for("abc# Notes");
    if cfg!(unix) {
        tiny.send("\x08");
        tiny.wait_for("ab# Notes");
        tiny.send("c");
    }
    tiny.send("\x13");
    tiny.wait_for("saved");
    let saved = std::fs::read_to_string(tiny.project.path().join("notes.md")).unwrap();
    assert!(saved.starts_with("abc# Notes"), "{saved:?}");
    // Esc on its own, back to the browser: the pane says VIEW again.
    tiny.send("\x1b");
    tiny.wait_for("VIEW");
    tiny.quit();
}

#[test]
fn a_click_puts_the_cursor_where_it_lands_and_a_drag_selects() {
    let mut tiny = Tiny::start("xterm-256color", 100, 30);
    tiny.wait_for("README.md");
    // A row of the browser, and a second click opens it.
    tiny.wait_until("the readme in the browser", |t| {
        t.find("README.md").is_some()
    });
    let readme = tiny.find("README.md").unwrap();
    tiny.click(readme);
    tiny.wait_until("the cursor on the readme", |t| t.on() == "README.md");
    tiny.click(readme);
    tiny.wait_for("EDIT");
    // Into the text: the cursor lands on the `r` of `readme`, line 3.
    let the = tiny.find("The readme").expect("the line on screen");
    tiny.click((the.0 + 4, the.1));
    tiny.wait_for("3:5");
    // And a drag from the `T` over `The readme` selects ten characters. The
    // line may have moved: with the cursor in it the paragraph is raw, and
    // the heading above it formatted, which is a row taller.
    let the = tiny.find("The readme").expect("the line on screen");
    tiny.mouse(0, the, true);
    tiny.mouse(32, (the.0 + 5, the.1), true);
    tiny.mouse(32, (the.0 + 10, the.1), true);
    tiny.mouse(0, (the.0 + 10, the.1), false);
    tiny.wait_for("10 selected");
    tiny.quit();
}

#[test]
fn the_terminal_runs_a_shell_in_the_project() {
    let mut tiny = Tiny::start("xterm-256color", 100, 30);
    tiny.wait_for("README.md");
    tiny.send("\x0f");
    tiny.wait_for("comes back");
    // A word the shell has to put together, so what shows is its answer and
    // not only what was typed: every shell tiny starts joins quotes the same.
    tiny.send("echo ti\"\"ny\"\"shell\r");
    tiny.wait_for("tinyshell");
    // Ctrl+O hands the keyboard back, and the shell stays.
    tiny.send("\x0f");
    tiny.wait_for("still running");
    tiny.send("\x0f");
    tiny.wait_for("comes back");
    tiny.send("exit\r");
    tiny.wait_for("the shell exited");
    tiny.quit();
}

